const g=5,n="su-dia",i="Lịch sử và Địa lí lớp 5",h="internal",t=[{id:"vi-tri-bien-dao",title:"Vị trí, lãnh thổ và biển đảo Việt Nam",lessons:[{id:"sd5-vi-tri-lanh-tho",title:"Vị trí địa lí, lãnh thổ và biểu tượng quốc gia",weeks:[1,2],learn:[{title:"Vị trí địa lí",text:"Việt Nam nằm trên bán đảo Đông Dương, thuộc khu vực Đông Nam Á. Phía bắc giáp Trung Quốc, phía tây giáp Lào và Campuchia, phía đông và phía nam giáp Biển Đông.",example:"🗺️ Bắc: Trung Quốc · Tây: Lào, Campuchia · Đông, Nam: Biển Đông"},{title:"Lãnh thổ",text:"Lãnh thổ Việt Nam gồm vùng đất, vùng biển và vùng trời. Phần đất liền hẹp ngang, kéo dài theo chiều bắc – nam, có hình chữ S.",example:"🇻🇳 Đất liền khoảng 331 nghìn km²"},{title:"Đơn vị hành chính",text:"Từ ngày 1 tháng 7 năm 2025, nước ta có 34 đơn vị hành chính cấp tỉnh, gồm 6 thành phố trực thuộc Trung ương và 28 tỉnh. Thủ đô là Hà Nội.",example:"🏙️ Hà Nội, Huế, Hải Phòng, Đà Nẵng, TP Hồ Chí Minh, Cần Thơ"},{title:"Quốc kì, Quốc huy, Quốc ca",text:"Quốc kì nền đỏ, ở giữa có ngôi sao vàng năm cánh. Quốc ca là bài “Tiến quân ca” của nhạc sĩ Văn Cao. Quốc huy hình tròn, nền đỏ, có ngôi sao vàng, bông lúa và bánh xe răng.",example:"🇻🇳 ⭐ 🌾 ⚙️"}],practice:[{questions:[{id:"sd5-vi-tri-lanh-tho-01",type:"mc",q:"Việt Nam nằm ở khu vực nào của châu Á?",options:["Đông Bắc Á","Đông Nam Á","Nam Á","Tây Á"],answer:1,explain:"Việt Nam nằm trên bán đảo Đông Dương, thuộc khu vực Đông Nam Á.",emoji:"🌏"},{id:"sd5-vi-tri-lanh-tho-02",type:"mc",q:"Phía bắc nước ta giáp với quốc gia nào?",options:["Lào","Campuchia","Thái Lan","Trung Quốc"],answer:3,explain:"Phía bắc Việt Nam giáp Trung Quốc.",emoji:"🧭"},{id:"sd5-vi-tri-lanh-tho-03",type:"tf",q:"Phần đất liền Việt Nam có hình chữ S.",answer:!0,explain:"Phần đất liền nước ta hẹp ngang, kéo dài, giống hình chữ S.",emoji:"🇻🇳"},{id:"sd5-vi-tri-lanh-tho-04",type:"mc",q:"Thủ đô của nước Cộng hòa xã hội chủ nghĩa Việt Nam là:",options:["Huế","Đà Nẵng","Hà Nội","Thành phố Hồ Chí Minh"],answer:2,explain:"Hà Nội là Thủ đô của nước ta.",emoji:"🏛️"},{id:"sd5-vi-tri-lanh-tho-05",type:"mc",q:"Quốc kì Việt Nam có màu gì?",options:["Nền đỏ, sao vàng năm cánh","Nền vàng, sao đỏ năm cánh","Nền xanh, sao vàng","Nền trắng, sao đỏ"],answer:0,explain:"Quốc kì Việt Nam là lá cờ đỏ sao vàng năm cánh.",emoji:"🇻🇳"},{id:"sd5-vi-tri-lanh-tho-06",type:"fill",q:"Quốc ca Việt Nam là bài hát “Tiến quân …”.",answer:["ca"],explain:"Quốc ca là bài “Tiến quân ca”.",emoji:"🎵"},{id:"sd5-vi-tri-lanh-tho-07",type:"mc",q:"Ai là tác giả bài “Tiến quân ca”?",options:["Văn Cao","Phạm Tuyên","Trịnh Công Sơn","Hoàng Vân"],answer:0,explain:"Nhạc sĩ Văn Cao sáng tác bài “Tiến quân ca”.",emoji:"🎼"},{id:"sd5-vi-tri-lanh-tho-08",type:"tf",q:"Phía đông và phía nam nước ta giáp Biển Đông.",answer:!0,explain:"Biển Đông bao bọc phía đông và phía nam phần đất liền nước ta.",emoji:"🌊"},{id:"sd5-vi-tri-lanh-tho-09",type:"multi",q:"Phía tây nước ta giáp những nước nào?",options:["Lào","Trung Quốc","Campuchia","Nhật Bản"],answers:[0,2],explain:"Phía tây Việt Nam giáp Lào và Campuchia.",emoji:"🧭"}]},{questions:[{id:"sd5-vi-tri-lanh-tho-10",type:"multi",q:"Lãnh thổ Việt Nam gồm những bộ phận nào?",options:["Vùng đất","Vùng biển","Vùng trời","Vùng sa mạc"],answers:[0,1,2],explain:"Lãnh thổ gồm vùng đất, vùng biển và vùng trời; nước ta không có sa mạc."},{id:"sd5-vi-tri-lanh-tho-11",type:"number",q:"Từ ngày 1 tháng 7 năm 2025, nước ta có bao nhiêu đơn vị hành chính cấp tỉnh?",answer:34,explain:"Nước ta có 34 đơn vị hành chính cấp tỉnh: 6 thành phố trực thuộc Trung ương và 28 tỉnh.",unit:"đơn vị"},{id:"sd5-vi-tri-lanh-tho-12",type:"number",q:"Nước ta có bao nhiêu thành phố trực thuộc Trung ương?",answer:6,explain:"Đó là Hà Nội, Huế, Hải Phòng, Đà Nẵng, Thành phố Hồ Chí Minh và Cần Thơ.",unit:"thành phố"},{id:"sd5-vi-tri-lanh-tho-13",type:"multi",q:"Những nơi nào là thành phố trực thuộc Trung ương?",options:["Huế","Nghệ An","Cần Thơ","Lạng Sơn","Hải Phòng"],answers:[0,2,4],explain:"Huế, Cần Thơ, Hải Phòng là thành phố trực thuộc Trung ương; Nghệ An, Lạng Sơn là tỉnh."},{id:"sd5-vi-tri-lanh-tho-14",type:"match",q:"Nối mỗi hướng với nơi nước ta tiếp giáp.",pairs:[["Phía bắc","Trung Quốc"],["Phía tây","Lào và Campuchia"],["Phía đông và phía nam","Biển Đông"]],explain:"Bắc giáp Trung Quốc, tây giáp Lào và Campuchia, đông và nam giáp Biển Đông."},{id:"sd5-vi-tri-lanh-tho-15",type:"tf",q:"Phần đất liền nước ta rộng theo chiều đông – tây và ngắn theo chiều bắc – nam.",answer:!1,explain:"Ngược lại: đất liền nước ta hẹp ngang và kéo dài theo chiều bắc – nam."},{id:"sd5-vi-tri-lanh-tho-16",type:"mc",q:"Trên Quốc huy Việt Nam không có hình nào sau đây?",options:["Ngôi sao vàng","Bông lúa","Bánh xe răng","Con rồng"],answer:3,explain:"Quốc huy có ngôi sao vàng, bông lúa, bánh xe răng; không có con rồng.",emoji:"⭐🌾⚙️"},{id:"sd5-vi-tri-lanh-tho-17",type:"tf",q:"Từ ngày 1 tháng 7 năm 2025, chính quyền địa phương nước ta có ba cấp: tỉnh, huyện, xã.",answer:!1,explain:"Từ ngày 1 tháng 7 năm 2025, không còn cấp huyện; chính quyền địa phương chỉ có hai cấp là tỉnh và xã."},{id:"sd5-vi-tri-lanh-tho-18",type:"mc",q:"Vì sao nói Việt Nam là cầu nối giữa đất liền và biển?",options:["Vì nước ta vừa gắn với lục địa, vừa giáp biển","Vì nước ta nằm sâu trong lục địa, xa biển","Vì nước ta là một quần đảo giữa đại dương","Vì nước ta nằm giữa hai sa mạc lớn"],answer:0,explain:"Nước ta vừa gắn liền với lục địa châu Á, vừa mở ra Biển Đông."}]},{questions:[{id:"sd5-vi-tri-lanh-tho-19",type:"mc",q:"Vị trí giáp biển giúp nước ta thuận lợi nhất cho hoạt động nào?",options:["Trồng cây ôn đới như lúa mì, táo","Khai thác băng tuyết quanh năm","Đi lại bằng tàu biển, đánh bắt hải sản","Chăn nuôi lạc đà trên hoang mạc"],answer:2,explain:"Giáp Biển Đông nên nước ta thuận lợi để đi lại bằng tàu biển và đánh bắt hải sản.",emoji:"🚢"},{id:"sd5-vi-tri-lanh-tho-20",type:"tf",q:"Bạn Nam nói: “Hà Nội vừa là Thủ đô, vừa là một thành phố trực thuộc Trung ương.” Bạn Nam nói đúng.",answer:!0,explain:"Hà Nội là Thủ đô và là một trong 6 thành phố trực thuộc Trung ương."},{id:"sd5-vi-tri-lanh-tho-21",type:"mc",q:"Trong lễ chào cờ, khi Quốc ca vang lên, em nên làm gì?",options:["Vừa hát vừa nói chuyện với bạn bên cạnh","Đứng tự do, không cần hát","Ngồi xuống ghế và hát nhỏ theo","Đứng nghiêm, nhìn Quốc kì, hát to, rõ"],answer:3,explain:"Đứng nghiêm, hát Quốc ca là thể hiện lòng yêu nước và tôn trọng Tổ quốc.",emoji:"🇻🇳"},{id:"sd5-vi-tri-lanh-tho-22",type:"mc",q:"Bạn Chi vẽ Quốc kì có ngôi sao bốn cánh. Bạn cần sửa thế nào?",options:["Đổi nền đỏ thành màu xanh","Vẽ lại sao thành năm cánh","Bỏ ngôi sao, chỉ giữ nền đỏ","Vẽ thêm bông lúa quanh sao"],answer:1,explain:"Quốc kì Việt Nam có ngôi sao vàng năm cánh trên nền đỏ."},{id:"sd5-vi-tri-lanh-tho-23",type:"multi",q:"Thành phố Hồ Chí Minh hiện nay được hợp nhất từ những đơn vị nào?",options:["Thành phố Hồ Chí Minh cũ","Bình Dương","Bà Rịa – Vũng Tàu","Cần Thơ","Long An"],answers:[0,1,2],explain:"Thành phố Hồ Chí Minh mới gồm Thành phố Hồ Chí Minh cũ, Bình Dương và Bà Rịa – Vũng Tàu."},{id:"sd5-vi-tri-lanh-tho-24",type:"mc",q:"Tỉnh nào sau đây giữ nguyên, không hợp nhất với tỉnh khác từ ngày 1 tháng 7 năm 2025?",options:["Nghệ An","Bắc Giang","Hà Giang","Yên Bái"],answer:0,explain:"Nghệ An giữ nguyên; Bắc Giang, Hà Giang, Yên Bái đã hợp nhất vào tỉnh khác."},{id:"sd5-vi-tri-lanh-tho-25",type:"tf",q:"Vùng trời phía trên đất liền và vùng biển của nước ta cũng thuộc lãnh thổ Việt Nam.",answer:!0,explain:"Lãnh thổ Việt Nam gồm vùng đất, vùng biển và vùng trời.",emoji:"✈️"},{id:"sd5-vi-tri-lanh-tho-26",type:"mc",q:"Vì sao phần đất liền nước ta có khí hậu và cảnh vật khác nhau giữa miền Bắc và miền Nam?",options:["Vì lãnh thổ kéo dài bắc – nam","Vì nước ta có diện tích rất nhỏ","Vì nước ta không giáp biển","Vì nước ta nằm gần Bắc Cực"],answer:0,explain:"Lãnh thổ kéo dài nên mỗi miền có khí hậu và cảnh vật riêng."}]}],challenge:{questions:[{id:"sd5-vi-tri-lanh-tho-27",type:"match",q:"Nối tỉnh mới với một tỉnh cũ đã hợp nhất vào.",pairs:[["Tuyên Quang","Hà Giang"],["Lào Cai","Yên Bái"],["Thái Nguyên","Bắc Kạn"],["Bắc Ninh","Bắc Giang"]],explain:"Tuyên Quang gồm cả Hà Giang; Lào Cai gồm cả Yên Bái; Thái Nguyên gồm cả Bắc Kạn; Bắc Ninh gồm cả Bắc Giang."},{id:"sd5-vi-tri-lanh-tho-28",type:"multi",q:"Những đơn vị nào giữ nguyên, không sắp xếp từ ngày 1 tháng 7 năm 2025?",options:["Cao Bằng","Hà Tĩnh","Quảng Bình","Điện Biên","Kon Tum"],answers:[0,1,3],explain:"Cao Bằng, Hà Tĩnh, Điện Biên giữ nguyên; Quảng Bình hợp vào Quảng Trị, Kon Tum hợp vào Quảng Ngãi."},{id:"sd5-vi-tri-lanh-tho-29",type:"mc",q:"Tỉnh Quảng Trị hiện nay được hợp nhất từ Quảng Trị và tỉnh nào?",options:["Thừa Thiên Huế","Quảng Bình","Hà Tĩnh","Quảng Nam"],answer:1,explain:"Quảng Trị hiện nay gồm Quảng Trị và Quảng Bình."},{id:"sd5-vi-tri-lanh-tho-30",type:"tf",q:"Từ ngày 1 tháng 7 năm 2025, nước ta có 28 tỉnh.",answer:!0,explain:"Ngoài 6 thành phố trực thuộc Trung ương, nước ta có 28 tỉnh, tổng cộng 34 đơn vị."},{id:"sd5-vi-tri-lanh-tho-31",type:"mc",q:"Thành phố Đà Nẵng hiện nay được hợp nhất từ Đà Nẵng và tỉnh nào?",options:["Quảng Ngãi","Thừa Thiên Huế","Quảng Nam","Bình Định"],answer:2,explain:"Đà Nẵng hiện nay gồm Đà Nẵng và Quảng Nam."},{id:"sd5-vi-tri-lanh-tho-32",type:"multi",q:"Việc làm nào thể hiện sự tôn trọng Quốc kì?",options:["Treo cờ ngay ngắn vào ngày lễ","Dùng cờ để lau bàn","Chào cờ nghiêm trang","Vẽ bậy lên lá cờ"],answers:[0,2],explain:"Treo cờ ngay ngắn và chào cờ nghiêm trang là tôn trọng Quốc kì."}]},summary:["Việt Nam ở khu vực Đông Nam Á, có phần đất liền hình chữ S.","Lãnh thổ gồm vùng đất, vùng biển và vùng trời.","Nước ta có 34 đơn vị hành chính cấp tỉnh, Thủ đô là Hà Nội.","Quốc kì, Quốc huy, Quốc ca là biểu tượng thiêng liêng của Tổ quốc."]},{id:"sd5-bien-dao",title:"Biển, đảo Việt Nam",weeks:[3,4],learn:[{title:"Biển Đông",text:"Vùng biển nước ta là một phần của Biển Đông, rộng lớn, có nhiều đảo và quần đảo.",example:"🌊🏝️"},{title:"Hoàng Sa và Trường Sa",text:"Quần đảo Hoàng Sa thuộc thành phố Đà Nẵng, quần đảo Trường Sa thuộc tỉnh Khánh Hòa. Hai quần đảo này là của Việt Nam.",example:"🇻🇳 Hoàng Sa · Trường Sa"},{title:"Đảo lớn, vịnh đẹp",text:"Phú Quốc là đảo lớn nhất nước ta, nay thuộc tỉnh An Giang. Vịnh Hạ Long ở tỉnh Quảng Ninh là Di sản thiên nhiên thế giới.",example:"🏝️ Phú Quốc · ⛰️🌊 Hạ Long"},{title:"Vai trò của biển",text:"Biển cho ta hải sản, muối, dầu khí, cảnh đẹp để du lịch và đường giao thông. Mỗi người cần giữ biển sạch và bảo vệ chủ quyền biển đảo.",example:"🐟 🧂 ⛽ 🚢"}],practice:[{questions:[{id:"sd5-bien-dao-01",type:"mc",q:"Vùng biển nước ta là một phần của biển nào?",options:["Biển Đỏ","Biển Đông","Biển Đen","Biển Bắc"],answer:1,explain:"Vùng biển Việt Nam là một phần của Biển Đông.",emoji:"🌊"},{id:"sd5-bien-dao-02",type:"tf",q:"Quần đảo Hoàng Sa và quần đảo Trường Sa là của Việt Nam.",answer:!0,explain:"Hoàng Sa và Trường Sa là bộ phận lãnh thổ không thể tách rời của Việt Nam.",emoji:"🇻🇳🏝️"},{id:"sd5-bien-dao-03",type:"mc",q:"Quần đảo Hoàng Sa thuộc địa phương nào?",options:["Tỉnh Khánh Hòa","Thành phố Đà Nẵng","Tỉnh Quảng Ninh","Tỉnh An Giang"],answer:1,explain:"Quần đảo Hoàng Sa thuộc thành phố Đà Nẵng."},{id:"sd5-bien-dao-04",type:"mc",q:"Quần đảo Trường Sa thuộc địa phương nào?",options:["Thành phố Đà Nẵng","Thành phố Hải Phòng","Tỉnh Khánh Hòa","Tỉnh Cà Mau"],answer:2,explain:"Quần đảo Trường Sa thuộc tỉnh Khánh Hòa."},{id:"sd5-bien-dao-05",type:"mc",q:"Đảo lớn nhất nước ta là đảo nào?",options:["Phú Quốc","Lý Sơn","Côn Sơn","Cát Bà"],answer:0,explain:"Phú Quốc là đảo lớn nhất Việt Nam.",emoji:"🏝️"},{id:"sd5-bien-dao-06",type:"mc",q:"Vịnh Hạ Long thuộc tỉnh nào?",options:["Khánh Hòa","Quảng Ngãi","Quảng Ninh","Thanh Hóa"],answer:2,explain:"Vịnh Hạ Long ở tỉnh Quảng Ninh.",emoji:"⛰️🌊"},{id:"sd5-bien-dao-07",type:"multi",q:"Biển đem lại cho chúng ta những gì?",options:["Hải sản","Muối","Dầu khí","Băng tuyết quanh năm"],answers:[0,1,2],explain:"Biển cho ta hải sản, muối, dầu khí; biển nước ta không có băng tuyết.",emoji:"🐟🧂"},{id:"sd5-bien-dao-08",type:"tf",q:"Vịnh Hạ Long được công nhận là Di sản thiên nhiên thế giới.",answer:!0,explain:"Vịnh Hạ Long là Di sản thiên nhiên thế giới, rất nổi tiếng."},{id:"sd5-bien-dao-09",type:"fill",q:"Quần đảo Trường Sa và quần đảo Hoàng … là của Việt Nam.",answer:["Sa"],explain:"Hai quần đảo của Việt Nam trên Biển Đông là Hoàng Sa và Trường Sa."}]},{questions:[{id:"sd5-bien-dao-10",type:"match",q:"Nối đảo, quần đảo, vịnh với địa phương.",pairs:[["Quần đảo Hoàng Sa","Đà Nẵng"],["Quần đảo Trường Sa","Khánh Hòa"],["Vịnh Hạ Long","Quảng Ninh"],["Đảo Phú Quốc","An Giang"]],explain:"Hoàng Sa – Đà Nẵng, Trường Sa – Khánh Hòa, Hạ Long – Quảng Ninh, Phú Quốc – An Giang."},{id:"sd5-bien-dao-11",type:"multi",q:"Những hoạt động kinh tế nào gắn với biển?",options:["Đánh bắt hải sản","Làm muối","Du lịch biển","Trồng chè trên núi cao"],answers:[0,1,2],explain:"Đánh bắt hải sản, làm muối, du lịch biển gắn với biển; trồng chè ở vùng đồi núi."},{id:"sd5-bien-dao-12",type:"tf",q:"Biển chỉ có lợi cho người dân sống ở ven biển, không liên quan đến cả nước.",answer:!1,explain:"Biển cung cấp hải sản, dầu khí, đường giao thông và điều hòa khí hậu cho cả nước."},{id:"sd5-bien-dao-13",type:"mc",q:"Biển có vai trò gì đối với khí hậu nước ta?",options:["Làm khí hậu điều hòa, mát mẻ hơn","Làm khí hậu khô hạn như sa mạc","Làm có tuyết rơi quanh năm","Không có vai trò gì"],answer:0,explain:"Biển cung cấp hơi ẩm, làm khí hậu điều hòa hơn."},{id:"sd5-bien-dao-14",type:"tf",q:"Đảo Phú Quốc nay thuộc tỉnh Cà Mau.",answer:!1,explain:"Phú Quốc trước thuộc Kiên Giang; Kiên Giang hợp nhất vào An Giang nên Phú Quốc nay thuộc tỉnh An Giang."},{id:"sd5-bien-dao-15",type:"mc",q:"Vì sao cần bảo vệ chủ quyền biển, đảo?",options:["Vì biển đảo chỉ để tắm biển và đi chơi","Vì đó là lãnh thổ, có nhiều tài nguyên quý","Vì biển đảo không có người sinh sống","Vì biển đảo không có giá trị kinh tế"],answer:1,explain:"Biển đảo là một phần lãnh thổ, có nhiều tài nguyên và giá trị quốc phòng."},{id:"sd5-bien-dao-16",type:"mc",q:"Tài nguyên khoáng sản quan trọng nào được khai thác ở thềm lục địa nước ta?",options:["Vàng và bạc","Than đá và quặng sắt","Kim cương và đá quý","Dầu mỏ và khí tự nhiên"],answer:3,explain:"Dầu mỏ và khí tự nhiên được khai thác ở vùng biển thềm lục địa phía nam.",emoji:"⛽"},{id:"sd5-bien-dao-17",type:"multi",q:"Đảo nào thuộc vùng biển nước ta?",options:["Cát Bà","Lý Sơn","Côn Sơn","Hải Nam"],answers:[0,1,2],explain:"Cát Bà, Lý Sơn, Côn Sơn là đảo của Việt Nam; Hải Nam là đảo của Trung Quốc."},{id:"sd5-bien-dao-18",type:"tf",q:"Rác thải nhựa trôi ra biển có thể làm hại rùa biển và cá.",answer:!0,explain:"Động vật biển có thể nuốt phải hoặc bị mắc vào rác nhựa.",emoji:"🐢"}]},{questions:[{id:"sd5-bien-dao-19",type:"mc",q:"Đi tắm biển, gia đình Bình nên làm gì với rác?",options:["Chôn rác xuống cát cho sạch","Ném rác xuống nước cho sóng cuốn","Gom rác bỏ đúng nơi quy định","Để rác lại trên bờ cho người dọn"],answer:2,explain:"Gom rác bỏ đúng nơi quy định giúp giữ biển sạch đẹp.",emoji:"🏖️"},{id:"sd5-bien-dao-20",type:"multi",q:"Em có thể làm gì để góp phần bảo vệ biển, đảo quê hương?",options:["Tìm hiểu về biển đảo Việt Nam","Không xả rác ra biển","Viết thư, vẽ tranh gửi các chú bộ đội ở Trường Sa","Bẻ san hô mang về làm kỉ niệm"],answers:[0,1,2],explain:"Tìm hiểu, giữ biển sạch, động viên các chú bộ đội là việc làm tốt; bẻ san hô làm hại biển."},{id:"sd5-bien-dao-21",type:"mc",q:"Một bạn nói: “Trường Sa thuộc tỉnh Quảng Ninh.” Em sửa lại thế nào?",options:["Trường Sa thuộc tỉnh An Giang","Trường Sa thuộc tỉnh Nghệ An","Trường Sa thuộc tỉnh Cà Mau","Trường Sa thuộc tỉnh Khánh Hòa"],answer:3,explain:"Quần đảo Trường Sa thuộc tỉnh Khánh Hòa."},{id:"sd5-bien-dao-22",type:"mc",q:"Vịnh Hạ Long thu hút nhiều khách du lịch chủ yếu vì:",options:["Có băng tuyết phủ trắng quanh năm","Có hàng nghìn đảo đá vôi kì vĩ","Có sa mạc cát rộng mênh mông","Có núi lửa đang phun trào"],answer:1,explain:"Vịnh Hạ Long có rất nhiều đảo đá vôi với hang động đẹp."},{id:"sd5-bien-dao-23",type:"tf",q:"Bảo vệ chủ quyền biển, đảo chỉ là việc của các chú bộ đội hải quân.",answer:!1,explain:"Bảo vệ biển đảo là trách nhiệm của mọi người dân, kể cả học sinh."},{id:"sd5-bien-dao-24",type:"mc",q:"Ngư dân ra khơi đánh bắt cá xa bờ còn góp phần:",options:["Khẳng định sự có mặt của người Việt trên biển","Làm ô nhiễm vùng biển xa bờ","Phá hoại các rạn san hô ngoài khơi","Làm cạn kiệt nước biển"],answer:0,explain:"Ngư dân bám biển vừa làm kinh tế, vừa góp phần bảo vệ chủ quyền biển đảo.",emoji:"🚤"},{id:"sd5-bien-dao-25",type:"mc",q:"Hà sưu tầm ảnh về một quần đảo của Việt Nam thuộc thành phố Đà Nẵng. Đó là quần đảo:",options:["Trường Sa","Côn Sơn","Hoàng Sa","Cát Bà"],answer:2,explain:"Quần đảo Hoàng Sa thuộc thành phố Đà Nẵng."},{id:"sd5-bien-dao-26",type:"tf",q:"Rừng ngập mặn ven biển giúp chắn sóng và là nơi sống của nhiều loài tôm, cá.",answer:!0,explain:"Rừng ngập mặn bảo vệ bờ biển và nuôi dưỡng nhiều loài thủy sản.",emoji:"🌳🦐"}]}],challenge:{questions:[{id:"sd5-bien-dao-27",type:"match",q:"Nối nguồn lợi từ biển với cách sử dụng.",pairs:[["Hải sản","Làm thức ăn"],["Nước biển","Làm muối"],["Dầu khí","Làm nhiên liệu"],["Bãi biển đẹp","Phát triển du lịch"]],explain:"Mỗi nguồn lợi của biển được dùng vào việc khác nhau."},{id:"sd5-bien-dao-28",type:"multi",q:"Những đảo, quần đảo nào thuộc chủ quyền Việt Nam?",options:["Hoàng Sa","Trường Sa","Phú Quốc","Hải Nam","Côn Sơn"],answers:[0,1,2,4],explain:"Hoàng Sa, Trường Sa, Phú Quốc, Côn Sơn là của Việt Nam; Hải Nam thuộc Trung Quốc."},{id:"sd5-bien-dao-29",type:"mc",q:"Vì sao biển, đảo có vai trò quan trọng về quốc phòng?",options:["Vì các đảo có nhiều băng tuyết","Vì là tuyến phòng thủ, bảo vệ đất liền","Vì biển giúp ngăn mưa vào đất liền","Vì các đảo đều không có người ở"],answer:1,explain:"Các đảo như những tiền đồn bảo vệ đất liền từ phía biển."},{id:"sd5-bien-dao-30",type:"tf",q:"Phú Quốc là đảo lớn nhất của nước ta và nay thuộc tỉnh An Giang.",answer:!0,explain:"Phú Quốc là đảo lớn nhất; Kiên Giang đã hợp nhất vào An Giang nên đảo nay thuộc An Giang."},{id:"sd5-bien-dao-31",type:"mc",q:"Hành động nào làm hại biển?",options:["Trồng rừng ngập mặn","Nhặt rác trên bãi biển","Dùng chất nổ để đánh bắt cá","Tuyên truyền giữ biển sạch"],answer:2,explain:"Đánh bắt bằng chất nổ giết cả cá con và phá hủy san hô."},{id:"sd5-bien-dao-32",type:"mc",q:"Quần đảo Trường Sa nằm ở phía nào so với quần đảo Hoàng Sa?",options:["Phía nam","Phía bắc","Phía tây, trên đất liền","Trùng chỗ với Hoàng Sa"],answer:0,explain:"Trên bản đồ, Hoàng Sa ở phía bắc, Trường Sa ở xa hơn về phía nam."}]},summary:["Vùng biển nước ta là một phần của Biển Đông, có nhiều đảo và quần đảo.","Quần đảo Hoàng Sa (Đà Nẵng) và Trường Sa (Khánh Hòa) là của Việt Nam.","Biển đem lại hải sản, muối, dầu khí, du lịch và giao thông; cần giữ biển sạch."]}]},{id:"thien-nhien",title:"Thiên nhiên Việt Nam",lessons:[{id:"sd5-dia-hinh-khoang-san",title:"Địa hình và khoáng sản",weeks:[5,5],learn:[{title:"Đồi núi và đồng bằng",text:"Phần đất liền nước ta có khoảng ba phần tư diện tích là đồi núi, một phần tư là đồng bằng.",example:"⛰️⛰️⛰️ + 🌾"},{title:"Núi cao, đồng bằng lớn",text:"Dãy Hoàng Liên Sơn có đỉnh Phan-xi-păng cao nhất nước ta. Hai đồng bằng lớn là đồng bằng Bắc Bộ và đồng bằng Nam Bộ, do sông ngòi bồi đắp.",example:"🏔️ Phan-xi-păng · 🌾 Bắc Bộ, Nam Bộ"},{title:"Khoáng sản",text:"Nước ta có nhiều loại khoáng sản: than ở Quảng Ninh, a-pa-tít ở Lào Cai, bô-xít ở Tây Nguyên, dầu mỏ và khí tự nhiên ở vùng biển phía nam.",example:"⚫ than · ⛽ dầu khí"}],practice:[{questions:[{id:"sd5-dia-hinh-khoang-san-01",type:"mc",q:"Dạng địa hình nào chiếm phần lớn diện tích đất liền nước ta?",options:["Đồng bằng","Sa mạc","Đồi núi","Băng tuyết"],answer:2,explain:"Đồi núi chiếm khoảng ba phần tư diện tích đất liền.",emoji:"⛰️"},{id:"sd5-dia-hinh-khoang-san-02",type:"mc",q:"Đỉnh núi cao nhất nước ta là:",options:["Phan-xi-păng","Bà Đen","Tây Côn Lĩnh","Bạch Mã"],answer:0,explain:"Phan-xi-păng trên dãy Hoàng Liên Sơn là đỉnh cao nhất Việt Nam.",emoji:"🏔️"},{id:"sd5-dia-hinh-khoang-san-03",type:"tf",q:"Đồng bằng chiếm khoảng ba phần tư diện tích đất liền nước ta.",answer:!1,explain:"Đồng bằng chỉ chiếm khoảng một phần tư; đồi núi chiếm khoảng ba phần tư."},{id:"sd5-dia-hinh-khoang-san-04",type:"multi",q:"Hai đồng bằng lớn nhất nước ta là:",options:["Đồng bằng Bắc Bộ","Đồng bằng sông Đà","Đồng bằng Nam Bộ","Đồng bằng Tây Nguyên"],answers:[0,2],explain:"Hai đồng bằng lớn là đồng bằng Bắc Bộ và đồng bằng Nam Bộ.",emoji:"🌾"},{id:"sd5-dia-hinh-khoang-san-05",type:"mc",q:"Than đá được khai thác nhiều nhất ở tỉnh nào?",options:["Lào Cai","Cà Mau","Đồng Tháp","Quảng Ninh"],answer:3,explain:"Quảng Ninh là nơi có nhiều mỏ than nhất nước ta.",emoji:"⚫"},{id:"sd5-dia-hinh-khoang-san-06",type:"fill",q:"Đỉnh Phan-xi-păng nằm trên dãy núi Hoàng … Sơn.",answer:["Liên"],explain:"Phan-xi-păng nằm trên dãy Hoàng Liên Sơn."},{id:"sd5-dia-hinh-khoang-san-07",type:"tf",q:"Dầu mỏ và khí tự nhiên được khai thác chủ yếu ở vùng biển phía nam nước ta.",answer:!0,explain:"Các mỏ dầu khí lớn nằm ở thềm lục địa phía nam.",emoji:"⛽"},{id:"sd5-dia-hinh-khoang-san-08",type:"mc",q:"A-pa-tít, nguyên liệu để làm phân bón, có nhiều ở tỉnh nào?",options:["An Giang","Quảng Ninh","Lào Cai","Thanh Hóa"],answer:2,explain:"Mỏ a-pa-tít lớn nằm ở tỉnh Lào Cai."},{id:"sd5-dia-hinh-khoang-san-09",type:"tf",q:"Nước ta có nhiều sa mạc rộng lớn.",answer:!1,explain:"Nước ta không có sa mạc; địa hình chủ yếu là đồi núi và đồng bằng."}]},{questions:[{id:"sd5-dia-hinh-khoang-san-10",type:"match",q:"Nối khoáng sản với nơi có nhiều.",pairs:[["Than","Quảng Ninh"],["A-pa-tít","Lào Cai"],["Bô-xít","Tây Nguyên"],["Dầu mỏ","Vùng biển phía nam"]],explain:"Than – Quảng Ninh, a-pa-tít – Lào Cai, bô-xít – Tây Nguyên, dầu mỏ – biển phía nam."},{id:"sd5-dia-hinh-khoang-san-11",type:"mc",q:"Đồng bằng Bắc Bộ do những sông nào bồi đắp?",options:["Sông Đà và sông Mê Công","Sông Mê Công và sông Đồng Nai","Sông Mã và sông Cả","Sông Hồng và sông Thái Bình"],answer:3,explain:"Đồng bằng Bắc Bộ do sông Hồng và sông Thái Bình bồi đắp."},{id:"sd5-dia-hinh-khoang-san-12",type:"mc",q:"Đồng bằng Nam Bộ do những sông nào bồi đắp?",options:["Sông Hồng và sông Thái Bình","Sông Mê Công và sông Đồng Nai","Sông Gianh và sông Hương","Sông Lô và sông Chảy"],answer:1,explain:"Đồng bằng Nam Bộ do sông Mê Công và sông Đồng Nai bồi đắp."},{id:"sd5-dia-hinh-khoang-san-13",type:"tf",q:"Các đồng bằng ven biển miền Trung rộng lớn hơn đồng bằng Nam Bộ.",answer:!1,explain:"Đồng bằng ven biển miền Trung nhỏ hẹp; đồng bằng Nam Bộ lớn nhất nước ta."},{id:"sd5-dia-hinh-khoang-san-14",type:"mc",q:"Vì sao đồng bằng là nơi trồng lúa chủ yếu?",options:["Vì đất bằng phẳng, màu mỡ, nhiều nước","Vì có nhiều băng tuyết để lấy nước","Vì có nhiều núi đá vôi cao","Vì không có sông nên ít lũ"],answer:0,explain:"Đất phù sa bằng phẳng và nhiều nước rất hợp để trồng lúa.",emoji:"🌾"},{id:"sd5-dia-hinh-khoang-san-15",type:"tf",q:"Khoáng sản có thể dùng mãi không bao giờ hết.",answer:!1,explain:"Khoáng sản hình thành trong thời gian rất dài, khai thác mãi sẽ cạn."},{id:"sd5-dia-hinh-khoang-san-16",type:"multi",q:"Vùng đồi núi nước ta thuận lợi cho những hoạt động nào?",options:["Trồng cây công nghiệp như chè, cà phê","Trồng và bảo vệ rừng","Đánh bắt cá biển xa bờ","Phát triển thủy điện"],answers:[0,1,3],explain:"Vùng đồi núi hợp trồng chè, cà phê, rừng và có sông dốc để làm thủy điện."},{id:"sd5-dia-hinh-khoang-san-17",type:"mc",q:"Bô-xít, nguyên liệu để sản xuất nhôm, có nhiều ở vùng nào?",options:["Đồng bằng Bắc Bộ","Vùng biển phía nam","Tây Nguyên","Ven biển miền Trung"],answer:2,explain:"Tây Nguyên có trữ lượng bô-xít lớn."},{id:"sd5-dia-hinh-khoang-san-18",type:"mc",q:"Phần lớn đồi núi nước ta là:",options:["Núi rất cao, phủ tuyết","Cồn cát","Núi lửa","Đồi núi thấp"],answer:3,explain:"Phần lớn diện tích đồi núi nước ta là đồi núi thấp."}]},{questions:[{id:"sd5-dia-hinh-khoang-san-19",type:"mc",q:"Lan muốn ngắm biển mây và lên đỉnh núi cao nhất nước ta. Lan nên đến tỉnh nào?",options:["Cà Mau","Lào Cai","Cần Thơ","Vĩnh Long"],answer:1,explain:"Đỉnh Phan-xi-păng thuộc dãy Hoàng Liên Sơn, ở tỉnh Lào Cai.",emoji:"🏔️"},{id:"sd5-dia-hinh-khoang-san-20",type:"multi",q:"Việc làm nào góp phần sử dụng khoáng sản tiết kiệm?",options:["Tắt bếp ga khi không dùng","Đi xe đạp hoặc đi bộ khi đi gần","Để đèn sáng suốt đêm khi không cần","Tái chế lon nhôm"],answers:[0,1,3],explain:"Tiết kiệm nhiên liệu và tái chế giúp đỡ phải khai thác khoáng sản."},{id:"sd5-dia-hinh-khoang-san-21",type:"tf",q:"Khai thác khoáng sản bừa bãi có thể làm ô nhiễm môi trường và gây sạt lở đất.",answer:!0,explain:"Khai thác bừa bãi phá rừng, làm bẩn nước và gây sạt lở."},{id:"sd5-dia-hinh-khoang-san-22",type:"mc",q:"Vì sao giao thông ở vùng núi khó khăn hơn ở đồng bằng?",options:["Vì vùng núi có nhiều sông lớn chảy êm","Vì vùng núi có nhiều sa mạc","Vì địa hình cao, dốc, bị chia cắt","Vì vùng núi không có mưa"],answer:2,explain:"Núi cao, dốc, nhiều đèo khiến làm đường và đi lại khó khăn."},{id:"sd5-dia-hinh-khoang-san-23",type:"mc",q:"Đồng bằng Nam Bộ có diện tích:",options:["Lớn nhất nước ta","Nhỏ nhất nước ta","Bằng đồng bằng ven biển miền Trung","Toàn là đồi núi"],answer:0,explain:"Đồng bằng Nam Bộ là đồng bằng lớn nhất nước ta."},{id:"sd5-dia-hinh-khoang-san-24",type:"tf",q:"Bạn Dũng nói: “Ở nước ta, đồng bằng rộng hơn đồi núi.” Bạn Dũng nói đúng.",answer:!1,explain:"Đồi núi chiếm khoảng ba phần tư, rộng hơn đồng bằng nhiều."},{id:"sd5-dia-hinh-khoang-san-25",type:"mc",q:"Ở vùng đồi núi, mùa mưa lớn dễ xảy ra hiện tượng nào?",options:["Sóng thần","Lũ quét, sạt lở","Tuyết lở","Bão cát sa mạc"],answer:1,explain:"Đất dốc gặp mưa lớn dễ bị lũ quét và sạt lở."},{id:"sd5-dia-hinh-khoang-san-26",type:"mc",q:"Khoáng sản nào được dùng làm nhiên liệu cho nhà máy nhiệt điện?",options:["A-pa-tít","Bô-xít","Đá vôi","Than"],answer:3,explain:"Than được đốt để chạy nhà máy nhiệt điện."}]}],challenge:{questions:[{id:"sd5-dia-hinh-khoang-san-27",type:"match",q:"Nối đồng bằng với sông bồi đắp.",pairs:[["Đồng bằng Bắc Bộ","Sông Hồng"],["Đồng bằng Nam Bộ","Sông Mê Công"],["Đồng bằng Thanh Hóa","Sông Mã"]],explain:"Sông Hồng bồi đắp đồng bằng Bắc Bộ, sông Mê Công bồi đắp đồng bằng Nam Bộ, sông Mã bồi đắp đồng bằng Thanh Hóa."},{id:"sd5-dia-hinh-khoang-san-28",type:"multi",q:"Phát biểu nào đúng về địa hình nước ta?",options:["Đồi núi chiếm phần lớn diện tích","Đồng bằng ven biển miền Trung nhỏ hẹp","Nước ta không có đồng bằng","Phan-xi-păng là đỉnh cao nhất"],answers:[0,1,3],explain:"Nước ta có hai đồng bằng lớn, nên ý “không có đồng bằng” là sai."},{id:"sd5-dia-hinh-khoang-san-29",type:"tf",q:"Than, dầu mỏ, a-pa-tít đều là khoáng sản của nước ta.",answer:!0,explain:"Đó là những khoáng sản quan trọng đang được khai thác ở nước ta."},{id:"sd5-dia-hinh-khoang-san-30",type:"mc",q:"Vì sao cần trồng rừng trên đồi núi trọc?",options:["Để có thêm đất làm sa mạc","Để có nhiều băng tuyết hơn","Để đồi núi cao thêm mỗi năm","Để giữ đất, giảm lũ quét, sạt lở"],answer:3,explain:"Rễ cây giữ đất, rừng giúp giảm lũ quét và sạt lở.",emoji:"🌳"},{id:"sd5-dia-hinh-khoang-san-31",type:"mc",q:"Phúc ở Cần Thơ, quê bạn nằm trên đồng bằng nào?",options:["Đồng bằng Bắc Bộ","Đồng bằng Nam Bộ","Đồng bằng Thanh Hóa","Cao nguyên"],answer:1,explain:"Cần Thơ nằm giữa đồng bằng Nam Bộ."},{id:"sd5-dia-hinh-khoang-san-32",type:"tf",q:"Phần lớn đồi núi nước ta là núi cao trên 2000 mét.",answer:!1,explain:"Phần lớn đồi núi nước ta là đồi núi thấp."}]},summary:["Đồi núi chiếm khoảng ba phần tư, đồng bằng khoảng một phần tư diện tích đất liền.","Phan-xi-păng trên dãy Hoàng Liên Sơn là đỉnh núi cao nhất nước ta.","Khoáng sản có hạn, cần khai thác tiết kiệm và hợp lí."]},{id:"sd5-khi-hau",title:"Khí hậu Việt Nam",weeks:[6,6],learn:[{title:"Nhiệt đới gió mùa",text:"Nước ta có khí hậu nhiệt đới gió mùa: nhiệt độ cao, mưa nhiều, gió và mưa thay đổi theo mùa.",example:"☀️🌧️🌬️"},{title:"Hai miền khí hậu",text:"Dãy Bạch Mã là ranh giới khí hậu. Miền Bắc có mùa đông lạnh và mùa hạ nóng, mưa nhiều. Miền Nam nóng quanh năm, có mùa mưa và mùa khô.",example:"❄️ Bắc · ☀️ Nam"},{title:"Thiên tai",text:"Khí hậu cũng gây ra thiên tai như bão, lũ lụt, hạn hán, rét đậm. Cần theo dõi dự báo thời tiết và phòng tránh.",example:"🌀 bão · 🌊 lũ · 🏜️ hạn"}],practice:[{questions:[{id:"sd5-khi-hau-01",type:"mc",q:"Nước ta có khí hậu gì?",options:["Nhiệt đới gió mùa","Ôn đới lạnh","Hàn đới băng giá","Hoang mạc khô"],answer:0,explain:"Việt Nam có khí hậu nhiệt đới gió mùa.",emoji:"☀️🌧️"},{id:"sd5-khi-hau-02",type:"tf",q:"Khí hậu nước ta có nhiệt độ cao và mưa nhiều.",answer:!0,explain:"Đó là đặc điểm của khí hậu nhiệt đới gió mùa."},{id:"sd5-khi-hau-03",type:"mc",q:"Dãy núi nào là ranh giới khí hậu giữa miền Bắc và miền Nam?",options:["Bạch Mã","Hoàng Liên Sơn","Trường Sơn Nam","Tam Đảo"],answer:0,explain:"Dãy Bạch Mã là ranh giới khí hậu giữa hai miền."},{id:"sd5-khi-hau-04",type:"mc",q:"Miền nào nước ta có mùa đông lạnh?",options:["Chỉ các đảo","Miền Nam","Cả hai miền đều không","Miền Bắc"],answer:3,explain:"Miền Bắc có mùa đông lạnh; miền Nam nóng quanh năm.",emoji:"❄️"},{id:"sd5-khi-hau-05",type:"tf",q:"Miền Nam nước ta nóng quanh năm, có mùa mưa và mùa khô.",answer:!0,explain:"Miền Nam nóng quanh năm và chia hai mùa: mưa và khô.",emoji:"☀️"},{id:"sd5-khi-hau-06",type:"multi",q:"Những thiên tai nào thường xảy ra ở nước ta?",options:["Bão","Lũ lụt","Hạn hán","Bão tuyết lớn ở đồng bằng"],answers:[0,1,2],explain:"Bão, lũ lụt, hạn hán thường xảy ra; đồng bằng nước ta không có bão tuyết.",emoji:"🌀"},{id:"sd5-khi-hau-07",type:"fill",q:"Khí hậu nước ta là khí hậu nhiệt đới … mùa.",answer:["gió"],explain:"Khí hậu nước ta là nhiệt đới gió mùa."},{id:"sd5-khi-hau-08",type:"tf",q:"Ở nước ta, gió và mưa không thay đổi theo mùa.",answer:!1,explain:"Gió và mưa thay đổi theo mùa – đó là đặc điểm “gió mùa”."},{id:"sd5-khi-hau-09",type:"mc",q:"Khi có bão, gia đình nên làm gì?",options:["Ra biển đánh cá như mọi ngày","Đi chơi ngoài trời ngắm gió","Chằng chống nhà, ở nơi an toàn","Trèo lên cây cao để quan sát"],answer:2,explain:"Chằng chống nhà cửa và ở nơi an toàn giúp tránh nguy hiểm khi bão."}]},{questions:[{id:"sd5-khi-hau-10",type:"match",q:"Nối miền khí hậu với đặc điểm.",pairs:[["Miền Bắc","Có mùa đông lạnh"],["Miền Nam","Nóng quanh năm"],["Dãy Bạch Mã","Ranh giới khí hậu"]],explain:"Miền Bắc có mùa đông lạnh, miền Nam nóng quanh năm, dãy Bạch Mã là ranh giới."},{id:"sd5-khi-hau-11",type:"mc",q:"Khí hậu nóng, mưa nhiều giúp cây cối:",options:["Rụng hết lá quanh năm","Xanh tốt quanh năm","Không mọc được","Chỉ sống ở sa mạc"],answer:1,explain:"Nắng và mưa nhiều giúp cây cối phát triển xanh tốt.",emoji:"🌳"},{id:"sd5-khi-hau-12",type:"tf",q:"Khí hậu nóng ẩm cũng làm nông sản dễ bị ẩm mốc và sâu bệnh phát triển.",answer:!0,explain:"Nóng ẩm có lợi cho cây nhưng cũng có hại vì sâu bệnh, nấm mốc phát triển."},{id:"sd5-khi-hau-13",type:"mc",q:"Vào mùa đông, miền Bắc nước ta chịu ảnh hưởng của loại gió nào gây lạnh?",options:["Gió Lào","Gió mùa đông bắc","Gió mùa tây nam","Gió biển"],answer:1,explain:"Gió mùa đông bắc đem không khí lạnh đến miền Bắc.",emoji:"🌬️"},{id:"sd5-khi-hau-14",type:"multi",q:"Khí hậu nhiệt đới gió mùa có thuận lợi gì cho nông nghiệp?",options:["Cây trồng phát triển quanh năm","Có thể trồng nhiều vụ lúa","Không bao giờ có thiên tai","Trồng được nhiều loại cây"],answers:[0,1,3],explain:"Nóng, mưa nhiều giúp trồng nhiều vụ, nhiều loại cây; nhưng vẫn có thiên tai."},{id:"sd5-khi-hau-15",type:"mc",q:"Khó khăn lớn nhất do khí hậu gây ra cho đời sống và sản xuất là:",options:["Bão, lũ lụt, hạn hán","Có quá nhiều tuyết","Không có mưa","Không có ánh nắng"],answer:0,explain:"Bão, lũ lụt, hạn hán gây thiệt hại về người và tài sản."},{id:"sd5-khi-hau-16",type:"tf",q:"Tháng 1, Thành phố Hồ Chí Minh thường lạnh hơn Hà Nội.",answer:!1,explain:"Tháng 1 miền Bắc đang mùa đông nên Hà Nội lạnh hơn; Thành phố Hồ Chí Minh nóng quanh năm."},{id:"sd5-khi-hau-17",type:"mc",q:"Sa Pa ở vùng núi cao tỉnh Lào Cai có khí hậu mát mẻ chủ yếu vì:",options:["Nằm trên núi cao","Ở gần biển","Ở cực nam đất nước","Không có gió"],answer:0,explain:"Càng lên cao, nhiệt độ càng giảm, nên vùng núi cao mát mẻ.",emoji:"🏔️"},{id:"sd5-khi-hau-18",type:"mc",q:"Rét đậm, rét hại thường xảy ra ở đâu?",options:["Đồng bằng Nam Bộ","Vùng núi phía bắc","Quần đảo Trường Sa","Mũi Cà Mau"],answer:1,explain:"Vùng núi phía bắc có mùa đông lạnh nhất nước ta."}]},{questions:[{id:"sd5-khi-hau-19",type:"mc",q:"Gia đình Minh định đi Hà Nội vào tháng 1. Minh nên chuẩn bị gì?",options:["Chỉ mang áo cộc tay","Không cần chuẩn bị gì","Mang áo phao bơi","Mang thêm áo ấm"],answer:3,explain:"Tháng 1 miền Bắc đang mùa đông lạnh nên cần áo ấm.",emoji:"🧥"},{id:"sd5-khi-hau-20",type:"multi",q:"Để phòng tránh lũ lụt, chúng ta nên làm gì?",options:["Theo dõi tin dự báo thời tiết","Trồng và bảo vệ rừng đầu nguồn","Chặt phá rừng","Chuẩn bị đồ dùng cần thiết khi có cảnh báo"],answers:[0,1,3],explain:"Theo dõi dự báo, bảo vệ rừng và chuẩn bị trước giúp giảm thiệt hại do lũ."},{id:"sd5-khi-hau-21",type:"tf",q:"Khi trời mưa to, sấm sét, em nên trú dưới gốc cây cao ngoài đồng.",answer:!1,explain:"Cây cao dễ bị sét đánh; nên trú trong nhà an toàn.",emoji:"⚡"},{id:"sd5-khi-hau-22",type:"mc",q:"Vì sao nông dân miền Nam thường chọn mùa mưa để cấy lúa nhiều?",options:["Vì có đủ nước cho lúa","Vì mùa mưa trời lạnh hơn","Vì mùa mưa có tuyết rơi","Vì mùa mưa không có nắng"],answer:0,explain:"Lúa cần nhiều nước, mùa mưa có đủ nước cho đồng ruộng.",emoji:"🌾"},{id:"sd5-khi-hau-23",type:"mc",q:"Tùng ở Cà Mau, Vy ở Lạng Sơn. Bạn nào có thể thấy sương giá vào mùa đông?",options:["Tùng","Cả hai bạn","Vy","Không bạn nào"],answer:2,explain:"Lạng Sơn ở vùng núi phía bắc có mùa đông lạnh, có thể có sương giá."},{id:"sd5-khi-hau-24",type:"tf",q:"Bão thường đổ bộ vào vùng ven biển nước ta, nhất là vùng ven biển miền Trung.",answer:!0,explain:"Ven biển miền Trung là nơi thường chịu ảnh hưởng của bão."},{id:"sd5-khi-hau-25",type:"mc",q:"Hạn hán kéo dài gây ra khó khăn nào?",options:["Ngập lụt nhà cửa, ruộng vườn","Có quá nhiều cá trong ao hồ","Tuyết rơi dày trên đồng ruộng","Thiếu nước sinh hoạt, tưới cây"],answer:3,explain:"Hạn hán làm thiếu nước, cây trồng khô héo."},{id:"sd5-khi-hau-26",type:"mc",q:"Nước ta trồng được nhiều loại rau quả nhiệt đới như xoài, chuối nhờ:",options:["Khí hậu lạnh giá","Khí hậu nóng ẩm","Có sa mạc","Có băng tuyết"],answer:1,explain:"Khí hậu nóng ẩm thích hợp cho cây trái nhiệt đới.",emoji:"🥭🍌"}]}],challenge:{questions:[{id:"sd5-khi-hau-27",type:"match",q:"Nối thiên tai với cách phòng tránh.",pairs:[["Bão","Chằng chống nhà cửa"],["Lũ lụt","Di chuyển đến nơi cao, an toàn"],["Hạn hán","Tích trữ và tiết kiệm nước"],["Rét đậm","Giữ ấm cơ thể"]],explain:"Mỗi loại thiên tai có cách phòng tránh phù hợp."},{id:"sd5-khi-hau-28",type:"multi",q:"Phát biểu nào đúng về khí hậu nước ta?",options:["Có sự khác nhau giữa miền Bắc và miền Nam","Gió và mưa thay đổi theo mùa","Lạnh quanh năm","Mưa nhiều"],answers:[0,1,3],explain:"Khí hậu nước ta nóng, mưa nhiều, thay đổi theo mùa và khác nhau giữa hai miền."},{id:"sd5-khi-hau-29",type:"tf",q:"Dãy Bạch Mã nằm giữa Hà Nội và Lạng Sơn.",answer:!1,explain:"Dãy Bạch Mã nằm giữa Huế và Đà Nẵng."},{id:"sd5-khi-hau-30",type:"mc",q:"Vì sao miền Bắc có mùa đông lạnh còn miền Nam thì không?",options:["Vì miền Nam có nhiều núi cao hơn miền Bắc","Vì miền Bắc chịu ảnh hưởng của gió mùa đông bắc","Vì miền Bắc ở gần xích đạo hơn","Vì miền Nam không giáp biển"],answer:1,explain:"Gió mùa đông bắc lạnh tràn về miền Bắc, còn miền Nam gần xích đạo hơn nên nóng quanh năm."},{id:"sd5-khi-hau-31",type:"mc",q:"Lúc có cảnh báo lũ quét ở vùng núi, việc nào đúng?",options:["Lội qua suối để kịp đến trường","Ở lại dưới chân đồi cho mát","Đứng sát bờ sông để xem nước","Không lội suối, tránh xa sườn đồi"],answer:3,explain:"Không lội suối, tránh xa nơi dễ sạt lở giúp giữ an toàn khi có lũ quét."},{id:"sd5-khi-hau-32",type:"tf",q:"Theo dõi bản tin dự báo thời tiết giúp người dân chủ động phòng tránh bão.",answer:!0,explain:"Biết trước đường đi của bão, người dân kịp chằng chống nhà cửa, đưa tàu thuyền vào nơi tránh trú."}]},summary:["Khí hậu nước ta là khí hậu nhiệt đới gió mùa, nóng và mưa nhiều.","Dãy Bạch Mã chia hai miền: miền Bắc có mùa đông lạnh, miền Nam nóng quanh năm.","Cần chủ động phòng tránh bão, lũ, hạn hán."]},{id:"sd5-song-ngoi",title:"Sông ngòi Việt Nam",weeks:[7,7],learn:[{title:"Mạng lưới sông dày đặc",text:"Nước ta có rất nhiều sông ngòi, phần lớn là sông nhỏ. Sông có nhiều nước và nhiều phù sa.",example:"🏞️ sông Hồng · sông Mê Công"},{title:"Mùa lũ, mùa cạn",text:"Lượng nước sông thay đổi theo mùa: mùa mưa nước dâng cao (mùa lũ), mùa khô nước ít (mùa cạn).",example:"🌧️⬆️ · ☀️⬇️"},{title:"Vai trò của sông",text:"Sông bồi đắp đồng bằng, cung cấp nước, tôm cá, là đường giao thông và nguồn thủy điện như nhà máy thủy điện Sơn La trên sông Đà.",example:"🚤 🐟 ⚡"}],practice:[{questions:[{id:"sd5-song-ngoi-01",type:"tf",q:"Nước ta có mạng lưới sông ngòi dày đặc.",answer:!0,explain:"Nước ta có rất nhiều sông ngòi, phân bố khắp cả nước.",emoji:"🏞️"},{id:"sd5-song-ngoi-02",type:"mc",q:"Sông ngòi nước ta có đặc điểm nào?",options:["Nhiều nước, nhiều phù sa","Ít nước, không có phù sa","Đóng băng vào mùa đông","Chỉ chảy vào mùa khô"],answer:0,explain:"Sông ngòi nước ta nhiều nước và mang nhiều phù sa."},{id:"sd5-song-ngoi-03",type:"mc",q:"Sông nào bồi đắp nên đồng bằng Bắc Bộ?",options:["Sông Mê Công","Sông Đồng Nai","Sông Hồng","Sông Hương"],answer:2,explain:"Sông Hồng cùng sông Thái Bình bồi đắp đồng bằng Bắc Bộ."},{id:"sd5-song-ngoi-04",type:"mc",q:"Đoạn sông Mê Công chảy qua nước ta còn gọi là sông gì?",options:["Sông Đà","Sông Cửu Long","Sông Mã","Sông Thái Bình"],answer:1,explain:"Sông Mê Công đổ ra biển bằng chín cửa nên còn gọi là sông Cửu Long.",emoji:"🐉"},{id:"sd5-song-ngoi-05",type:"tf",q:"Lượng nước sông ở nước ta giống nhau quanh năm.",answer:!1,explain:"Lượng nước sông thay đổi theo mùa: mùa lũ nhiều nước, mùa cạn ít nước."},{id:"sd5-song-ngoi-06",type:"multi",q:"Sông ngòi đem lại những lợi ích gì?",options:["Bồi đắp đồng bằng","Cung cấp nước tưới","Cho tôm cá","Tạo ra băng tuyết"],answers:[0,1,2],explain:"Sông bồi đắp đồng bằng, cung cấp nước và thủy sản.",emoji:"🐟"},{id:"sd5-song-ngoi-07",type:"fill",q:"Mùa mưa, nước sông dâng cao gọi là mùa … .",answer:["lũ"],explain:"Mùa nước sông dâng cao là mùa lũ."},{id:"sd5-song-ngoi-08",type:"mc",q:"Nhà máy thủy điện Sơn La được xây trên sông nào?",options:["Sông Hồng","Sông Cầu","Sông Đà","Sông Mê Công"],answer:2,explain:"Thủy điện Sơn La nằm trên sông Đà.",emoji:"⚡"},{id:"sd5-song-ngoi-09",type:"tf",q:"Phù sa của sông giúp đồng ruộng màu mỡ.",answer:!0,explain:"Phù sa bồi đắp làm đất đồng bằng màu mỡ."}]},{questions:[{id:"sd5-song-ngoi-10",type:"match",q:"Nối sông với vai trò.",pairs:[["Sông Đà","Thủy điện"],["Sông Hồng","Bồi đắp đồng bằng Bắc Bộ"],["Sông Mê Công","Bồi đắp đồng bằng Nam Bộ"]],explain:"Sông Đà có thủy điện lớn; sông Hồng và sông Mê Công bồi đắp hai đồng bằng lớn."},{id:"sd5-song-ngoi-11",type:"mc",q:"Vì sao phần lớn sông ngòi nước ta là sông nhỏ, ngắn?",options:["Vì nước ta có nhiều sa mạc","Vì sông bị đóng băng","Vì nước ta rất ít mưa","Vì lãnh thổ hẹp ngang"],answer:3,explain:"Lãnh thổ hẹp ngang nên sông từ núi ra biển ngắn."},{id:"sd5-song-ngoi-12",type:"mc",q:"Vì sao lượng nước sông thay đổi theo mùa?",options:["Vì băng tuyết trên núi tan ra","Vì lượng mưa thay đổi theo mùa","Vì nước biển chảy ngược vào","Vì con người đổ thêm nước vào"],answer:1,explain:"Mùa mưa nước sông lên, mùa khô nước sông xuống."},{id:"sd5-song-ngoi-13",type:"tf",q:"Mùa lũ không bao giờ gây thiệt hại cho mùa màng và nhà cửa.",answer:!1,explain:"Nước lũ dâng cao có thể gây ngập lụt, làm thiệt hại mùa màng và nhà cửa.",emoji:"🌊"},{id:"sd5-song-ngoi-14",type:"multi",q:"Ở đồng bằng Nam Bộ, sông ngòi giúp người dân:",options:["Đi lại bằng ghe, xuồng","Nuôi tôm, cá","Họp chợ nổi","Trượt tuyết"],answers:[0,1,2],explain:"Sông ngòi chằng chịt gắn với ghe xuồng, nuôi thủy sản, chợ nổi.",emoji:"🛶"},{id:"sd5-song-ngoi-15",type:"mc",q:"Nước sông Hồng có màu đỏ nâu chủ yếu do:",options:["Có nhiều tảo đỏ","Bị nhuộm màu","Mang nhiều phù sa","Có nhiều muối mặn"],answer:2,explain:"Sông Hồng chở rất nhiều phù sa nên nước có màu đỏ nâu."},{id:"sd5-song-ngoi-16",type:"tf",q:"Sông ở vùng núi chảy dốc, nhiều thác ghềnh nên thuận lợi để làm thủy điện.",answer:!0,explain:"Sông có độ dốc lớn tạo sức nước mạnh, thuận lợi làm thủy điện."},{id:"sd5-song-ngoi-17",type:"mc",q:"Mùa cạn kéo dài gây khó khăn gì?",options:["Ngập lụt nhà cửa","Lũ quét ở vùng núi","Thiếu nước tưới, nước dùng","Sóng thần ở ven biển"],answer:2,explain:"Mùa cạn nước sông ít, có nơi thiếu nước tưới và sinh hoạt."},{id:"sd5-song-ngoi-18",type:"mc",q:"Sông Mê Công bắt nguồn từ đâu?",options:["Từ dãy Trường Sơn của nước ta","Từ đồng bằng Nam Bộ","Từ Biển Đông chảy vào đất liền","Từ nước ngoài, chảy qua nhiều nước"],answer:3,explain:"Sông Mê Công chảy qua nhiều quốc gia rồi mới vào nước ta."}]},{questions:[{id:"sd5-song-ngoi-19",type:"mc",q:"Thấy người xả rác xuống sông, Ngọc nên làm gì?",options:["Xả rác theo cho nhanh","Nhắc nhở nhẹ nhàng, làm gương","Làm ngơ như không thấy","Ném rác lại vào người đó"],answer:1,explain:"Nhắc nhở và làm gương giúp giữ dòng sông sạch."},{id:"sd5-song-ngoi-20",type:"multi",q:"Việc nào giúp bảo vệ sông ngòi?",options:["Không xả nước thải bẩn xuống sông","Trồng cây ven bờ sông","Đánh cá bằng điện","Vớt rác trên sông"],answers:[0,1,3],explain:"Không xả bẩn, trồng cây, vớt rác giúp sông sạch; đánh cá bằng điện hủy hoại nguồn cá."},{id:"sd5-song-ngoi-21",type:"tf",q:"Đắp đê dọc sông Hồng giúp ngăn lũ cho đồng bằng Bắc Bộ.",answer:!0,explain:"Hệ thống đê sông Hồng bảo vệ làng mạc, đồng ruộng khỏi lũ."},{id:"sd5-song-ngoi-22",type:"mc",q:"Ở đồng bằng Nam Bộ, mùa nước nổi đem lại lợi ích gì?",options:["Làm đất bị bạc màu, khô cằn","Làm đồng ruộng khô hạn hơn","Bồi phù sa, đem lại cá tôm","Gây tuyết rơi trên đồng bằng"],answer:2,explain:"Mùa nước nổi bồi phù sa cho ruộng và mang lại nhiều thủy sản."},{id:"sd5-song-ngoi-23",type:"mc",q:"Khoa muốn tham quan chợ nổi trên sông. Khoa nên đến vùng nào?",options:["Đồng bằng Nam Bộ","Vùng núi phía bắc","Tây Nguyên","Quần đảo Hoàng Sa"],answer:0,explain:"Chợ nổi trên sông là nét đặc trưng của đồng bằng Nam Bộ, như chợ nổi Cái Răng ở Cần Thơ.",emoji:"🛶"},{id:"sd5-song-ngoi-24",type:"tf",q:"Trẻ em có thể tự bơi ở sông vào mùa lũ mà không cần người lớn.",answer:!1,explain:"Mùa lũ nước chảy xiết, rất nguy hiểm; trẻ em không được tự ý xuống sông."},{id:"sd5-song-ngoi-25",type:"mc",q:"Vì sao đồng bằng và các thành phố lớn thường nằm ven sông?",options:["Vì ven sông có nhiều núi cao, hiểm trở","Vì có nước, phù sa và đi lại thuận tiện","Vì ven sông vắng vẻ, không có người","Vì ven sông lạnh giá quanh năm"],answer:1,explain:"Sông cho nước, phù sa và đường đi lại, nên dân cư đông đúc."},{id:"sd5-song-ngoi-26",type:"mc",q:"Hồ thủy điện ngoài phát điện còn giúp:",options:["Gây hạn hán cho vùng hạ lưu","Biến đồng bằng thành sa mạc","Làm sông cạn hẳn quanh năm","Điều tiết nước, giảm lũ hạ lưu"],answer:3,explain:"Hồ chứa giữ nước mùa lũ và xả nước mùa cạn."}]}],challenge:{questions:[{id:"sd5-song-ngoi-27",type:"order",q:"Sắp xếp các bước của hạt phù sa từ núi về đồng bằng.",items:["Mưa làm trôi đất đá trên núi","Nước sông chở phù sa xuôi dòng","Phù sa lắng đọng ở vùng đất thấp","Đồng bằng được bồi đắp, màu mỡ"],explain:"Phù sa từ núi theo dòng sông xuống, lắng lại và bồi đắp đồng bằng."},{id:"sd5-song-ngoi-28",type:"match",q:"Nối mùa với tình trạng sông.",pairs:[["Mùa mưa","Nước sông dâng cao"],["Mùa khô","Nước sông xuống thấp"],["Mùa nước nổi ở Nam Bộ","Nước tràn đồng, nhiều cá tôm"]],explain:"Lượng nước sông thay đổi theo mùa mưa và mùa khô."},{id:"sd5-song-ngoi-29",type:"tf",q:"Sông Mê Công đổ ra Biển Đông.",answer:!0,explain:"Sông Mê Công chảy qua đồng bằng Nam Bộ rồi đổ ra Biển Đông."},{id:"sd5-song-ngoi-30",type:"multi",q:"Những sông nào chảy qua nước ta?",options:["Sông Hồng","Sông Đà","Sông Đồng Nai","Sông Nin","Sông Hoàng Hà"],answers:[0,1,2],explain:"Sông Nin ở châu Phi, sông Hoàng Hà ở Trung Quốc; các sông còn lại chảy qua nước ta."},{id:"sd5-song-ngoi-31",type:"mc",q:"Vì sao nói sông ngòi “vừa có lợi, vừa có hại”?",options:["Vì sông lúc nào cũng gây hại cho con người","Vì sông cho nước, phù sa nhưng lũ gây ngập","Vì sông không đem lại lợi ích gì","Vì sông chỉ chảy ở vùng núi cao"],answer:1,explain:"Sông đem lại nhiều lợi ích nhưng lũ lụt có thể gây thiệt hại."},{id:"sd5-song-ngoi-32",type:"tf",q:"Sông Hương chảy qua thành phố Cần Thơ.",answer:!1,explain:"Sông Hương chảy qua thành phố Huế; Cần Thơ nằm bên sông Hậu."}]},summary:["Nước ta có mạng lưới sông ngòi dày đặc, sông nhiều nước, nhiều phù sa.","Lượng nước sông thay đổi theo mùa: mùa lũ và mùa cạn.","Sông bồi đắp đồng bằng, cho nước, thủy sản, giao thông và thủy điện."]}]},{id:"dan-cu",title:"Dân cư và các dân tộc",lessons:[{id:"sd5-dan-cu-dan-toc",title:"Dân cư và các dân tộc Việt Nam",weeks:[8,8],learn:[{title:"Dân số đông",text:"Việt Nam là nước đông dân, dân số đã vượt 100 triệu người. Dân số đông tạo nguồn lao động dồi dào nhưng cũng gây sức ép về việc làm, nhà ở, trường học, môi trường.",example:"👨‍👩‍👧‍👦 hơn 100 triệu người"},{title:"54 dân tộc",text:"Nước ta có 54 dân tộc anh em. Dân tộc Kinh đông nhất. Các dân tộc như Tày, Thái, Mường, Mông, Khmer, Ê-đê, Chăm… đều là thành viên của đại gia đình Việt Nam.",example:"🤝 54 dân tộc"},{title:"Phân bố dân cư",text:"Dân cư tập trung đông ở đồng bằng, ven biển và các thành phố; thưa thớt ở vùng núi. Các dân tộc ít người sống chủ yếu ở miền núi và cao nguyên.",example:"🏙️ đông · ⛰️ thưa"}],practice:[{questions:[{id:"sd5-dan-cu-dan-toc-01",type:"number",q:"Nước ta có bao nhiêu dân tộc?",answer:54,explain:"Việt Nam có 54 dân tộc anh em.",unit:"dân tộc",emoji:"🤝"},{id:"sd5-dan-cu-dan-toc-02",type:"mc",q:"Dân tộc nào có số dân đông nhất nước ta?",options:["Tày","Thái","Kinh","Mường"],answer:2,explain:"Dân tộc Kinh chiếm phần lớn dân số nước ta."},{id:"sd5-dan-cu-dan-toc-03",type:"tf",q:"Dân số Việt Nam đã vượt 100 triệu người.",answer:!0,explain:"Việt Nam là nước đông dân, dân số đã hơn 100 triệu người."},{id:"sd5-dan-cu-dan-toc-04",type:"mc",q:"Dân cư nước ta tập trung đông nhất ở đâu?",options:["Vùng núi cao","Vùng biên giới","Các quần đảo xa bờ","Đồng bằng, ven biển"],answer:3,explain:"Đồng bằng, ven biển có nhiều điều kiện thuận lợi nên dân cư đông đúc."},{id:"sd5-dan-cu-dan-toc-05",type:"tf",q:"Các dân tộc ít người sống chủ yếu ở các thành phố lớn ven biển.",answer:!1,explain:"Phần lớn các dân tộc ít người sống ở miền núi và cao nguyên.",emoji:"⛰️"},{id:"sd5-dan-cu-dan-toc-06",type:"multi",q:"Những dân tộc nào sống trên đất nước Việt Nam?",options:["Tày","Ê-đê","Khmer","Mông"],answers:[0,1,2,3],explain:"Tày, Ê-đê, Khmer, Mông đều là dân tộc trong 54 dân tộc Việt Nam."},{id:"sd5-dan-cu-dan-toc-07",type:"fill",q:"Nước ta có năm mươi … dân tộc anh em.",answer:["bốn","tư"],explain:"Việt Nam có năm mươi tư (54) dân tộc."},{id:"sd5-dan-cu-dan-toc-08",type:"mc",q:"Vùng nào có dân cư thưa thớt nhất?",options:["Vùng núi","Đồng bằng Bắc Bộ","Thành phố Hồ Chí Minh","Ven biển"],answer:0,explain:"Vùng núi đi lại khó khăn, dân cư thưa thớt."},{id:"sd5-dan-cu-dan-toc-09",type:"tf",q:"Các dân tộc Việt Nam cùng chung sống, đoàn kết trên một đất nước.",answer:!0,explain:"Các dân tộc là anh em trong đại gia đình Việt Nam."}]},{questions:[{id:"sd5-dan-cu-dan-toc-10",type:"mc",q:"Vì sao dân cư tập trung đông ở đồng bằng?",options:["Vì đồng bằng có nhiều núi cao","Vì đồng bằng không có sông ngòi","Vì đồng bằng lạnh giá quanh năm","Vì đất bằng, màu mỡ, dễ đi lại"],answer:3,explain:"Đồng bằng thuận lợi cho sản xuất và đi lại nên dân đông."},{id:"sd5-dan-cu-dan-toc-11",type:"multi",q:"Dân số đông gây ra những khó khăn nào?",options:["Thiếu việc làm","Thiếu nhà ở","Môi trường bị ô nhiễm","Nhiều rừng hơn"],answers:[0,1,2],explain:"Dân số đông gây sức ép về việc làm, nhà ở, môi trường."},{id:"sd5-dan-cu-dan-toc-12",type:"tf",q:"Dân số đông giúp nước ta có nguồn lao động dồi dào.",answer:!0,explain:"Nhiều người trong độ tuổi lao động là một thuận lợi lớn."},{id:"sd5-dan-cu-dan-toc-13",type:"match",q:"Nối nhà ở truyền thống với vùng.",pairs:[["Nhà sàn","Người Thái, Tày ở miền núi phía bắc"],["Nhà rông","Một số dân tộc ở Tây Nguyên"],["Nhà ba gian mái ngói","Làng quê đồng bằng Bắc Bộ"]],explain:"Mỗi vùng, mỗi dân tộc có kiểu nhà phù hợp với thiên nhiên và văn hóa."},{id:"sd5-dan-cu-dan-toc-14",type:"mc",q:"Vùng núi dân cư thưa, điều đó gây khó khăn gì?",options:["Ô nhiễm khói bụi nhiều","Có quá nhiều nhà cao tầng","Thiếu người lao động","Tắc đường thường xuyên"],answer:2,explain:"Vùng núi giàu tài nguyên nhưng ít người lao động."},{id:"sd5-dan-cu-dan-toc-15",type:"tf",q:"Chỉ dân tộc Kinh mới là người Việt Nam.",answer:!1,explain:"Tất cả 54 dân tộc đều là người Việt Nam, bình đẳng như nhau."},{id:"sd5-dan-cu-dan-toc-16",type:"mc",q:"Thành phố có số dân đông nhất nước ta là:",options:["Huế","Cần Thơ","Thành phố Hồ Chí Minh","Thành phố Đà Nẵng"],answer:2,explain:"Thành phố Hồ Chí Minh là đô thị đông dân nhất nước ta."},{id:"sd5-dan-cu-dan-toc-17",type:"mc",q:"Ở thành phố đông dân thường gặp vấn đề nào?",options:["Tắc đường, ô nhiễm không khí","Thiếu đường giao thông vì ít người","Không có trường học","Có quá nhiều rừng"],answer:0,explain:"Đông người, nhiều xe cộ dễ gây tắc đường và ô nhiễm.",emoji:"🚗"},{id:"sd5-dan-cu-dan-toc-18",type:"multi",q:"Nét văn hóa nào là của các dân tộc Việt Nam?",options:["Chợ phiên vùng cao","Lễ hội cồng chiêng Tây Nguyên","Áo dài","Lễ hội hóa trang ở châu Âu"],answers:[0,1,2],explain:"Chợ phiên, cồng chiêng, áo dài là nét văn hóa Việt Nam."}]},{questions:[{id:"sd5-dan-cu-dan-toc-19",type:"mc",q:"Lớp của Chi có bạn Hà là người Tày, bạn Phúc là người Kinh. Các bạn nên cư xử thế nào?",options:["Chỉ chơi với bạn cùng dân tộc","Không nói chuyện với nhau","Trêu chọc trang phục của bạn","Đoàn kết, tôn trọng, giúp nhau"],answer:3,explain:"Các dân tộc bình đẳng, cần tôn trọng và đoàn kết."},{id:"sd5-dan-cu-dan-toc-20",type:"tf",q:"Nhà nước mở trường học, làm đường ở vùng núi là để giúp đồng bào các dân tộc có cuộc sống tốt hơn.",answer:!0,explain:"Đầu tư trường học, đường sá giúp vùng núi phát triển."},{id:"sd5-dan-cu-dan-toc-21",type:"mc",q:"Để giảm bớt tắc đường ở thành phố đông dân, em có thể đề xuất việc nào?",options:["Mỗi người đi một ô tô riêng","Đỗ xe giữa lòng đường","Đi xe buýt, đi xe đạp khi có thể","Xây nhà lấn ra đường"],answer:2,explain:"Đi phương tiện công cộng giúp giảm số xe trên đường.",emoji:"🚌"},{id:"sd5-dan-cu-dan-toc-22",type:"multi",q:"Việc làm nào thể hiện sự tôn trọng các dân tộc khác?",options:["Tìm hiểu phong tục của bạn","Hỏi bạn về lễ hội quê bạn","Chế giễu tiếng nói của bạn","Thưởng thức món ăn truyền thống của bạn"],answers:[0,1,3],explain:"Tìm hiểu, quan tâm là tôn trọng; chế giễu là sai."},{id:"sd5-dan-cu-dan-toc-23",type:"mc",q:"Vì sao Nhà nước khuyến khích người dân đến lập nghiệp ở những vùng còn thưa dân?",options:["Để bỏ hoang đất đai ở vùng núi","Để các thành phố lớn đông người thêm","Để khai thác tài nguyên, phân bố dân hợp lí","Để chặt phá rừng lấy gỗ bán"],answer:2,explain:"Phân bố dân cư hợp lí giúp các vùng cùng phát triển."},{id:"sd5-dan-cu-dan-toc-24",type:"tf",q:"Dân số tăng càng nhanh thì việc học tập, chữa bệnh càng dễ dàng.",answer:!1,explain:"Dân số tăng quá nhanh gây sức ép lên trường học, bệnh viện và việc làm."},{id:"sd5-dan-cu-dan-toc-25",type:"mc",q:"Lễ hội cồng chiêng là nét văn hóa đặc sắc của vùng nào?",options:["Đồng bằng Bắc Bộ","Ven biển miền Trung","Đồng bằng Nam Bộ","Tây Nguyên"],answer:3,explain:"Không gian văn hóa cồng chiêng Tây Nguyên là di sản nổi tiếng.",emoji:"🥁"},{id:"sd5-dan-cu-dan-toc-26",type:"mc",q:"Phố cổ Hội An, nơi đông khách du lịch, nay thuộc địa phương nào?",options:["Tỉnh Quảng Ngãi","Thành phố Đà Nẵng","Thành phố Huế","Tỉnh Khánh Hòa"],answer:1,explain:"Quảng Nam đã hợp nhất vào Đà Nẵng nên phố cổ Hội An nay thuộc thành phố Đà Nẵng.",emoji:"🏮"}]}],challenge:{questions:[{id:"sd5-dan-cu-dan-toc-27",type:"match",q:"Nối dân tộc với vùng sinh sống chủ yếu.",pairs:[["Ê-đê","Tây Nguyên"],["Khmer","Đồng bằng Nam Bộ"],["Thái","Miền núi phía bắc"],["Chăm","Ven biển Nam Trung Bộ và Nam Bộ"]],explain:"Ê-đê ở Tây Nguyên, Khmer ở Nam Bộ, Thái ở miền núi phía bắc, Chăm ở Nam Trung Bộ và Nam Bộ."},{id:"sd5-dan-cu-dan-toc-28",type:"multi",q:"Phát biểu nào đúng về dân cư nước ta?",options:["Nước ta đông dân","Dân cư phân bố không đều","Vùng núi đông dân hơn đồng bằng","Có 54 dân tộc"],answers:[0,1,3],explain:"Đồng bằng đông dân hơn vùng núi, nên ý thứ ba sai."},{id:"sd5-dan-cu-dan-toc-29",type:"tf",q:"Ở nước ta, các dân tộc đều bình đẳng, đoàn kết, tôn trọng và giúp nhau cùng phát triển.",answer:!0,explain:"Các dân tộc Việt Nam bình đẳng và đoàn kết."},{id:"sd5-dan-cu-dan-toc-30",type:"mc",q:"Dân cư phân bố không đều dẫn đến điều gì?",options:["Mọi nơi đều đông dân như nhau","Nơi thừa lao động, nơi thiếu","Không ảnh hưởng gì đến đời sống","Rừng ở đồng bằng tăng nhanh"],answer:1,explain:"Đồng bằng thừa lao động, vùng núi lại thiếu người khai thác tài nguyên."},{id:"sd5-dan-cu-dan-toc-31",type:"mc",q:"Phong tục nào là của người Việt dịp Tết Nguyên đán?",options:["Hóa trang bằng bí ngô","Dựng cây thông Nô-en","Tặng trứng sô-cô-la","Gói bánh chưng, chúc Tết"],answer:3,explain:"Gói bánh chưng, chúc Tết là phong tục Tết của người Việt.",emoji:"🎋"},{id:"sd5-dan-cu-dan-toc-32",type:"tf",q:"Người Kinh sống chủ yếu ở vùng núi cao.",answer:!1,explain:"Người Kinh sống chủ yếu ở đồng bằng, ven biển và đô thị."}]},summary:["Việt Nam đông dân, có hơn 100 triệu người.","Nước ta có 54 dân tộc, dân tộc Kinh đông nhất.","Dân cư đông ở đồng bằng, ven biển; thưa ở vùng núi.","Các dân tộc đoàn kết, yêu thương, giúp đỡ nhau."]}]},{id:"quoc-gia-dau-tien",title:"Những quốc gia đầu tiên trên lãnh thổ Việt Nam",lessons:[{id:"sd5-van-lang-au-lac",title:"Nhà nước Văn Lang, Âu Lạc",weeks:[9,10],learn:[{title:"Nhà nước Văn Lang",text:"Nhà nước đầu tiên của người Việt là Văn Lang, do các vua Hùng đứng đầu, đóng đô ở Phong Châu (Phú Thọ ngày nay). Văn Lang hình thành ở vùng đồng bằng sông Hồng, sông Mã, sông Cả.",example:"👑 Vua Hùng · Phong Châu"},{title:"Đời sống người Việt cổ",text:"Người Việt cổ trồng lúa nước, ở nhà sàn, đúc trống đồng, có tục nhuộm răng, ăn trầu. Trống đồng Đông Sơn là cổ vật nổi tiếng.",example:"🌾 🏠 🥁"},{title:"Nhà nước Âu Lạc",text:"Sau Văn Lang, Thục Phán (An Dương Vương) lập nước Âu Lạc, đóng đô ở Cổ Loa (Hà Nội ngày nay). Thành Cổ Loa có nhiều vòng hình xoắn ốc; quân Âu Lạc giỏi dùng nỏ.",example:"🌀 Thành Cổ Loa · 🏹 nỏ"},{title:"Giỗ Tổ Hùng Vương",text:"Hằng năm, ngày mùng 10 tháng 3 âm lịch, nhân dân cả nước tưởng nhớ các vua Hùng. Tín ngưỡng thờ cúng Hùng Vương được UNESCO ghi danh.",example:"“Dù ai đi ngược về xuôi, nhớ ngày Giỗ Tổ mùng mười tháng ba.”"}],practice:[{questions:[{id:"sd5-van-lang-au-lac-01",type:"mc",q:"Nhà nước đầu tiên của người Việt là:",options:["Âu Lạc","Văn Lang","Đại Việt","Vạn Xuân"],answer:1,explain:"Văn Lang là nhà nước đầu tiên của người Việt.",emoji:"👑"},{id:"sd5-van-lang-au-lac-02",type:"mc",q:"Ai đứng đầu nhà nước Văn Lang?",options:["An Dương Vương","Lý Thái Tổ","Ngô Quyền","Các vua Hùng"],answer:3,explain:"Đứng đầu nhà nước Văn Lang là các vua Hùng."},{id:"sd5-van-lang-au-lac-03",type:"mc",q:"Ai là người lập nên nước Âu Lạc?",options:["Vua Hùng","An Dương Vương","Hai Bà Trưng","Lý Bí"],answer:1,explain:"Thục Phán – An Dương Vương lập nên nước Âu Lạc."},{id:"sd5-van-lang-au-lac-04",type:"mc",q:"Kinh đô của nước Âu Lạc ở đâu?",options:["Phong Châu","Thăng Long","Cổ Loa","Phú Xuân"],answer:2,explain:"An Dương Vương đóng đô ở Cổ Loa, nay thuộc Hà Nội.",emoji:"🌀"},{id:"sd5-van-lang-au-lac-05",type:"tf",q:"Người Việt cổ thời Văn Lang sống chủ yếu bằng nghề chăn nuôi lạc đà.",answer:!1,explain:"Người Việt cổ sống chủ yếu bằng nghề trồng lúa nước.",emoji:"🌾"},{id:"sd5-van-lang-au-lac-06",type:"fill",q:"Ngày Giỗ Tổ Hùng Vương là ngày mùng … tháng 3 âm lịch.",answer:["10","mười"],explain:"Giỗ Tổ Hùng Vương là ngày mùng 10 tháng 3 âm lịch."},{id:"sd5-van-lang-au-lac-07",type:"tf",q:"Thành Cổ Loa có hình vuông, chỉ có một vòng thành.",answer:!1,explain:"Thành Cổ Loa có nhiều vòng thành uốn lượn hình xoắn ốc."},{id:"sd5-van-lang-au-lac-08",type:"mc",q:"Cổ vật nổi tiếng thể hiện tài đúc đồng của người Việt cổ là:",options:["Bình gốm hoa lam","Trống đồng Đông Sơn","Tượng Phật bằng gỗ","Chuông chùa"],answer:1,explain:"Trống đồng Đông Sơn là cổ vật tiêu biểu của thời Văn Lang – Âu Lạc.",emoji:"🥁"},{id:"sd5-van-lang-au-lac-09",type:"multi",q:"Người Việt cổ có những phong tục nào?",options:["Nhuộm răng","Ăn trầu","Ở nhà sàn","Đi tàu hỏa"],answers:[0,1,2],explain:"Nhuộm răng, ăn trầu, ở nhà sàn là phong tục của người Việt cổ."}]},{questions:[{id:"sd5-van-lang-au-lac-10",type:"order",q:"Sắp xếp theo thứ tự thời gian.",items:["Nhà nước Văn Lang ra đời","Nhà nước Âu Lạc ra đời","Xây thành Cổ Loa"],explain:"Văn Lang có trước, sau đó An Dương Vương lập Âu Lạc và xây thành Cổ Loa."},{id:"sd5-van-lang-au-lac-11",type:"match",q:"Nối nhà nước với thông tin đúng.",pairs:[["Văn Lang","Kinh đô Phong Châu"],["Âu Lạc","Kinh đô Cổ Loa"],["Vua Hùng","Đứng đầu Văn Lang"]],explain:"Văn Lang đóng đô ở Phong Châu, Âu Lạc đóng đô ở Cổ Loa."},{id:"sd5-van-lang-au-lac-12",type:"mc",q:"Văn Lang hình thành ở khu vực nào?",options:["Đồng bằng sông Cửu Long","Vùng cao nguyên Tây Nguyên","Lưu vực sông Hồng, sông Mã, sông Cả","Ven biển Nam Trung Bộ"],answer:2,explain:"Nhà nước Văn Lang hình thành ở vùng đồng bằng sông Hồng, sông Mã, sông Cả."},{id:"sd5-van-lang-au-lac-13",type:"tf",q:"Kinh đô Phong Châu của nước Văn Lang nay thuộc tỉnh Phú Thọ.",answer:!0,explain:"Phong Châu nằm ở vùng đất nay thuộc tỉnh Phú Thọ."},{id:"sd5-van-lang-au-lac-14",type:"mc",q:"Vì sao người Việt cổ ở nhà sàn?",options:["Để ngắm sao vào ban đêm","Vì sống giữa sa mạc nóng","Vì không có đất để làm nền","Để tránh ẩm thấp và thú dữ"],answer:3,explain:"Nhà sàn cao ráo, tránh được ẩm thấp, nước lũ và thú dữ.",emoji:"🏠"},{id:"sd5-van-lang-au-lac-15",type:"tf",q:"Vũ khí nổi tiếng của quân Âu Lạc là súng thần công.",answer:!1,explain:"Quân Âu Lạc nổi tiếng với nỏ, gắn với truyền thuyết nỏ thần.",emoji:"🏹"},{id:"sd5-van-lang-au-lac-16",type:"multi",q:"Thành Cổ Loa có những đặc điểm nào?",options:["Có nhiều vòng thành","Hình xoắn ốc","Xây bằng bê tông cốt thép","Là kinh đô của Âu Lạc"],answers:[0,1,3],explain:"Thành Cổ Loa xây bằng đất, có nhiều vòng hình xoắn ốc, là kinh đô Âu Lạc."},{id:"sd5-van-lang-au-lac-17",type:"mc",q:"Hình ảnh nào thường được khắc trên mặt trống đồng Đông Sơn?",options:["Ô tô, tàu hỏa, máy bay","Mặt trời, chim, người giã gạo","Tòa nhà cao tầng, cầu sắt","Chữ cái La-tinh và số"],answer:1,explain:"Trống đồng khắc mặt trời, chim, cảnh sinh hoạt của người Việt cổ."},{id:"sd5-van-lang-au-lac-18",type:"mc",q:"Truyện nào gắn với thời các vua Hùng?",options:["Sơn Tinh, Thủy Tinh","Sự tích Hồ Gươm","Cây khế","Thạch Sanh và Lý Thông"],answer:0,explain:"Truyền thuyết Sơn Tinh, Thủy Tinh kể chuyện thời vua Hùng thứ mười tám."}]},{questions:[{id:"sd5-van-lang-au-lac-19",type:"mc",q:"Truyền thuyết Sơn Tinh, Thủy Tinh cho thấy người Việt cổ đã phải:",options:["Chống hạn hán giữa sa mạc","Chống tuyết lở trên núi cao","Chống lũ lụt giữ đồng ruộng","Chống núi lửa đang phun"],answer:2,explain:"Thủy Tinh dâng nước tượng trưng cho lũ lụt mà người Việt cổ phải chống chọi."},{id:"sd5-van-lang-au-lac-20",type:"tf",q:"Việc xây thành Cổ Loa nhiều vòng cho thấy nước Âu Lạc chú trọng phòng thủ, bảo vệ đất nước.",answer:!0,explain:"Thành nhiều vòng, có hào nước giúp phòng thủ vững chắc."},{id:"sd5-van-lang-au-lac-21",type:"mc",q:"Gia đình Thảo đi lễ Đền Hùng vào ngày Giỗ Tổ. Đền Hùng nằm ở tỉnh nào?",options:["Hà Nội","Thanh Hóa","Ninh Bình","Phú Thọ"],answer:3,explain:"Khu di tích Đền Hùng ở tỉnh Phú Thọ."},{id:"sd5-van-lang-au-lac-22",type:"multi",q:"Những điều nào cho thấy người Việt cổ rất khéo tay?",options:["Đúc trống đồng tinh xảo","Làm nỏ bắn được nhiều mũi tên","Chế tạo máy bay","Xây thành Cổ Loa"],answers:[0,1,3],explain:"Trống đồng, nỏ, thành Cổ Loa thể hiện trí tuệ và sự khéo léo của người Việt cổ."},{id:"sd5-van-lang-au-lac-23",type:"mc",q:"Câu “Dù ai đi ngược về xuôi, nhớ ngày Giỗ Tổ mùng mười tháng ba” nhắc chúng ta điều gì?",options:["Nhớ đi chơi xa vào mùa xuân","Nhớ làm bánh vào Tết Trung thu","Nhớ chuẩn bị cho ngày khai giảng","Nhớ cội nguồn, nhớ ơn vua Hùng"],answer:3,explain:"Câu ca dao nhắc mọi người nhớ cội nguồn dân tộc."},{id:"sd5-van-lang-au-lac-24",type:"tf",q:"Văn Lang là nhà nước được thành lập sau Âu Lạc.",answer:!1,explain:"Văn Lang có trước, Âu Lạc ra đời sau."},{id:"sd5-van-lang-au-lac-25",type:"mc",q:"Sự tích bánh chưng, bánh giầy cho thấy người Việt cổ coi trọng:",options:["Đồ ăn nhanh, tiện lợi","Nghề đánh bắt cá voi","Hạt gạo, nghề trồng lúa","Nghề khai thác mỏ vàng"],answer:2,explain:"Bánh chưng, bánh giầy làm từ gạo nếp, thể hiện sự quý trọng hạt gạo.",emoji:"🍙"},{id:"sd5-van-lang-au-lac-26",type:"mc",q:"Khu di tích Cổ Loa ngày nay thuộc địa phương nào?",options:["Hà Nội","Bắc Ninh","Phú Thọ","Hải Phòng"],answer:0,explain:"Thành Cổ Loa nay thuộc Thủ đô Hà Nội."}]}],challenge:{questions:[{id:"sd5-van-lang-au-lac-27",type:"match",q:"Nối nhân vật, sự vật với thời kì.",pairs:[["Vua Hùng","Văn Lang"],["An Dương Vương","Âu Lạc"],["Trống đồng Đông Sơn","Văn Lang – Âu Lạc"]],explain:"Vua Hùng gắn với Văn Lang, An Dương Vương gắn với Âu Lạc; trống đồng có ở thời Văn Lang – Âu Lạc."},{id:"sd5-van-lang-au-lac-28",type:"multi",q:"Phát biểu nào đúng về nhà nước Văn Lang?",options:["Là nhà nước đầu tiên của người Việt","Đứng đầu là vua Hùng","Đóng đô ở Cổ Loa","Người dân trồng lúa nước"],answers:[0,1,3],explain:"Văn Lang đóng đô ở Phong Châu; Cổ Loa là kinh đô của Âu Lạc."},{id:"sd5-van-lang-au-lac-29",type:"tf",q:"Tín ngưỡng thờ cúng Hùng Vương đã được UNESCO ghi danh là di sản văn hóa phi vật thể.",answer:!0,explain:"Tín ngưỡng thờ cúng Hùng Vương ở Phú Thọ được UNESCO ghi danh."},{id:"sd5-van-lang-au-lac-30",type:"mc",q:"Em hiểu câu “Uống nước nhớ nguồn” liên quan đến ngày Giỗ Tổ thế nào?",options:["Biết ơn người có công dựng nước","Mỗi ngày phải uống nhiều nước","Phải đi tìm những nguồn nước mới","Không liên quan gì đến ngày Giỗ Tổ"],answer:0,explain:"Giỗ Tổ là dịp thể hiện lòng biết ơn các vua Hùng đã có công dựng nước."},{id:"sd5-van-lang-au-lac-31",type:"order",q:"Sắp xếp những người đứng đầu đất nước theo thứ tự thời gian.",items:["Các vua Hùng","An Dương Vương","Ngô Quyền","Lý Thái Tổ"],explain:"Vua Hùng (Văn Lang) → An Dương Vương (Âu Lạc) → Ngô Quyền (năm 939) → Lý Thái Tổ (năm 1009)."},{id:"sd5-van-lang-au-lac-32",type:"tf",q:"Người Việt cổ chỉ biết săn bắt, chưa biết trồng trọt.",answer:!1,explain:"Người Việt cổ đã trồng lúa nước, làm nhà sàn, đúc đồng."}]},summary:["Văn Lang là nhà nước đầu tiên của người Việt, do các vua Hùng đứng đầu.","Âu Lạc do An Dương Vương lập, kinh đô Cổ Loa, nổi tiếng thành xoắn ốc và nỏ.","Ngày mùng 10 tháng 3 âm lịch là ngày Giỗ Tổ Hùng Vương."]},{id:"sd5-phu-nam",title:"Vương quốc Phù Nam",weeks:[11,11],learn:[{title:"Ra đời ở Nam Bộ",text:"Khoảng thế kỉ I, vương quốc Phù Nam hình thành ở vùng đất Nam Bộ ngày nay.",example:"🗺️ Nam Bộ"},{title:"Óc Eo – cảng thị sầm uất",text:"Óc Eo (nay thuộc tỉnh An Giang) là cảng thị lớn của Phù Nam. Thương nhân nhiều nước đến buôn bán bằng đường biển.",example:"⛵ Óc Eo · An Giang"},{title:"Đời sống cư dân",text:"Cư dân Phù Nam trồng lúa nước, làm đồ gốm, đồ trang sức, đánh cá, buôn bán; họ ở nhà sàn ven sông, kênh rạch.",example:"🌾 🏺 💍 ⛵"}],practice:[{questions:[{id:"sd5-phu-nam-01",type:"mc",q:"Vương quốc Phù Nam hình thành ở vùng nào của nước ta ngày nay?",options:["Miền núi phía bắc","Đồng bằng Bắc Bộ","Nam Bộ","Tây Bắc"],answer:2,explain:"Phù Nam hình thành ở vùng đất Nam Bộ ngày nay."},{id:"sd5-phu-nam-02",type:"mc",q:"Phù Nam ra đời vào khoảng thế kỉ nào?",options:["Thế kỉ I","Thế kỉ X","Thế kỉ XV","Thế kỉ XX"],answer:0,explain:"Phù Nam hình thành khoảng thế kỉ I."},{id:"sd5-phu-nam-03",type:"mc",q:"Cảng thị nổi tiếng của Phù Nam là:",options:["Cổ Loa","Phong Châu","Óc Eo","Thăng Long"],answer:2,explain:"Óc Eo là cảng thị sầm uất của Phù Nam.",emoji:"⛵"},{id:"sd5-phu-nam-04",type:"tf",q:"Di tích Óc Eo nay thuộc tỉnh An Giang.",answer:!0,explain:"Di tích Óc Eo nằm ở tỉnh An Giang."},{id:"sd5-phu-nam-05",type:"multi",q:"Cư dân Phù Nam làm những nghề gì?",options:["Trồng lúa nước","Làm đồ gốm, trang sức","Buôn bán bằng đường biển","Khai thác dầu khí"],answers:[0,1,2],explain:"Cư dân Phù Nam trồng lúa, làm gốm, trang sức và buôn bán."},{id:"sd5-phu-nam-06",type:"tf",q:"Cư dân Phù Nam thường ở nhà băng trên núi tuyết.",answer:!1,explain:"Cư dân Phù Nam ở nhà sàn ven sông, kênh rạch.",emoji:"🏠"},{id:"sd5-phu-nam-07",type:"fill",q:"Cảng thị lớn của vương quốc Phù Nam là … Eo.",answer:["Óc"],explain:"Đó là cảng thị Óc Eo."},{id:"sd5-phu-nam-08",type:"tf",q:"Phù Nam là vương quốc nằm ở vùng núi cao, không có biển.",answer:!1,explain:"Phù Nam ở vùng đồng bằng ven biển Nam Bộ, buôn bán bằng đường biển."},{id:"sd5-phu-nam-09",type:"mc",q:"Phù Nam buôn bán với các nước chủ yếu bằng con đường nào?",options:["Đường biển","Đường sắt","Đường hàng không","Đường bộ qua sa mạc"],answer:0,explain:"Thuyền buôn các nước đến Óc Eo bằng đường biển."}]},{questions:[{id:"sd5-phu-nam-10",type:"mc",q:"Vì sao Óc Eo trở thành cảng thị sầm uất?",options:["Vì nằm trên núi cao, dễ phòng thủ","Vì gần biển, trên đường buôn bán","Vì có nhiều băng tuyết quý hiếm","Vì nằm xa sông, xa biển"],answer:1,explain:"Óc Eo gần biển, thuận lợi cho thuyền buôn các nước ghé qua."},{id:"sd5-phu-nam-11",type:"multi",q:"Người ta tìm thấy những hiện vật nào ở di tích Óc Eo?",options:["Đồ gốm","Đồ trang sức bằng vàng","Đồng tiền của nước ngoài","Điện thoại"],answers:[0,1,2],explain:"Đồ gốm, trang sức, tiền nước ngoài cho thấy Óc Eo buôn bán rộng."},{id:"sd5-phu-nam-12",type:"tf",q:"Việc tìm thấy tiền của nhiều nước ở Óc Eo chứng tỏ Phù Nam có quan hệ buôn bán rộng.",answer:!0,explain:"Tiền nước ngoài là dấu vết của hoạt động buôn bán với nhiều nước."},{id:"sd5-phu-nam-13",type:"match",q:"Nối nhà nước cổ với vùng đất ngày nay.",pairs:[["Văn Lang","Bắc Bộ và bắc Trung Bộ"],["Phù Nam","Nam Bộ"],["Champa","Ven biển miền Trung"]],explain:"Văn Lang ở phía bắc, Champa ở miền Trung, Phù Nam ở phía nam."},{id:"sd5-phu-nam-14",type:"mc",q:"Cư dân Phù Nam đào kênh rạch để làm gì?",options:["Để thoát nước, đi lại, tưới ruộng","Để trượt tuyết vào mùa đông","Để biến đồng ruộng thành sa mạc","Để nuôi lạc đà chở hàng"],answer:0,explain:"Kênh rạch giúp thoát nước, đi lại bằng thuyền và lấy nước tưới."},{id:"sd5-phu-nam-15",type:"tf",q:"Phù Nam và Champa là cùng một vương quốc.",answer:!1,explain:"Phù Nam ở Nam Bộ, Champa ở miền Trung; đó là hai vương quốc khác nhau."},{id:"sd5-phu-nam-16",type:"mc",q:"Văn hóa của cư dân Phù Nam được gọi là:",options:["Văn hóa Óc Eo","Văn hóa Đông Sơn","Văn hóa Sa Huỳnh","Văn hóa Hòa Bình"],answer:0,explain:"Văn hóa của cư dân Phù Nam gọi là văn hóa Óc Eo."},{id:"sd5-phu-nam-17",type:"mc",q:"Phù Nam chịu ảnh hưởng văn hóa, tôn giáo từ nước nào qua buôn bán?",options:["Ai Cập","Hy Lạp","Ấn Độ","Nhật Bản"],answer:2,explain:"Phù Nam tiếp thu nhiều yếu tố văn hóa, tôn giáo từ Ấn Độ."},{id:"sd5-phu-nam-18",type:"multi",q:"Điều kiện tự nhiên nào giúp Phù Nam phát triển?",options:["Đồng bằng rộng, đất màu mỡ","Gần biển","Nhiều sông, kênh rạch","Có nhiều băng tuyết"],answers:[0,1,2],explain:"Đồng bằng phù sa, sông nước, gần biển giúp trồng lúa và buôn bán."}]},{questions:[{id:"sd5-phu-nam-19",type:"mc",q:"Vy xem trong bảo tàng một chiếc nhẫn vàng nhỏ, tinh xảo tìm thấy ở Óc Eo. Hiện vật này cho biết điều gì?",options:["Người Phù Nam chưa biết làm đồ trang sức","Thợ thủ công Phù Nam rất khéo tay","Óc Eo là vùng núi","Người Phù Nam sống bằng săn bắt"],answer:1,explain:"Trang sức vàng tinh xảo cho thấy nghề thủ công Phù Nam phát triển.",emoji:"💍"},{id:"sd5-phu-nam-20",type:"tf",q:"Cần giữ gìn, bảo vệ di tích Óc Eo vì đó là di sản quý của đất nước.",answer:!0,explain:"Di tích Óc Eo giúp ta hiểu về lịch sử vùng đất Nam Bộ."},{id:"sd5-phu-nam-21",type:"mc",q:"Khi đến tham quan khu di tích Óc Eo, em nên làm gì?",options:["Đi theo hướng dẫn, không chạm hiện vật","Vẽ tên mình lên hiện vật","Nhặt cổ vật nhỏ mang về làm kỉ niệm","Ăn uống, xả rác trong khu di tích"],answer:0,explain:"Tôn trọng quy định giúp bảo vệ di tích."},{id:"sd5-phu-nam-22",type:"mc",q:"Hình ảnh nào phù hợp với đời sống cư dân Phù Nam?",options:["Nhà băng trên tuyết","Đàn lạc đà trên cát","Thuyền buôn neo đậu bên cảng","Ruộng bậc thang trên núi cao"],answer:2,explain:"Phù Nam có cảng thị Óc Eo với thuyền buôn tấp nập."},{id:"sd5-phu-nam-23",type:"tf",q:"Phù Nam là quốc gia cổ trên vùng đất Nam Bộ ngày nay.",answer:!0,explain:"Phù Nam là một trong những quốc gia đầu tiên trên lãnh thổ Việt Nam."},{id:"sd5-phu-nam-24",type:"mc",q:"Ngày nay, vùng đất xưa của Phù Nam là vựa lúa lớn của nước ta. Điều đó nói lên:",options:["Vùng đất này hoàn toàn không có nước","Vùng đất này toàn đồi núi cao","Vùng đất này lạnh giá quanh năm","Đất ở đây màu mỡ, hợp trồng lúa"],answer:3,explain:"Đồng bằng phù sa màu mỡ giúp nghề trồng lúa phát triển từ xưa."},{id:"sd5-phu-nam-25",type:"multi",q:"Phù Nam và Văn Lang giống nhau ở điểm nào?",options:["Đều trồng lúa nước","Đều ở nhà sàn","Đều có kinh đô Cổ Loa","Đều là vương quốc trên sa mạc"],answers:[0,1],explain:"Cả hai đều trồng lúa nước, ở nhà sàn; kinh đô Cổ Loa chỉ của Âu Lạc."},{id:"sd5-phu-nam-26",type:"mc",q:"Nghề nào của Phù Nam cho thấy đây là quốc gia giỏi giao thương?",options:["Chăn nuôi tuần lộc","Săn bắt cá voi ở Bắc Cực","Khai thác băng tuyết","Buôn bán qua cảng biển"],answer:3,explain:"Phù Nam nổi tiếng với hoạt động buôn bán qua cảng Óc Eo."}]}],challenge:{questions:[{id:"sd5-phu-nam-27",type:"order",q:"Sắp xếp các quốc gia cổ theo thời gian ra đời, từ sớm đến muộn.",items:["Văn Lang","Âu Lạc","Phù Nam"],explain:"Văn Lang ra đời sớm nhất, rồi đến Âu Lạc; Phù Nam hình thành khoảng thế kỉ I."},{id:"sd5-phu-nam-28",type:"match",q:"Nối di tích với quốc gia cổ.",pairs:[["Óc Eo","Phù Nam"],["Thành Cổ Loa","Âu Lạc"],["Đền Hùng","Văn Lang"]],explain:"Óc Eo – Phù Nam, Cổ Loa – Âu Lạc, Đền Hùng – Văn Lang."},{id:"sd5-phu-nam-29",type:"multi",q:"Phát biểu nào đúng về Phù Nam?",options:["Ra đời khoảng thế kỉ I","Có cảng thị Óc Eo","Đóng đô ở Phong Châu","Buôn bán với nhiều nước"],answers:[0,1,3],explain:"Phong Châu là kinh đô của Văn Lang, không phải Phù Nam."},{id:"sd5-phu-nam-30",type:"tf",q:"Óc Eo chỉ buôn bán với người trong vùng, không có hàng hóa nước ngoài.",answer:!1,explain:"Ở Óc Eo tìm thấy hàng hóa, tiền của nhiều nước, chứng tỏ buôn bán quốc tế."},{id:"sd5-phu-nam-31",type:"mc",q:"Nếu làm hướng dẫn viên ở di tích Óc Eo, em giới thiệu điều gì là chính xác?",options:["Đây là kinh đô của các vua Hùng","Đây là cảng thị lớn của Phù Nam","Đây là thành của An Dương Vương","Đây là nơi Ngô Quyền đánh giặc"],answer:1,explain:"Óc Eo là cảng thị lớn của vương quốc Phù Nam."},{id:"sd5-phu-nam-32",type:"tf",q:"Cư dân Phù Nam không biết làm đồ gốm.",answer:!1,explain:"Cư dân Phù Nam làm được nhiều đồ gốm, trang sức đẹp."}]},summary:["Phù Nam hình thành khoảng thế kỉ I ở vùng Nam Bộ ngày nay.","Óc Eo (An Giang) là cảng thị lớn, buôn bán với nhiều nước.","Văn hóa Óc Eo để lại nhiều đồ gốm, trang sức, tượng thần quý giá."]},{id:"sd5-champa",title:"Vương quốc Champa",weeks:[12,12],learn:[{title:"Ra đời ở miền Trung",text:"Khoảng thế kỉ II, vương quốc Champa hình thành ở vùng ven biển miền Trung nước ta ngày nay.",example:"🗺️ ven biển miền Trung"},{title:"Đời sống cư dân",text:"Cư dân Champa trồng lúa nước, đánh cá, làm gốm, buôn bán bằng đường biển. Họ có chữ viết riêng dựa trên chữ Phạn của Ấn Độ.",example:"🌾 🐟 ⛵"},{title:"Đền tháp Chăm",text:"Người Chăm xây nhiều đền tháp bằng gạch nung rất đẹp. Khu đền tháp Mỹ Sơn (nay thuộc thành phố Đà Nẵng) là Di sản văn hóa thế giới; tháp Bà Pô Na-ga ở Nha Trang (Khánh Hòa) rất nổi tiếng.",example:"🛕 Mỹ Sơn · Pô Na-ga"}],practice:[{questions:[{id:"sd5-champa-01",type:"mc",q:"Vương quốc Champa hình thành ở vùng nào nước ta ngày nay?",options:["Ven biển miền Trung","Đồng bằng Bắc Bộ","Nam Bộ","Miền núi phía bắc"],answer:0,explain:"Champa hình thành ở vùng ven biển miền Trung."},{id:"sd5-champa-02",type:"mc",q:"Champa ra đời vào khoảng thế kỉ nào?",options:["Thế kỉ I trước Công nguyên","Thế kỉ X","Thế kỉ II","Thế kỉ XVIII"],answer:2,explain:"Champa hình thành khoảng thế kỉ II."},{id:"sd5-champa-03",type:"mc",q:"Công trình kiến trúc tiêu biểu của người Chăm là:",options:["Đền tháp bằng gạch","Kim tự tháp đá","Nhà rông mái cao","Thành Cổ Loa"],answer:0,explain:"Người Chăm nổi tiếng với các đền tháp xây bằng gạch nung.",emoji:"🛕"},{id:"sd5-champa-04",type:"tf",q:"Khu đền tháp Mỹ Sơn là Di sản văn hóa thế giới.",answer:!0,explain:"Mỹ Sơn đã được UNESCO công nhận là Di sản văn hóa thế giới."},{id:"sd5-champa-05",type:"multi",q:"Cư dân Champa làm những nghề nào?",options:["Trồng lúa nước","Đánh cá","Buôn bán bằng đường biển","Chăn nuôi tuần lộc"],answers:[0,1,2],explain:"Cư dân Champa sống bằng trồng lúa, đánh cá, buôn bán."},{id:"sd5-champa-06",type:"tf",q:"Người Champa không có chữ viết riêng.",answer:!1,explain:"Người Champa có chữ viết riêng, dựa trên chữ Phạn của Ấn Độ."},{id:"sd5-champa-07",type:"fill",q:"Khu đền tháp … Sơn của người Chăm là Di sản văn hóa thế giới.",answer:["Mỹ"],explain:"Đó là khu đền tháp Mỹ Sơn."},{id:"sd5-champa-08",type:"mc",q:"Tháp Bà Pô Na-ga nằm ở thành phố nào?",options:["Nha Trang","Huế","Cần Thơ","Hạ Long"],answer:0,explain:"Tháp Bà Pô Na-ga nằm ở Nha Trang, tỉnh Khánh Hòa."},{id:"sd5-champa-09",type:"tf",q:"Champa nằm ở vùng đồng bằng sông Hồng.",answer:!1,explain:"Champa ở vùng ven biển miền Trung, không phải đồng bằng sông Hồng."}]},{questions:[{id:"sd5-champa-10",type:"mc",q:"Khu đền tháp Mỹ Sơn nay thuộc địa phương nào?",options:["Tỉnh Quảng Ngãi","Thành phố Huế","Tỉnh Khánh Hòa","Thành phố Đà Nẵng"],answer:3,explain:"Mỹ Sơn trước thuộc Quảng Nam; Quảng Nam đã hợp nhất vào Đà Nẵng."},{id:"sd5-champa-11",type:"match",q:"Nối di tích với quốc gia cổ.",pairs:[["Đền tháp Mỹ Sơn","Champa"],["Cảng thị Óc Eo","Phù Nam"],["Thành Cổ Loa","Âu Lạc"]],explain:"Mỹ Sơn – Champa, Óc Eo – Phù Nam, Cổ Loa – Âu Lạc."},{id:"sd5-champa-12",type:"mc",q:"Vì sao cư dân Champa giỏi đi biển và buôn bán?",options:["Vì sống xa biển","Vì sống ở sa mạc","Vì sống trên núi cao","Vì sống ở vùng ven biển"],answer:3,explain:"Champa ở ven biển miền Trung nên cư dân giỏi đi biển.",emoji:"⛵"},{id:"sd5-champa-13",type:"tf",q:"Champa và Phù Nam đều chịu ảnh hưởng văn hóa Ấn Độ.",answer:!0,explain:"Cả hai vương quốc tiếp thu chữ viết, tôn giáo, nghệ thuật Ấn Độ."},{id:"sd5-champa-14",type:"multi",q:"Đặc điểm nào đúng với đền tháp Chăm?",options:["Xây bằng gạch nung","Có nhiều hình chạm khắc đẹp","Làm bằng băng tuyết","Còn đứng vững đến ngày nay"],answers:[0,1,3],explain:"Đền tháp Chăm xây bằng gạch, chạm khắc tinh xảo, nhiều tháp còn đến nay."},{id:"sd5-champa-15",type:"mc",q:"Đất đai vùng ven biển miền Trung có đặc điểm gì khiến cư dân Champa phải làm thêm nghề biển?",options:["Đồng bằng nhỏ hẹp","Đồng bằng rất rộng","Toàn sa mạc","Không có biển"],answer:0,explain:"Đồng bằng nhỏ hẹp nên cư dân làm thêm nghề đánh cá, buôn bán biển."},{id:"sd5-champa-16",type:"tf",q:"Ngày nay không còn người Chăm sinh sống ở Việt Nam.",answer:!1,explain:"Người Chăm là một trong 54 dân tộc Việt Nam, vẫn giữ gìn văn hóa của mình."},{id:"sd5-champa-17",type:"mc",q:"Điệu múa nổi tiếng của người Chăm thường gắn với hình ảnh nào?",options:["Thiếu nữ đội bình nước","Múa lân sư rồng","Múa rối nước","Múa trên băng tuyết"],answer:0,explain:"Múa đội nước là điệu múa đặc sắc của người Chăm."},{id:"sd5-champa-18",type:"mc",q:"Vương quốc Champa có chữ viết dựa trên loại chữ nào?",options:["Chữ Hán","Chữ Phạn của Ấn Độ","Chữ La-tinh","Chữ tượng hình Ai Cập"],answer:1,explain:"Chữ Chăm cổ được tạo ra dựa trên chữ Phạn của Ấn Độ."}]},{questions:[{id:"sd5-champa-19",type:"mc",q:"Minh thấy một ngọn tháp gạch đỏ cổ kính ở Nha Trang. Đó có thể là công trình của cư dân vương quốc nào?",options:["Văn Lang","Âu Lạc","Phù Nam","Champa"],answer:3,explain:"Các tháp gạch cổ ở miền Trung là công trình của cư dân Champa."},{id:"sd5-champa-20",type:"tf",q:"Khi tham quan tháp Chăm, ta có thể leo trèo, khắc tên lên tường tháp để làm kỉ niệm.",answer:!1,explain:"Khắc tên, leo trèo làm hư hại di tích; cần tôn trọng và giữ gìn."},{id:"sd5-champa-21",type:"multi",q:"Đâu là di sản văn hóa của người Chăm?",options:["Khu đền tháp Mỹ Sơn","Tháp Bà Pô Na-ga","Điệu múa đội nước","Trống đồng Đông Sơn"],answers:[0,1,2],explain:"Trống đồng Đông Sơn là của người Việt cổ thời Văn Lang – Âu Lạc."},{id:"sd5-champa-22",type:"mc",q:"Ở đồng bằng nhỏ hẹp ven biển, cư dân Champa đã làm gì để có nước tưới ruộng?",options:["Đào giếng, dẫn nước","Phá rừng để làm đường","Đào kênh ra sa mạc","Dựng nhà băng giữ nước"],answer:0,explain:"Người Chăm giỏi làm giếng và hệ thống dẫn nước tưới."},{id:"sd5-champa-23",type:"mc",q:"Lễ hội Ka-tê là lễ hội truyền thống của dân tộc nào?",options:["Người Thái","Người Mông","Người Chăm","Người Tày"],answer:2,explain:"Ka-tê là lễ hội lớn của người Chăm."},{id:"sd5-champa-24",type:"tf",q:"Champa, Phù Nam và Văn Lang – Âu Lạc là những quốc gia đầu tiên trên lãnh thổ Việt Nam.",answer:!0,explain:"Đó là ba quốc gia cổ trên lãnh thổ nước ta ngày nay."},{id:"sd5-champa-25",type:"mc",q:"Vì sao các nhà khoa học vẫn nghiên cứu cách người Chăm xây tháp gạch?",options:["Vì tháp được xây bằng thép và kính","Vì tháp mới được xây năm ngoái","Vì tháp làm hoàn toàn bằng gỗ","Vì gạch gắn rất chắc, chưa giải thích hết"],answer:3,explain:"Kĩ thuật xây tháp gạch của người Chăm còn nhiều điều bí ẩn."},{id:"sd5-champa-26",type:"mc",q:"Em có thể làm gì để giới thiệu văn hóa Chăm với bạn bè?",options:["Chê văn hóa Chăm là lạc hậu","Sưu tầm ảnh tháp Chăm, kể cho bạn","Lấy gạch ở tháp về làm kỉ niệm","Không quan tâm, không tìm hiểu"],answer:1,explain:"Tìm hiểu và giới thiệu giúp lan tỏa giá trị văn hóa Chăm."}]}],challenge:{questions:[{id:"sd5-champa-27",type:"match",q:"Nối quốc gia cổ với thời gian ra đời.",pairs:[["Văn Lang","Khoảng thế kỉ VII trước Công nguyên"],["Phù Nam","Khoảng thế kỉ I"],["Champa","Khoảng thế kỉ II"]],explain:"Văn Lang ra đời khoảng thế kỉ VII trước Công nguyên, Phù Nam khoảng thế kỉ I, Champa khoảng thế kỉ II."},{id:"sd5-champa-28",type:"match",q:"Nối quốc gia cổ với vùng đất.",pairs:[["Văn Lang","Đồng bằng sông Hồng"],["Champa","Ven biển miền Trung"],["Phù Nam","Nam Bộ"]],explain:"Mỗi quốc gia cổ hình thành ở một vùng của nước ta ngày nay."},{id:"sd5-champa-29",type:"multi",q:"Ba quốc gia cổ Văn Lang – Âu Lạc, Phù Nam, Champa có điểm chung nào?",options:["Đều trồng lúa nước","Đều nằm trên lãnh thổ Việt Nam ngày nay","Đều đóng đô ở Cổ Loa","Đều xây kim tự tháp"],answers:[0,1],explain:"Cả ba đều trồng lúa nước và nằm trên lãnh thổ nước ta ngày nay."},{id:"sd5-champa-30",type:"tf",q:"Khu đền tháp Mỹ Sơn được UNESCO ghi danh là Di sản văn hóa thế giới.",answer:!0,explain:"Mỹ Sơn là một trong các di sản văn hóa thế giới của Việt Nam."},{id:"sd5-champa-31",type:"mc",q:"Phát biểu nào sai?",options:["Champa có chữ viết riêng","Người Chăm giỏi xây tháp gạch","Champa buôn bán bằng đường biển","Champa hình thành ở vùng núi Tây Bắc"],answer:3,explain:"Champa ở ven biển miền Trung, không phải vùng núi Tây Bắc."},{id:"sd5-champa-32",type:"order",q:"Sắp xếp các công trình từ bắc vào nam.",items:["Thành Cổ Loa (Hà Nội)","Thánh địa Mỹ Sơn (Đà Nẵng)","Tháp Bà Pô Na-ga (Khánh Hòa)","Di tích Óc Eo (An Giang)"],explain:"Hà Nội ở phía bắc, rồi đến Đà Nẵng, Khánh Hòa, An Giang ở phía nam."}]},summary:["Champa hình thành khoảng thế kỉ II ở vùng ven biển miền Trung.","Cư dân Champa trồng lúa, đánh cá, buôn bán đường biển, có chữ viết riêng.","Khu đền tháp Mỹ Sơn là Di sản văn hóa thế giới."]}]},{id:"dau-tranh-bac-thuoc",title:"Đấu tranh giành độc lập thời Bắc thuộc",lessons:[{id:"sd5-hai-ba-trung",title:"Khởi nghĩa Hai Bà Trưng",weeks:[13,13],learn:[{title:"Hơn một nghìn năm Bắc thuộc",text:"Sau khi nước Âu Lạc mất, nước ta bị các triều đại phong kiến phương Bắc đô hộ hơn một nghìn năm. Nhân dân ta nhiều lần đứng lên khởi nghĩa giành độc lập.",example:"⛓️ ➜ ✊"},{title:"Khởi nghĩa Hai Bà Trưng",text:"Mùa xuân năm 40, Trưng Trắc và Trưng Nhị phất cờ khởi nghĩa ở Mê Linh, chống ách đô hộ của nhà Hán. Nghĩa quân đánh đuổi quân Hán, Trưng Trắc lên làm vua, gọi là Trưng Vương.",example:"⚔️ năm 40 · Mê Linh"},{title:"Những tấm gương khác",text:"Năm 248, Bà Triệu khởi nghĩa ở vùng núi Nưa (Thanh Hóa). Năm 544, Lý Bí lên ngôi hoàng đế, đặt tên nước là Vạn Xuân.",example:"🐘 Bà Triệu · 🏯 Vạn Xuân"}],practice:[{questions:[{id:"sd5-hai-ba-trung-01",type:"mc",q:"Khởi nghĩa Hai Bà Trưng nổ ra vào năm nào?",options:["Năm 938","Năm 248","Năm 1010","Năm 40"],answer:3,explain:"Hai Bà Trưng khởi nghĩa vào mùa xuân năm 40.",emoji:"⚔️"},{id:"sd5-hai-ba-trung-02",type:"mc",q:"Hai Bà Trưng khởi nghĩa chống lại ách đô hộ của nhà nào?",options:["Nhà Tống","Nhà Hán","Nhà Minh","Nhà Thanh"],answer:1,explain:"Hai Bà Trưng chống ách đô hộ của nhà Hán."},{id:"sd5-hai-ba-trung-03",type:"mc",q:"Hai Bà Trưng phất cờ khởi nghĩa ở đâu?",options:["Cổ Loa","Lam Sơn","Hoa Lư","Mê Linh"],answer:3,explain:"Hai Bà phất cờ khởi nghĩa ở Mê Linh."},{id:"sd5-hai-ba-trung-04",type:"tf",q:"Hai Bà Trưng là hai chị em Trưng Trắc và Trưng Nhị.",answer:!0,explain:"Hai Bà Trưng là Trưng Trắc (chị) và Trưng Nhị (em)."},{id:"sd5-hai-ba-trung-05",type:"tf",q:"Sau khi khởi nghĩa thắng lợi, Trưng Nhị lên làm vua.",answer:!1,explain:"Trưng Trắc lên làm vua, gọi là Trưng Vương."},{id:"sd5-hai-ba-trung-06",type:"fill",q:"Sau khi đánh đuổi quân Hán, Trưng Trắc lên làm vua, gọi là … Vương.",answer:["Trưng"],explain:"Trưng Trắc lên ngôi, gọi là Trưng Vương."},{id:"sd5-hai-ba-trung-07",type:"mc",q:"Năm 544, Lý Bí lên ngôi và đặt tên nước là:",options:["Văn Lang","Đại Việt","Vạn Xuân","Âu Lạc"],answer:2,explain:"Lý Bí lên ngôi hoàng đế, đặt tên nước là Vạn Xuân."},{id:"sd5-hai-ba-trung-08",type:"mc",q:"Năm 248, ai lãnh đạo cuộc khởi nghĩa ở vùng núi Nưa (Thanh Hóa)?",options:["Hai Bà Trưng","Ngô Quyền","Lý Bí","Bà Triệu"],answer:3,explain:"Bà Triệu khởi nghĩa năm 248 ở vùng núi Nưa, Thanh Hóa.",emoji:"🐘"},{id:"sd5-hai-ba-trung-09",type:"tf",q:"Thời Bắc thuộc chỉ kéo dài khoảng một trăm năm.",answer:!1,explain:"Thời Bắc thuộc kéo dài hơn một nghìn năm, đến năm 938 mới chấm dứt."}]},{questions:[{id:"sd5-hai-ba-trung-10",type:"order",q:"Sắp xếp các cuộc khởi nghĩa theo thứ tự thời gian.",items:["Khởi nghĩa Hai Bà Trưng","Khởi nghĩa Bà Triệu","Lý Bí lập nước Vạn Xuân"],explain:"Năm 40 – Hai Bà Trưng, năm 248 – Bà Triệu, năm 544 – Lý Bí lập nước Vạn Xuân."},{id:"sd5-hai-ba-trung-11",type:"match",q:"Nối nhân vật với năm.",pairs:[["Hai Bà Trưng khởi nghĩa","Năm 40"],["Bà Triệu khởi nghĩa","Năm 248"],["Lý Bí lập nước Vạn Xuân","Năm 544"]],explain:"Hai Bà Trưng: năm 40; Bà Triệu: năm 248; Lý Bí lập nước Vạn Xuân: năm 544."},{id:"sd5-hai-ba-trung-12",type:"mc",q:"Vì sao nhân dân ta nhiều lần khởi nghĩa trong thời Bắc thuộc?",options:["Vì không chịu bị đô hộ, muốn độc lập","Vì muốn đi đến những vùng đất xa","Vì thích chiến tranh, thích đánh nhau","Vì thiếu nhà ở và ruộng đất"],answer:0,explain:"Nhân dân ta khao khát độc lập, không cam chịu bị đô hộ."},{id:"sd5-hai-ba-trung-13",type:"tf",q:"Khởi nghĩa Hai Bà Trưng cho thấy phụ nữ Việt Nam rất anh hùng, yêu nước.",answer:!0,explain:"Hai Bà Trưng là tấm gương tiêu biểu của phụ nữ Việt Nam."},{id:"sd5-hai-ba-trung-14",type:"multi",q:"Ai là những phụ nữ lãnh đạo khởi nghĩa thời Bắc thuộc?",options:["Trưng Trắc","Trưng Nhị","Bà Triệu","Lý Bí"],answers:[0,1,2],explain:"Lý Bí là nam; ba người còn lại là những nữ anh hùng."},{id:"sd5-hai-ba-trung-15",type:"mc",q:"Ý nghĩa của khởi nghĩa Hai Bà Trưng là gì?",options:["Mở đầu thời kì Bắc thuộc ở nước ta","Dời kinh đô về thành Thăng Long","Chấm dứt hoàn toàn thời Bắc thuộc","Khẳng định ý chí giành độc lập của dân ta"],answer:3,explain:"Khởi nghĩa thể hiện ý chí giành độc lập; Bắc thuộc chấm dứt năm 938."},{id:"sd5-hai-ba-trung-16",type:"tf",q:"Khởi nghĩa Hai Bà Trưng đã chấm dứt hoàn toàn thời kì Bắc thuộc.",answer:!1,explain:"Năm 43 quân Hán đàn áp, nước ta lại bị đô hộ; đến năm 938 Bắc thuộc mới chấm dứt."},{id:"sd5-hai-ba-trung-17",type:"mc",q:"Lý Bí đặt tên nước là Vạn Xuân với mong muốn gì?",options:["Đất nước thật nhỏ bé","Đất nước có nhiều tuyết","Đất nước chỉ có mùa xuân","Đất nước bền vững muôn đời"],answer:3,explain:"Vạn Xuân nghĩa là muôn mùa xuân, mong đất nước bền vững lâu dài."},{id:"sd5-hai-ba-trung-18",type:"mc",q:"Hai Bà Trưng thuộc thời kì nào của lịch sử nước ta?",options:["Thời Văn Lang","Thời nhà Trần","Thời Bắc thuộc","Thời nhà Nguyễn"],answer:2,explain:"Hai Bà Trưng khởi nghĩa trong thời kì Bắc thuộc."}]},{questions:[{id:"sd5-hai-ba-trung-19",type:"mc",q:"Ở Hà Nội có phố Hai Bà Trưng và các đền thờ Hai Bà. Điều đó thể hiện gì?",options:["Nhân dân biết ơn công lao của Hai Bà","Hai Bà từng sống ở chính phố đó","Hai Bà đã xây dựng các con phố đó","Không có ý nghĩa gì đặc biệt"],answer:0,explain:"Đặt tên đường, lập đền thờ là cách nhân dân tưởng nhớ người anh hùng."},{id:"sd5-hai-ba-trung-20",type:"tf",q:"Bà Triệu từng nói: muốn cưỡi cơn gió mạnh, đạp luồng sóng dữ, chém cá kình ở biển Đông, đánh đuổi quân xâm lược.",answer:!0,explain:"Câu nói nổi tiếng thể hiện ý chí lớn của Bà Triệu."},{id:"sd5-hai-ba-trung-21",type:"mc",q:"Nhóm Lan làm báo tường về “Nữ anh hùng thời Bắc thuộc”. Nhân vật nào phù hợp?",options:["Ngô Quyền","Bà Triệu","Lý Thái Tổ","Quang Trung"],answer:1,explain:"Bà Triệu là nữ anh hùng thời Bắc thuộc."},{id:"sd5-hai-ba-trung-22",type:"multi",q:"Học tập Hai Bà Trưng, em có thể làm gì?",options:["Chăm học để mai sau xây dựng đất nước","Tìm hiểu, kể lại chuyện Hai Bà cho bạn bè","Trêu chọc bạn gái","Kính trọng phụ nữ"],answers:[0,1,3],explain:"Học tập tốt, tìm hiểu lịch sử, tôn trọng phụ nữ là những việc làm đúng."},{id:"sd5-hai-ba-trung-23",type:"mc",q:"Từ năm 40 đến năm 248 là bao nhiêu năm?",options:["108 năm","208 năm","288 năm","200 năm"],answer:1,explain:"248 − 40 = 208 năm."},{id:"sd5-hai-ba-trung-24",type:"tf",q:"Lý Bí lên ngôi hoàng đế sau khởi nghĩa Bà Triệu.",answer:!0,explain:"Bà Triệu khởi nghĩa năm 248, Lý Bí lên ngôi năm 544."},{id:"sd5-hai-ba-trung-25",type:"mc",q:"Câu nào nói đúng về thời Bắc thuộc?",options:["Nhân dân ta liên tục đấu tranh giành độc lập","Nhân dân ta cam chịu, không đấu tranh","Nước ta luôn được độc lập, tự do","Chỉ có một cuộc khởi nghĩa duy nhất"],answer:0,explain:"Thời Bắc thuộc có nhiều cuộc khởi nghĩa liên tiếp."},{id:"sd5-hai-ba-trung-26",type:"number",q:"Lý Bí lên ngôi năm 544. Khởi nghĩa Hai Bà Trưng năm 40. Hai sự kiện cách nhau bao nhiêu năm?",answer:504,explain:"544 − 40 = 504 năm.",unit:"năm"}]}],challenge:{questions:[{id:"sd5-hai-ba-trung-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Nước Âu Lạc ra đời","Hai Bà Trưng khởi nghĩa","Bà Triệu khởi nghĩa","Lý Bí lập nước Vạn Xuân"],explain:"Âu Lạc có trước Công nguyên, rồi đến năm 40, năm 248, năm 544."},{id:"sd5-hai-ba-trung-28",type:"multi",q:"Phát biểu nào đúng?",options:["Hai Bà Trưng khởi nghĩa năm 40","Lý Bí đặt tên nước là Vạn Xuân","Bà Triệu khởi nghĩa ở Mê Linh","Bắc thuộc kéo dài hơn một nghìn năm"],answers:[0,1,3],explain:"Bà Triệu khởi nghĩa ở vùng núi Nưa (Thanh Hóa), không phải Mê Linh."},{id:"sd5-hai-ba-trung-29",type:"tf",q:"Khởi nghĩa Hai Bà Trưng giữ được độc lập suốt một nghìn năm.",answer:!1,explain:"Năm 43, quân Hán sang đàn áp, khởi nghĩa thất bại; nước ta lại bị đô hộ."},{id:"sd5-hai-ba-trung-30",type:"mc",q:"Vì sao dù bị đô hộ hơn nghìn năm, người Việt vẫn giữ được tiếng nói và phong tục?",options:["Vì không có ai đến nước ta","Vì quân đô hộ khuyến khích người Việt","Vì nhân dân luôn giữ gìn văn hóa dân tộc","Vì người Việt sống tách biệt trên đảo"],answer:2,explain:"Lòng yêu nước giúp người Việt giữ tiếng nói, phong tục suốt thời Bắc thuộc."},{id:"sd5-hai-ba-trung-31",type:"number",q:"Khởi nghĩa Hai Bà Trưng năm 40, Hai Bà hi sinh năm 43. Hai Bà giữ được độc lập khoảng bao nhiêu năm?",answer:3,explain:"43 − 40 = 3 năm.",unit:"năm"},{id:"sd5-hai-ba-trung-32",type:"match",q:"Nối nhân vật với địa danh gắn bó.",pairs:[["Hai Bà Trưng","Mê Linh"],["Bà Triệu","Núi Nưa"],["An Dương Vương","Cổ Loa"]],explain:"Hai Bà Trưng – Mê Linh, Bà Triệu – núi Nưa, An Dương Vương – Cổ Loa."}]},summary:["Năm 40, Hai Bà Trưng khởi nghĩa ở Mê Linh, đánh đuổi quân Hán.","Khởi nghĩa Hai Bà Trưng thể hiện tinh thần yêu nước và vai trò to lớn của phụ nữ Việt Nam.","Bà Triệu (năm 248), Lý Bí (năm 544) tiếp nối truyền thống đấu tranh giành độc lập."]},{id:"sd5-ngo-quyen-bach-dang",title:"Ngô Quyền và chiến thắng Bạch Đằng năm 938",weeks:[14,14],learn:[{title:"Quân Nam Hán sang xâm lược",text:"Năm 938, quân Nam Hán kéo sang xâm lược nước ta theo đường biển. Ngô Quyền lãnh đạo nhân dân đánh giặc.",example:"⛵⛵ ➜ 🌊"},{title:"Trận địa cọc",text:"Ngô Quyền cho đóng cọc gỗ đầu nhọn, bịt sắt xuống lòng sông Bạch Đằng. Khi nước triều lên, ta nhử thuyền giặc vào; khi nước triều rút, cọc nhô lên, thuyền giặc bị vỡ, quân ta tấn công.",example:"🪵🪵 sông Bạch Đằng"},{title:"Ý nghĩa",text:"Chiến thắng Bạch Đằng năm 938 chấm dứt hơn một nghìn năm Bắc thuộc. Năm 939, Ngô Quyền xưng vương, đóng đô ở Cổ Loa.",example:"🏆 938 · 👑 939"}],practice:[{questions:[{id:"sd5-ngo-quyen-bach-dang-01",type:"mc",q:"Chiến thắng Bạch Đằng của Ngô Quyền diễn ra vào năm nào?",options:["Năm 40","Năm 1010","Năm 1288","Năm 938"],answer:3,explain:"Ngô Quyền đánh tan quân Nam Hán năm 938.",emoji:"🌊"},{id:"sd5-ngo-quyen-bach-dang-02",type:"mc",q:"Ngô Quyền đánh tan quân xâm lược nào?",options:["Quân Hán","Quân Nam Hán","Quân Mông – Nguyên","Quân Thanh"],answer:1,explain:"Năm 938, Ngô Quyền đánh tan quân Nam Hán."},{id:"sd5-ngo-quyen-bach-dang-03",type:"mc",q:"Trận đánh năm 938 diễn ra trên sông nào?",options:["Sông Hồng","Sông Như Nguyệt","Sông Mê Công","Sông Bạch Đằng"],answer:3,explain:"Trận đánh diễn ra trên sông Bạch Đằng."},{id:"sd5-ngo-quyen-bach-dang-04",type:"tf",q:"Ngô Quyền cho đóng cọc gỗ đầu nhọn, bịt sắt xuống lòng sông.",answer:!0,explain:"Bãi cọc ngầm là trận địa nổi tiếng của Ngô Quyền.",emoji:"🪵"},{id:"sd5-ngo-quyen-bach-dang-05",type:"tf",q:"Chiến thắng Bạch Đằng năm 938 chấm dứt thời kì Bắc thuộc.",answer:!0,explain:"Chiến thắng này kết thúc hơn một nghìn năm Bắc thuộc."},{id:"sd5-ngo-quyen-bach-dang-06",type:"mc",q:"Năm 939, Ngô Quyền xưng vương và đóng đô ở đâu?",options:["Cổ Loa","Hoa Lư","Thăng Long","Phú Xuân"],answer:0,explain:"Ngô Quyền đóng đô ở Cổ Loa."},{id:"sd5-ngo-quyen-bach-dang-07",type:"fill",q:"Năm 938, Ngô Quyền chiến thắng trên sông Bạch … .",answer:["Đằng"],explain:"Đó là chiến thắng Bạch Đằng."},{id:"sd5-ngo-quyen-bach-dang-08",type:"tf",q:"Quân Nam Hán kéo sang nước ta bằng đường biển.",answer:!0,explain:"Quân Nam Hán theo đường biển tiến vào sông Bạch Đằng.",emoji:"⛵"},{id:"sd5-ngo-quyen-bach-dang-09",type:"mc",q:"Ngô Quyền đã lợi dụng hiện tượng tự nhiên nào để đánh giặc?",options:["Gió bão","Thủy triều lên xuống","Động đất","Mưa lớn đầu nguồn"],answer:1,explain:"Ngô Quyền dựa vào lúc triều lên, triều xuống để bố trí trận đánh."}]},{questions:[{id:"sd5-ngo-quyen-bach-dang-10",type:"order",q:"Sắp xếp diễn biến trận Bạch Đằng năm 938.",items:["Đóng cọc gỗ bịt sắt dưới lòng sông","Nhử thuyền giặc vào lúc nước triều lên","Nước triều rút, thuyền giặc va vào cọc","Quân ta đổ ra tấn công, giặc thua chạy"],explain:"Chuẩn bị bãi cọc → nhử địch lúc triều lên → triều rút, thuyền giặc vỡ → quân ta tấn công."},{id:"sd5-ngo-quyen-bach-dang-11",type:"mc",q:"Vì sao phải nhử thuyền giặc vào lúc nước triều lên?",options:["Để quân ta dễ bơi lội","Để thuyền giặc đi nhanh hơn","Để nước che khuất bãi cọc","Để giặc nhìn thấy bãi cọc"],answer:2,explain:"Triều lên, nước ngập cọc nên giặc không phát hiện ra bãi cọc."},{id:"sd5-ngo-quyen-bach-dang-12",type:"tf",q:"Khi nước triều lên, cọc nhô cao làm thuyền giặc bị vỡ.",answer:!1,explain:"Cọc chỉ nhô lên khi nước triều rút; lúc triều lên, nước che khuất cọc."},{id:"sd5-ngo-quyen-bach-dang-13",type:"multi",q:"Chiến thắng Bạch Đằng năm 938 có ý nghĩa gì?",options:["Chấm dứt hơn một nghìn năm Bắc thuộc","Mở ra thời kì độc lập lâu dài","Mở đầu thời kì Bắc thuộc","Dời đô về Thăng Long"],answers:[0,1],explain:"Năm 938 chấm dứt Bắc thuộc, mở ra thời kì độc lập."},{id:"sd5-ngo-quyen-bach-dang-14",type:"match",q:"Nối sự kiện với năm.",pairs:[["Chiến thắng Bạch Đằng","Năm 938"],["Ngô Quyền xưng vương","Năm 939"],["Hai Bà Trưng khởi nghĩa","Năm 40"]],explain:"Năm 40 – Hai Bà Trưng; năm 938 – Bạch Đằng; năm 939 – Ngô Quyền xưng vương."},{id:"sd5-ngo-quyen-bach-dang-15",type:"mc",q:"Cách đánh của Ngô Quyền cho thấy ông là người:",options:["Liều lĩnh, thiếu suy nghĩ","Chỉ trông chờ vào may mắn","Nhút nhát, sợ đối đầu với giặc","Mưu trí, biết dựa vào thiên nhiên"],answer:3,explain:"Ông biết dùng thủy triều và bãi cọc để thắng giặc mạnh."},{id:"sd5-ngo-quyen-bach-dang-16",type:"tf",q:"Ngô Quyền xưng vương và đóng đô ở Thăng Long.",answer:!1,explain:"Ngô Quyền đóng đô ở Cổ Loa; Thăng Long là kinh đô từ thời Lý."},{id:"sd5-ngo-quyen-bach-dang-17",type:"mc",q:"Sông Bạch Đằng nằm ở vùng nào ngày nay?",options:["Đồng bằng Nam Bộ","Giữa Huế và Đà Nẵng","Cao nguyên Tây Nguyên","Giữa Quảng Ninh và Hải Phòng"],answer:3,explain:"Sông Bạch Đằng chảy qua vùng giáp ranh Quảng Ninh và Hải Phòng."},{id:"sd5-ngo-quyen-bach-dang-18",type:"mc",q:"Ngô Quyền có quê ở Đường Lâm, nay thuộc:",options:["Thanh Hóa","Nghệ An","Hà Nội","Quảng Ninh"],answer:2,explain:"Đường Lâm nay thuộc Thủ đô Hà Nội."}]},{questions:[{id:"sd5-ngo-quyen-bach-dang-19",type:"mc",q:"Nếu giặc đến vào lúc nước ròng mà ta chưa kịp nhử, điều gì có thể xảy ra?",options:["Giặc thấy bãi cọc và tránh được","Giặc chắc chắn thua ngay lập tức","Thủy triều không bao giờ thay đổi","Cọc tự trôi mất theo dòng nước"],answer:0,explain:"Khi nước cạn, cọc lộ ra nên giặc dễ phát hiện; vì thế chọn đúng thời điểm rất quan trọng."},{id:"sd5-ngo-quyen-bach-dang-20",type:"tf",q:"Ngô Quyền được coi là người mở đầu thời kì độc lập lâu dài của dân tộc.",answer:!0,explain:"Sau năm 938, nước ta bước vào thời kì độc lập lâu dài."},{id:"sd5-ngo-quyen-bach-dang-21",type:"mc",q:"Bình đố: “Trận đánh nào dùng bãi cọc ngầm trên sông và chấm dứt thời Bắc thuộc?” Đáp án là:",options:["Chiến thắng Chi Lăng","Chiến thắng Bạch Đằng năm 938","Chiến thắng Điện Biên Phủ","Chiến thắng Ngọc Hồi – Đống Đa"],answer:1,explain:"Đó là chiến thắng Bạch Đằng năm 938 của Ngô Quyền."},{id:"sd5-ngo-quyen-bach-dang-22",type:"number",q:"Năm 938 cách năm 40 bao nhiêu năm?",answer:898,explain:"938 − 40 = 898 năm.",unit:"năm"},{id:"sd5-ngo-quyen-bach-dang-23",type:"multi",q:"Bài học nào rút ra từ chiến thắng Bạch Đằng năm 938?",options:["Biết dựa vào địa hình, thiên nhiên","Chuẩn bị kĩ trước khi đánh","Chỉ cần đông người là thắng","Đoàn kết toàn dân"],answers:[0,1,3],explain:"Chuẩn bị kĩ, mưu trí và đoàn kết là chìa khóa thắng lợi."},{id:"sd5-ngo-quyen-bach-dang-24",type:"tf",q:"Bãi cọc của Ngô Quyền được đóng trên đỉnh núi.",answer:!1,explain:"Bãi cọc được đóng dưới lòng sông Bạch Đằng."},{id:"sd5-ngo-quyen-bach-dang-25",type:"mc",q:"Ngày nay, cách tốt nhất để tưởng nhớ Ngô Quyền là:",options:["Tìm hiểu lịch sử, giữ gìn di tích","Đóng thêm cọc ở các con sông","Quên đi những chuyện đã qua","Viết tên mình lên tường đền thờ"],answer:0,explain:"Tìm hiểu và giữ gìn di tích là cách thể hiện lòng biết ơn."},{id:"sd5-ngo-quyen-bach-dang-26",type:"mc",q:"Trước năm 938, nước ta đang ở thời kì nào?",options:["Thời Lý","Thời Trần","Thời Bắc thuộc","Thời Văn Lang"],answer:2,explain:"Trước năm 938 là thời Bắc thuộc."}]}],challenge:{questions:[{id:"sd5-ngo-quyen-bach-dang-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Hai Bà Trưng khởi nghĩa","Lý Bí lập nước Vạn Xuân","Chiến thắng Bạch Đằng của Ngô Quyền","Ngô Quyền xưng vương"],explain:"Năm 40 → năm 544 → năm 938 → năm 939."},{id:"sd5-ngo-quyen-bach-dang-28",type:"match",q:"Nối nhân vật với quân xâm lược mà họ chống lại.",pairs:[["Hai Bà Trưng","Quân Hán"],["Ngô Quyền","Quân Nam Hán"],["Trần Hưng Đạo","Quân Mông – Nguyên"]],explain:"Hai Bà Trưng – quân Hán, Ngô Quyền – quân Nam Hán, Trần Hưng Đạo – quân Mông – Nguyên."},{id:"sd5-ngo-quyen-bach-dang-29",type:"tf",q:"Sông Bạch Đằng còn chứng kiến chiến thắng của quân dân nhà Trần năm 1288.",answer:!0,explain:"Năm 1288, Trần Hưng Đạo cũng dùng bãi cọc đánh tan quân Nguyên trên sông Bạch Đằng."},{id:"sd5-ngo-quyen-bach-dang-30",type:"mc",q:"Vì sao chiến thắng năm 938 được xem là mốc rất quan trọng?",options:["Vì từ đó nước ta mất độc lập","Vì là trận đánh đầu tiên của nước ta","Vì mở ra thời kì độc lập lâu dài","Vì sau trận đó vua dời đô về Huế"],answer:2,explain:"Từ năm 938, nước ta bước vào thời kì độc lập lâu dài."},{id:"sd5-ngo-quyen-bach-dang-31",type:"multi",q:"Điều nào đúng về Ngô Quyền?",options:["Đánh tan quân Nam Hán năm 938","Xưng vương năm 939","Dời đô về Thăng Long","Đóng đô ở Cổ Loa"],answers:[0,1,3],explain:"Dời đô về Thăng Long là việc của Lý Thái Tổ năm 1010."},{id:"sd5-ngo-quyen-bach-dang-32",type:"number",q:"Chiến thắng Bạch Đằng năm 938, Lý Thái Tổ dời đô năm 1010. Hai sự kiện cách nhau bao nhiêu năm?",answer:72,explain:"1010 − 938 = 72 năm.",unit:"năm"}]},summary:["Năm 938, Ngô Quyền đánh tan quân Nam Hán trên sông Bạch Đằng.","Trận địa cọc dựa vào thủy triều là cách đánh rất mưu trí.","Chiến thắng chấm dứt hơn một nghìn năm Bắc thuộc, mở ra thời kì độc lập lâu dài."]}]},{id:"ly-tran",title:"Nhà Lý và nhà Trần",lessons:[{id:"sd5-nha-ly-thang-long",title:"Nhà Lý và việc dời đô về Thăng Long",weeks:[15,15],learn:[{title:"Dời đô về Thăng Long",text:"Năm 1009, Lý Công Uẩn lên ngôi vua, lập ra nhà Lý (Lý Thái Tổ). Năm 1010, nhà vua ban Chiếu dời đô, dời kinh đô từ Hoa Lư (Ninh Bình) về thành Đại La và đổi tên là Thăng Long.",example:"🐉 1010 · Hoa Lư ➜ Thăng Long"},{title:"Vì sao chọn Đại La?",text:"Đại La ở trung tâm đất nước, đất rộng, bằng phẳng, cao ráo, giao thông thuận tiện, muôn vật phong phú – nơi có thể làm kinh đô lâu dài.",example:"🏯 trung tâm đất nước"},{title:"Thành tựu thời Lý",text:"Năm 1054, nhà Lý đổi tên nước là Đại Việt. Năm 1070 xây Văn Miếu; năm 1076 lập Quốc Tử Giám. Lý Thường Kiệt chỉ huy kháng chiến chống quân Tống, chiến thắng trên phòng tuyến sông Như Nguyệt năm 1077.",example:"📜 Văn Miếu – Quốc Tử Giám"}],practice:[{questions:[{id:"sd5-nha-ly-thang-long-01",type:"mc",q:"Lý Thái Tổ dời đô về Thăng Long vào năm nào?",options:["Năm 938","Năm 1054","Năm 1010","Năm 1288"],answer:2,explain:"Năm 1010, Lý Thái Tổ dời đô về Đại La, đổi tên là Thăng Long.",emoji:"🐉"},{id:"sd5-nha-ly-thang-long-02",type:"mc",q:"Trước khi dời về Thăng Long, kinh đô ở đâu?",options:["Hoa Lư","Cổ Loa","Phú Xuân","Phong Châu"],answer:0,explain:"Kinh đô trước đó ở Hoa Lư (Ninh Bình)."},{id:"sd5-nha-ly-thang-long-03",type:"tf",q:"Lý Công Uẩn chính là vua Lý Thái Tổ.",answer:!0,explain:"Lý Công Uẩn lên ngôi năm 1009, hiệu là Lý Thái Tổ."},{id:"sd5-nha-ly-thang-long-04",type:"fill",q:"Năm 1010, thành Đại La được đổi tên là … Long.",answer:["Thăng"],explain:"Đại La được đổi tên là Thăng Long, nghĩa là rồng bay lên."},{id:"sd5-nha-ly-thang-long-05",type:"mc",q:"Năm 1054, nhà Lý đổi tên nước là:",options:["Vạn Xuân","Văn Lang","Đại Nam","Đại Việt"],answer:3,explain:"Năm 1054, nước ta có tên là Đại Việt."},{id:"sd5-nha-ly-thang-long-06",type:"mc",q:"Ai chỉ huy cuộc kháng chiến chống quân Tống thời Lý?",options:["Ngô Quyền","Lý Thường Kiệt","Trần Hưng Đạo","Lê Lợi"],answer:1,explain:"Lý Thường Kiệt chỉ huy kháng chiến chống quân Tống."},{id:"sd5-nha-ly-thang-long-07",type:"tf",q:"Văn Miếu được xây dựng dưới thời nhà Nguyễn.",answer:!1,explain:"Văn Miếu được xây năm 1070, dưới thời nhà Lý.",emoji:"📜"},{id:"sd5-nha-ly-thang-long-08",type:"mc",q:"Thăng Long ngày nay là thành phố nào?",options:["Huế","Ninh Bình","Hà Nội","Hải Phòng"],answer:2,explain:"Thăng Long chính là Thủ đô Hà Nội ngày nay."},{id:"sd5-nha-ly-thang-long-09",type:"tf",q:"Hoa Lư, kinh đô cũ trước thời Lý, nay thuộc tỉnh Ninh Bình.",answer:!0,explain:"Cố đô Hoa Lư nằm ở tỉnh Ninh Bình."}]},{questions:[{id:"sd5-nha-ly-thang-long-10",type:"multi",q:"Vì sao Lý Thái Tổ chọn Đại La làm kinh đô?",options:["Ở trung tâm đất nước","Đất rộng, bằng phẳng, cao ráo","Giao thông thuận tiện","Có nhiều núi đá hiểm trở, chật hẹp"],answers:[0,1,2],explain:"Đại La rộng, bằng phẳng, ở trung tâm, thuận tiện – hợp làm kinh đô lâu dài."},{id:"sd5-nha-ly-thang-long-11",type:"mc",q:"Hoa Lư có đặc điểm gì khiến không hợp làm kinh đô lâu dài?",options:["Rộng rãi, bằng phẳng","Gần nhiều chợ","Nằm giữa đồng bằng lớn","Chật hẹp, nhiều núi đá"],answer:3,explain:"Hoa Lư nhiều núi đá, hợp phòng thủ nhưng chật hẹp, khó phát triển."},{id:"sd5-nha-ly-thang-long-12",type:"order",q:"Sắp xếp các sự kiện thời Lý theo thứ tự thời gian.",items:["Lý Thái Tổ dời đô về Thăng Long","Đổi tên nước là Đại Việt","Xây dựng Văn Miếu","Chiến thắng quân Tống trên sông Như Nguyệt"],explain:"Năm 1010 → năm 1054 → năm 1070 → năm 1077."},{id:"sd5-nha-ly-thang-long-13",type:"match",q:"Nối sự kiện với năm.",pairs:[["Dời đô về Thăng Long","Năm 1010"],["Đổi tên nước là Đại Việt","Năm 1054"],["Xây Văn Miếu","Năm 1070"],["Lập Quốc Tử Giám","Năm 1076"]],explain:"Năm 1010 dời đô, năm 1054 đổi tên nước, năm 1070 xây Văn Miếu, năm 1076 lập Quốc Tử Giám."},{id:"sd5-nha-ly-thang-long-14",type:"tf",q:"Quốc Tử Giám được coi là trường đại học đầu tiên của nước ta.",answer:!0,explain:"Quốc Tử Giám lập năm 1076, là nơi đào tạo nhân tài cho đất nước."},{id:"sd5-nha-ly-thang-long-15",type:"mc",q:"Bài thơ “Nam quốc sơn hà” gắn với cuộc kháng chiến nào?",options:["Chống quân Nam Hán","Chống quân Thanh thời Tây Sơn","Chống quân Tống thời Lý","Chống thực dân Pháp"],answer:2,explain:"Bài thơ gắn với cuộc kháng chiến chống Tống trên sông Như Nguyệt."},{id:"sd5-nha-ly-thang-long-16",type:"mc",q:"Phòng tuyến sông Như Nguyệt được Lý Thường Kiệt xây dựng để:",options:["Chặn quân Tống tiến lên","Trồng lúa nước ven sông","Mở chợ buôn bán bên sông","Xây nhà máy thủy điện"],answer:0,explain:"Phòng tuyến trên sông Như Nguyệt chặn quân Tống tiến về Thăng Long."},{id:"sd5-nha-ly-thang-long-17",type:"tf",q:"Lý Thái Tổ dời đô về Hoa Lư.",answer:!1,explain:"Lý Thái Tổ dời đô từ Hoa Lư về Đại La (Thăng Long)."},{id:"sd5-nha-ly-thang-long-18",type:"mc",q:"Ý nghĩa của tên gọi “Thăng Long” là:",options:["Biển rộng lớn","Sông dài mãi","Núi cao vút","Rồng bay lên"],answer:3,explain:"Thăng Long nghĩa là rồng bay lên, thể hiện khát vọng đất nước phát triển."}]},{questions:[{id:"sd5-nha-ly-thang-long-19",type:"mc",q:"Việc dời đô về Thăng Long thể hiện mong muốn gì của nhà Lý?",options:["Muốn ở gần núi để dễ trốn giặc","Đất nước phát triển lâu dài","Muốn đi du lịch khắp nơi","Muốn rời bỏ quê hương"],answer:1,explain:"Dời đô về nơi trung tâm, thuận lợi để đất nước phát triển lâu dài."},{id:"sd5-nha-ly-thang-long-20",type:"number",q:"Năm 2010, Hà Nội kỉ niệm Thăng Long tròn bao nhiêu năm?",answer:1e3,explain:"2010 − 1010 = 1000 năm.",unit:"năm",emoji:"🎉"},{id:"sd5-nha-ly-thang-long-21",type:"tf",q:"Ngày nay, Văn Miếu – Quốc Tử Giám ở Hà Nội vẫn là nơi tôn vinh truyền thống hiếu học.",answer:!0,explain:"Nhiều học sinh đến Văn Miếu tham quan, tìm hiểu truyền thống hiếu học."},{id:"sd5-nha-ly-thang-long-22",type:"mc",q:"Nam đọc được câu: “Sông núi nước Nam vua Nam ở”. Câu này khẳng định điều gì?",options:["Nước Nam có rất nhiều sông núi","Vua Nam thích ngắm sông núi","Nước Nam là của người Nam","Nước Nam không giáp biển"],answer:2,explain:"Câu thơ khẳng định chủ quyền độc lập của nước ta."},{id:"sd5-nha-ly-thang-long-23",type:"multi",q:"Thành tựu nào thuộc thời nhà Lý?",options:["Dời đô về Thăng Long","Xây Văn Miếu","Đánh thắng quân Tống","Chiến thắng Điện Biên Phủ"],answers:[0,1,2],explain:"Chiến thắng Điện Biên Phủ diễn ra năm 1954."},{id:"sd5-nha-ly-thang-long-24",type:"mc",q:"Ngày nay ở Văn Miếu, em nên làm gì khi tham quan?",options:["Sờ đầu rùa đá để lấy may","Leo lên bia đá để chụp ảnh","Khắc tên mình lên cột","Giữ trật tự, không chạm hiện vật"],answer:3,explain:"Bảo vệ hiện vật giúp giữ gìn di tích quý giá."},{id:"sd5-nha-ly-thang-long-25",type:"number",q:"Từ năm Lý Thái Tổ dời đô (1010) đến năm xây Văn Miếu (1070) là bao nhiêu năm?",answer:60,explain:"1070 − 1010 = 60 năm.",unit:"năm"},{id:"sd5-nha-ly-thang-long-26",type:"tf",q:"Thời Lý chưa có trường học nào.",answer:!1,explain:"Thời Lý đã lập Quốc Tử Giám năm 1076 để dạy học."}]}],challenge:{questions:[{id:"sd5-nha-ly-thang-long-27",type:"order",q:"Sắp xếp các kinh đô theo thứ tự thời gian được chọn làm kinh đô.",items:["Phong Châu","Cổ Loa","Hoa Lư","Thăng Long"],explain:"Phong Châu (Văn Lang) → Cổ Loa (Âu Lạc) → Hoa Lư → Thăng Long (năm 1010)."},{id:"sd5-nha-ly-thang-long-28",type:"match",q:"Nối nhân vật với việc làm.",pairs:[["Lý Thái Tổ","Dời đô về Thăng Long"],["Lý Thường Kiệt","Chống quân Tống"],["Ngô Quyền","Chiến thắng Bạch Đằng năm 938"]],explain:"Mỗi nhân vật gắn với một sự kiện lịch sử tiêu biểu."},{id:"sd5-nha-ly-thang-long-29",type:"tf",q:"Chiếu dời đô do vua Lý Thái Tổ ban ra.",answer:!0,explain:"Năm 1010, Lý Thái Tổ ban Chiếu dời đô."},{id:"sd5-nha-ly-thang-long-30",type:"multi",q:"Phát biểu nào đúng?",options:["Thăng Long nay là Hà Nội","Năm 1054 nước ta có tên Đại Việt","Quốc Tử Giám lập năm 1010","Lý Thường Kiệt chống quân Tống"],answers:[0,1,3],explain:"Quốc Tử Giám được lập năm 1076, không phải năm 1010."},{id:"sd5-nha-ly-thang-long-31",type:"mc",q:"Nếu kinh đô vẫn ở Hoa Lư, khó khăn lớn nhất là gì?",options:["Không có núi để phòng thủ","Đất chật hẹp, khó mở rộng","Nằm quá gần biển lớn","Khí hậu quá lạnh giá"],answer:1,explain:"Hoa Lư phòng thủ tốt nhưng chật hẹp, khó phát triển lâu dài."},{id:"sd5-nha-ly-thang-long-32",type:"number",q:"Năm 1077 cách năm 1010 bao nhiêu năm?",answer:67,explain:"1077 − 1010 = 67 năm.",unit:"năm"}]},summary:["Năm 1010, Lý Thái Tổ dời đô từ Hoa Lư về Đại La, đổi tên là Thăng Long.","Năm 1054, nhà Lý đặt tên nước là Đại Việt.","Nhà Lý xây Văn Miếu, lập Quốc Tử Giám; Lý Thường Kiệt đánh thắng quân Tống."]},{id:"sd5-nha-tran-mong-nguyen",title:"Nhà Trần và ba lần kháng chiến chống Mông – Nguyên",weeks:[16,17],learn:[{title:"Nhà Trần",text:"Năm 1226, nhà Trần thành lập. Nhà Trần rất quan tâm đến sản xuất nông nghiệp, đắp đê phòng lụt, lập chức Hà đê sứ để trông coi đê điều.",example:"🌾 đắp đê"},{title:"Ba lần kháng chiến",text:"Quân dân nhà Trần ba lần đánh thắng quân xâm lược Mông – Nguyên (năm 1258, năm 1285 và năm 1287 – 1288). Trần Hưng Đạo (Trần Quốc Tuấn) là vị tướng tài, viết “Hịch tướng sĩ” khích lệ quân sĩ.",example:"⚔️ ×3"},{title:"Đồng lòng đánh giặc",text:"Tại Hội nghị Diên Hồng, các bô lão đồng thanh hô “Đánh!”. Quân sĩ khắc hai chữ “Sát Thát” lên cánh tay. Thiếu niên Trần Quốc Toản quyết tâm ra trận đánh giặc.",example:"👴 “Đánh!”"},{title:"Bạch Đằng năm 1288",text:"Năm 1288, Trần Hưng Đạo dùng bãi cọc trên sông Bạch Đằng, đánh tan đoàn thuyền chiến của quân Nguyên.",example:"🌊🪵 1288"}],practice:[{questions:[{id:"sd5-nha-tran-mong-nguyen-01",type:"mc",q:"Nhà Trần ba lần kháng chiến chống quân xâm lược nào?",options:["Quân Tống","Quân Minh","Quân Mông – Nguyên","Quân Nam Hán"],answer:2,explain:"Nhà Trần ba lần đánh thắng quân Mông – Nguyên.",emoji:"⚔️"},{id:"sd5-nha-tran-mong-nguyen-02",type:"number",q:"Quân dân nhà Trần đã mấy lần đánh thắng quân Mông – Nguyên?",answer:3,explain:"Nhà Trần ba lần kháng chiến chống Mông – Nguyên thắng lợi.",unit:"lần"},{id:"sd5-nha-tran-mong-nguyen-03",type:"mc",q:"Vị tướng tài lãnh đạo kháng chiến chống Mông – Nguyên là:",options:["Lý Thường Kiệt","Lê Lợi","Trần Hưng Đạo","Nguyễn Huệ"],answer:2,explain:"Trần Hưng Đạo (Trần Quốc Tuấn) là vị tướng tài của nhà Trần."},{id:"sd5-nha-tran-mong-nguyen-04",type:"tf",q:"“Hịch tướng sĩ” do Lý Thường Kiệt viết.",answer:!1,explain:"“Hịch tướng sĩ” do Trần Hưng Đạo viết.",emoji:"📜"},{id:"sd5-nha-tran-mong-nguyen-05",type:"mc",q:"Ở Hội nghị Diên Hồng, các bô lão đồng thanh hô:",options:["“Hòa!”","“Hàng!”","“Chạy!”","“Đánh!”"],answer:3,explain:"Các bô lão đồng lòng hô “Đánh!”, thể hiện ý chí quyết chiến."},{id:"sd5-nha-tran-mong-nguyen-06",type:"fill",q:"Quân sĩ nhà Trần khắc hai chữ “Sát …” lên cánh tay.",answer:["Thát"],explain:"Hai chữ “Sát Thát” thể hiện quyết tâm đánh giặc."},{id:"sd5-nha-tran-mong-nguyen-07",type:"tf",q:"Nhà Trần rất quan tâm đắp đê phòng lụt.",answer:!0,explain:"Nhà Trần lập chức Hà đê sứ để trông coi việc đắp đê."},{id:"sd5-nha-tran-mong-nguyen-08",type:"mc",q:"Năm 1288, quân dân nhà Trần đánh tan quân Nguyên trên sông nào?",options:["Sông Như Nguyệt","Sông Hồng","Sông Bạch Đằng","Sông Mã"],answer:2,explain:"Năm 1288, Trần Hưng Đạo đánh tan quân Nguyên trên sông Bạch Đằng.",emoji:"🌊"},{id:"sd5-nha-tran-mong-nguyen-09",type:"mc",q:"Thiếu niên nào nổi tiếng thời Trần vì quyết tâm ra trận đánh giặc?",options:["Trần Quốc Toản","Lê Lợi","Ngô Quyền","Lý Thường Kiệt"],answer:0,explain:"Trần Quốc Toản tuổi nhỏ mà chí lớn, lập đội quân đánh giặc."}]},{questions:[{id:"sd5-nha-tran-mong-nguyen-10",type:"order",q:"Sắp xếp các năm quân dân nhà Trần đánh giặc theo thứ tự.",items:["Năm 1258","Năm 1285","Năm 1288"],explain:"Ba lần kháng chiến: năm 1258, năm 1285 và năm 1287 – 1288."},{id:"sd5-nha-tran-mong-nguyen-11",type:"match",q:"Nối sự kiện với ý nghĩa.",pairs:[["Hội nghị Diên Hồng","Toàn dân đồng lòng đánh giặc"],["Hịch tướng sĩ","Khích lệ tinh thần quân sĩ"],["Chữ “Sát Thát”","Quyết tâm của quân sĩ"]],explain:"Mỗi sự kiện thể hiện tinh thần đoàn kết, quyết chiến của quân dân nhà Trần."},{id:"sd5-nha-tran-mong-nguyen-12",type:"multi",q:"Vì sao nhà Trần ba lần đánh thắng quân Mông – Nguyên?",options:["Toàn dân đoàn kết","Có tướng tài như Trần Hưng Đạo","Có cách đánh mưu trí","Quân giặc rất ít"],answers:[0,1,2],explain:"Quân Mông – Nguyên rất mạnh; ta thắng nhờ đoàn kết, tướng tài và mưu trí."},{id:"sd5-nha-tran-mong-nguyen-13",type:"tf",q:"Trận Bạch Đằng năm 1288 có cách đánh giống trận Bạch Đằng năm 938 là dùng bãi cọc.",answer:!0,explain:"Cả hai trận đều dùng bãi cọc và thủy triều trên sông Bạch Đằng."},{id:"sd5-nha-tran-mong-nguyen-14",type:"mc",q:"Chức Hà đê sứ thời Trần có nhiệm vụ gì?",options:["Trông coi việc đắp đê","Thu thuế ở các chợ","Dạy học ở Quốc Tử Giám","Đóng thuyền chiến"],answer:0,explain:"Hà đê sứ trông coi đê điều, phòng chống lụt."},{id:"sd5-nha-tran-mong-nguyen-15",type:"mc",q:"Hội nghị Diên Hồng mời những ai đến hỏi ý kiến?",options:["Các thương nhân nước ngoài","Chỉ có các tướng giặc","Các bô lão đại diện nhân dân","Chỉ có trẻ em"],answer:2,explain:"Vua Trần mời các bô lão để hỏi ý kiến toàn dân."},{id:"sd5-nha-tran-mong-nguyen-16",type:"tf",q:"Quân Mông – Nguyên là đội quân yếu, dễ đánh.",answer:!1,explain:"Quân Mông – Nguyên rất mạnh, từng chiếm nhiều nước; thắng họ là kì tích."},{id:"sd5-nha-tran-mong-nguyen-17",type:"mc",q:"Nhà Trần thành lập vào năm nào?",options:["Năm 1010","Năm 1428","Năm 1226","Năm 1802"],answer:2,explain:"Nhà Trần thành lập năm 1226."},{id:"sd5-nha-tran-mong-nguyen-18",type:"mc",q:"Vì sao nhà Trần chú trọng đắp đê?",options:["Để làm đường đua ngựa","Để nuôi cá trong ruộng","Để ngăn gió mùa đông bắc","Để chống lũ, giữ mùa màng"],answer:3,explain:"Đê ngăn nước lũ, bảo vệ đồng ruộng và làng xóm."}]},{questions:[{id:"sd5-nha-tran-mong-nguyen-19",type:"mc",q:"Hội nghị Diên Hồng cho thấy điều gì về nhà Trần?",options:["Vua không quan tâm đến dân","Vua biết lắng nghe dân","Nhân dân rất sợ giặc","Chỉ quan lại đi đánh giặc"],answer:1,explain:"Vua Trần hỏi ý kiến bô lão, dựa vào sức mạnh của dân."},{id:"sd5-nha-tran-mong-nguyen-20",type:"tf",q:"Trần Quốc Toản cho thấy tuổi nhỏ cũng có thể có lòng yêu nước và chí lớn.",answer:!0,explain:"Trần Quốc Toản tuy nhỏ tuổi nhưng rất yêu nước."},{id:"sd5-nha-tran-mong-nguyen-21",type:"mc",q:"Nếu viết về “Tinh thần đoàn kết thời Trần”, Khoa nên chọn sự kiện nào?",options:["Hội nghị Diên Hồng","Dời đô về Thăng Long","Xây Văn Miếu","Đại phá quân Thanh"],answer:0,explain:"Hội nghị Diên Hồng thể hiện sự đồng lòng của vua tôi và nhân dân."},{id:"sd5-nha-tran-mong-nguyen-22",type:"number",q:"Năm 1288 cách năm 938 bao nhiêu năm?",answer:350,explain:"1288 − 938 = 350 năm.",unit:"năm"},{id:"sd5-nha-tran-mong-nguyen-23",type:"multi",q:"Bài học nào từ thời Trần vẫn có ích ngày nay?",options:["Đoàn kết sẽ tạo nên sức mạnh","Biết lắng nghe ý kiến của mọi người","Không cần chuẩn bị kĩ","Bảo vệ đê điều, phòng chống thiên tai"],answers:[0,1,3],explain:"Đoàn kết, lắng nghe, phòng chống thiên tai là bài học quý."},{id:"sd5-nha-tran-mong-nguyen-24",type:"tf",q:"Nhân dân đã quên công lao của Trần Hưng Đạo, không còn đền thờ ông.",answer:!1,explain:"Nhân dân lập đền thờ Trần Hưng Đạo ở nhiều nơi để tưởng nhớ ông."},{id:"sd5-nha-tran-mong-nguyen-25",type:"mc",q:"Điểm khác giữa hai chiến thắng Bạch Đằng là gì?",options:["Cả hai trận đều đánh quân Thanh xâm lược","Năm 938 đánh Nam Hán, năm 1288 đánh Nguyên","Trận năm 938 do Trần Hưng Đạo chỉ huy","Trận năm 1288 do Ngô Quyền chỉ huy"],answer:1,explain:"Năm 938 Ngô Quyền đánh quân Nam Hán; năm 1288 Trần Hưng Đạo đánh quân Nguyên."},{id:"sd5-nha-tran-mong-nguyen-26",type:"mc",q:"Vì sao nói chiến thắng Mông – Nguyên là một kì tích?",options:["Vì quân ta đông hơn giặc rất nhiều","Vì chỉ cần đánh một trận là thắng","Vì quân giặc không muốn đánh","Vì quân Mông – Nguyên rất mạnh"],answer:3,explain:"Đánh thắng đội quân hùng mạnh bậc nhất thời đó ba lần là kì tích."}]}],challenge:{questions:[{id:"sd5-nha-tran-mong-nguyen-27",type:"order",q:"Sắp xếp các triều đại theo thứ tự thời gian.",items:["Nhà Ngô","Nhà Lý","Nhà Trần","Nhà Hậu Lê"],explain:"Nhà Ngô (năm 939) → nhà Lý (năm 1009) → nhà Trần (năm 1226) → nhà Hậu Lê (năm 1428)."},{id:"sd5-nha-tran-mong-nguyen-28",type:"match",q:"Nối người anh hùng với trận đánh trên sông.",pairs:[["Ngô Quyền","Bạch Đằng năm 938"],["Lý Thường Kiệt","Như Nguyệt năm 1077"],["Trần Hưng Đạo","Bạch Đằng năm 1288"]],explain:"Ngô Quyền – Bạch Đằng 938, Lý Thường Kiệt – Như Nguyệt 1077, Trần Hưng Đạo – Bạch Đằng 1288."},{id:"sd5-nha-tran-mong-nguyen-29",type:"multi",q:"Phát biểu nào đúng về nhà Trần?",options:["Ba lần đánh thắng quân Mông – Nguyên","Có Hội nghị Diên Hồng","Dời đô về Thăng Long","Lập chức Hà đê sứ"],answers:[0,1,3],explain:"Dời đô về Thăng Long là việc của nhà Lý năm 1010."},{id:"sd5-nha-tran-mong-nguyen-30",type:"tf",q:"Trận Bạch Đằng năm 1288 do Ngô Quyền chỉ huy.",answer:!1,explain:"Trận năm 1288 do Trần Hưng Đạo chỉ huy; Ngô Quyền chỉ huy trận năm 938."},{id:"sd5-nha-tran-mong-nguyen-31",type:"number",q:"Nhà Trần thành lập năm 1226, chiến thắng Bạch Đằng năm 1288. Cách nhau bao nhiêu năm?",answer:62,explain:"1288 − 1226 = 62 năm.",unit:"năm"},{id:"sd5-nha-tran-mong-nguyen-32",type:"mc",q:"Câu “Ta thường tới bữa quên ăn, nửa đêm vỗ gối…” thể hiện điều gì ở Trần Hưng Đạo?",options:["Ông mất ngủ vì quá vui","Ông đang bị ốm nặng","Ông không thích ăn cơm","Lòng yêu nước, căm giận giặc"],answer:3,explain:"Đây là lời trong “Hịch tướng sĩ”, thể hiện lòng yêu nước sâu sắc."}]},summary:["Nhà Trần chú trọng nông nghiệp, đắp đê phòng lụt.","Quân dân nhà Trần ba lần đánh thắng quân Mông – Nguyên.","Trần Hưng Đạo lãnh đạo chiến thắng Bạch Đằng năm 1288.","Sức mạnh đoàn kết toàn dân là nguyên nhân chính của thắng lợi."]}]},{id:"lam-son-hau-le",title:"Khởi nghĩa Lam Sơn và nhà Hậu Lê",lessons:[{id:"sd5-khoi-nghia-lam-son",title:"Khởi nghĩa Lam Sơn",weeks:[18,19],learn:[{title:"Lê Lợi dựng cờ khởi nghĩa",text:"Đầu thế kỉ XV, quân Minh xâm lược và đô hộ nước ta. Năm 1418, Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn (Thanh Hóa). Nguyễn Trãi là người bàn mưu tính kế giúp Lê Lợi.",example:"🚩 Lam Sơn · 1418"},{title:"Chi Lăng – Xương Giang",text:"Năm 1427, nghĩa quân Lam Sơn đánh tan viện binh quân Minh ở Chi Lăng (Lạng Sơn) và Xương Giang. Quân Minh phải rút về nước.",example:"⛰️ ải Chi Lăng · 1427"},{title:"Nhà Hậu Lê ra đời",text:"Năm 1428, Lê Lợi lên ngôi vua, lập ra nhà Hậu Lê, đóng đô ở Thăng Long. Nguyễn Trãi viết “Bình Ngô đại cáo” tuyên bố độc lập.",example:"👑 1428 · 📜 Bình Ngô đại cáo"}],practice:[{questions:[{id:"sd5-khoi-nghia-lam-son-01",type:"mc",q:"Ai là người lãnh đạo khởi nghĩa Lam Sơn?",options:["Trần Hưng Đạo","Nguyễn Huệ","Lê Lợi","Lý Thường Kiệt"],answer:2,explain:"Lê Lợi lãnh đạo khởi nghĩa Lam Sơn.",emoji:"🚩"},{id:"sd5-khoi-nghia-lam-son-02",type:"mc",q:"Khởi nghĩa Lam Sơn chống lại quân xâm lược nào?",options:["Quân Minh","Quân Nguyên","Quân Tống","Quân Thanh"],answer:0,explain:"Khởi nghĩa Lam Sơn chống quân Minh."},{id:"sd5-khoi-nghia-lam-son-03",type:"mc",q:"Lê Lợi dựng cờ khởi nghĩa vào năm nào?",options:["Năm 1288","Năm 1428","Năm 1418","Năm 1789"],answer:2,explain:"Năm 1418, Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn."},{id:"sd5-khoi-nghia-lam-son-04",type:"tf",q:"Lam Sơn thuộc tỉnh Thanh Hóa.",answer:!0,explain:"Lam Sơn là vùng đất thuộc tỉnh Thanh Hóa."},{id:"sd5-khoi-nghia-lam-son-05",type:"mc",q:"Ai là người viết “Bình Ngô đại cáo”?",options:["Lê Lợi","Lý Thường Kiệt","Trần Hưng Đạo","Nguyễn Trãi"],answer:3,explain:"Nguyễn Trãi viết “Bình Ngô đại cáo” năm 1428.",emoji:"📜"},{id:"sd5-khoi-nghia-lam-son-06",type:"tf",q:"Năm 1428, Lê Lợi lên ngôi vua, lập ra nhà Trần.",answer:!1,explain:"Năm 1428, Lê Lợi lập ra nhà Hậu Lê; nhà Trần thành lập năm 1226.",emoji:"👑"},{id:"sd5-khoi-nghia-lam-son-07",type:"fill",q:"Năm 1427, nghĩa quân đánh tan viện binh quân Minh ở ải Chi … .",answer:["Lăng"],explain:"Đó là chiến thắng Chi Lăng."},{id:"sd5-khoi-nghia-lam-son-08",type:"mc",q:"Ải Chi Lăng nay thuộc tỉnh nào?",options:["Thanh Hóa","Cao Bằng","Lạng Sơn","Quảng Ninh"],answer:2,explain:"Ải Chi Lăng thuộc tỉnh Lạng Sơn.",emoji:"⛰️"},{id:"sd5-khoi-nghia-lam-son-09",type:"tf",q:"Truyền thuyết Hồ Gươm kể về việc Lê Lợi trả gươm cho Rùa Vàng.",answer:!0,explain:"Theo truyền thuyết, Lê Lợi trả gươm báu cho Rùa Vàng ở hồ Tả Vọng, từ đó hồ có tên Hồ Gươm.",emoji:"🐢"}]},{questions:[{id:"sd5-khoi-nghia-lam-son-10",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Lê Lợi dựng cờ khởi nghĩa ở Lam Sơn","Chiến thắng Chi Lăng – Xương Giang","Lê Lợi lên ngôi, lập nhà Hậu Lê"],explain:"Năm 1418 → năm 1427 → năm 1428."},{id:"sd5-khoi-nghia-lam-son-11",type:"match",q:"Nối sự kiện với năm.",pairs:[["Dựng cờ khởi nghĩa Lam Sơn","Năm 1418"],["Chiến thắng Chi Lăng","Năm 1427"],["Lập nhà Hậu Lê","Năm 1428"]],explain:"Khởi nghĩa năm 1418, Chi Lăng năm 1427, lập nhà Hậu Lê năm 1428."},{id:"sd5-khoi-nghia-lam-son-12",type:"number",q:"Khởi nghĩa Lam Sơn bắt đầu năm 1418 và quân Minh rút về nước năm 1427. Cuộc khởi nghĩa kéo dài khoảng bao nhiêu năm?",answer:10,explain:"Tính cả năm đầu và năm cuối, từ 1418 đến 1427 là khoảng 10 năm.",unit:"năm"},{id:"sd5-khoi-nghia-lam-son-13",type:"mc",q:"Ải Chi Lăng có địa hình thế nào giúp nghĩa quân mai phục?",options:["Đồng bằng rộng, bằng phẳng","Sa mạc khô nóng","Bãi biển dài, nhiều cát","Hẻm núi hẹp giữa núi cao"],answer:3,explain:"Chi Lăng là thung lũng hẹp giữa núi, thuận lợi để mai phục."},{id:"sd5-khoi-nghia-lam-son-14",type:"tf",q:"“Bình Ngô đại cáo” được xem như bản tuyên ngôn độc lập của nước ta sau khi đánh thắng quân Minh.",answer:!0,explain:"“Bình Ngô đại cáo” khẳng định nền độc lập của dân tộc."},{id:"sd5-khoi-nghia-lam-son-15",type:"multi",q:"Vì sao khởi nghĩa Lam Sơn thắng lợi?",options:["Nhân dân ủng hộ, đoàn kết","Có người lãnh đạo tài giỏi như Lê Lợi, Nguyễn Trãi","Có cách đánh mưu trí","Quân Minh không đánh lại"],answers:[0,1,2],explain:"Ta thắng nhờ lòng dân, người lãnh đạo tài và mưu trí."},{id:"sd5-khoi-nghia-lam-son-16",type:"mc",q:"Lê Lai được nhân dân ghi nhớ vì:",options:["Liều mình cứu Lê Lợi","Viết “Bình Ngô đại cáo”","Dời đô về Thăng Long","Đánh thắng quân Nguyên"],answer:0,explain:"Lê Lai đóng giả Lê Lợi, hi sinh để cứu chủ tướng và nghĩa quân."},{id:"sd5-khoi-nghia-lam-son-17",type:"tf",q:"Lê Lợi lên ngôi và đóng đô ở Huế.",answer:!1,explain:"Lê Lợi đóng đô ở Thăng Long."},{id:"sd5-khoi-nghia-lam-son-18",type:"mc",q:"Hồ Gươm (hồ Hoàn Kiếm) nằm ở thành phố nào?",options:["Huế","Thanh Hóa","Lạng Sơn","Hà Nội"],answer:3,explain:"Hồ Hoàn Kiếm ở trung tâm Thủ đô Hà Nội."}]},{questions:[{id:"sd5-khoi-nghia-lam-son-19",type:"mc",q:"Câu “Đem đại nghĩa để thắng hung tàn, lấy chí nhân để thay cường bạo” thể hiện điều gì?",options:["Chỉ cần dùng vũ lực là thắng được","Dùng chính nghĩa, lòng nhân để thắng","Rất sợ hãi trước kẻ thù hung bạo","Muốn đem quân đi đánh nước khác"],answer:1,explain:"Câu văn trong “Bình Ngô đại cáo” nói về tư tưởng nhân nghĩa."},{id:"sd5-khoi-nghia-lam-son-20",type:"tf",q:"Sau khi thắng, nghĩa quân Lam Sơn cấp thuyền, lương thực cho quân Minh về nước, thể hiện lòng nhân đạo.",answer:!0,explain:"Đây là chính sách nhân đạo, giữ hòa hiếu lâu dài."},{id:"sd5-khoi-nghia-lam-son-21",type:"mc",q:"Tên “Hoàn Kiếm” có nghĩa là gì?",options:["Trả lại gươm","Rèn kiếm","Mài gươm","Cất giữ gươm"],answer:0,explain:"Hoàn Kiếm nghĩa là trả gươm, gắn với truyền thuyết Lê Lợi trả gươm cho Rùa Vàng."},{id:"sd5-khoi-nghia-lam-son-22",type:"multi",q:"Đâu là những người có công trong khởi nghĩa Lam Sơn?",options:["Lê Lợi","Nguyễn Trãi","Lê Lai","Ngô Quyền"],answers:[0,1,2],explain:"Ngô Quyền sống ở thế kỉ X, chiến thắng Bạch Đằng năm 938."},{id:"sd5-khoi-nghia-lam-son-23",type:"mc",q:"Ngọc được giao kể chuyện “Lê Lai cứu chúa”. Câu chuyện thuộc thời kì nào?",options:["Khởi nghĩa Lam Sơn","Thời nhà Lý","Thời nhà Trần","Phong trào Tây Sơn"],answer:0,explain:"Lê Lai hi sinh cứu Lê Lợi trong khởi nghĩa Lam Sơn."},{id:"sd5-khoi-nghia-lam-son-24",type:"tf",q:"Khởi nghĩa Lam Sơn diễn ra trước kháng chiến chống Mông – Nguyên.",answer:!1,explain:"Kháng chiến chống Mông – Nguyên ở thế kỉ XIII; khởi nghĩa Lam Sơn ở thế kỉ XV."},{id:"sd5-khoi-nghia-lam-son-25",type:"mc",q:"Thất bại ở Chi Lăng đã làm quân Minh ra sao?",options:["Mạnh hơn trước và tiến lên","Mất tinh thần, phải rút về nước","Chiếm được thành Thăng Long","Quay sang đầu hàng quân Thanh"],answer:1,explain:"Viện binh bị tiêu diệt, quân Minh mất tinh thần và phải rút về nước."},{id:"sd5-khoi-nghia-lam-son-26",type:"number",q:"Lê Lợi lên ngôi năm 1428. Năm đó cách năm 1288 bao nhiêu năm?",answer:140,explain:"1428 − 1288 = 140 năm.",unit:"năm"}]}],challenge:{questions:[{id:"sd5-khoi-nghia-lam-son-27",type:"order",q:"Sắp xếp các chiến thắng theo thứ tự thời gian.",items:["Bạch Đằng – Ngô Quyền","Như Nguyệt – Lý Thường Kiệt","Bạch Đằng – Trần Hưng Đạo","Chi Lăng – Lê Lợi"],explain:"Năm 938 → năm 1077 → năm 1288 → năm 1427."},{id:"sd5-khoi-nghia-lam-son-28",type:"match",q:"Nối nhân vật với tác phẩm hoặc sự kiện.",pairs:[["Nguyễn Trãi","Bình Ngô đại cáo"],["Trần Hưng Đạo","Hịch tướng sĩ"],["Lý Thái Tổ","Chiếu dời đô"]],explain:"Nguyễn Trãi – Bình Ngô đại cáo, Trần Hưng Đạo – Hịch tướng sĩ, Lý Thái Tổ – Chiếu dời đô."},{id:"sd5-khoi-nghia-lam-son-29",type:"multi",q:"Phát biểu nào đúng?",options:["Lam Sơn ở Thanh Hóa","Chi Lăng ở Lạng Sơn","Lê Lợi đánh quân Thanh","Nhà Hậu Lê thành lập năm 1428"],answers:[0,1,3],explain:"Lê Lợi đánh quân Minh; quân Thanh bị Quang Trung đánh tan năm 1789."},{id:"sd5-khoi-nghia-lam-son-30",type:"tf",q:"Nguyễn Trãi là vị tướng chỉ huy trận Bạch Đằng năm 938.",answer:!1,explain:"Nguyễn Trãi là người bàn mưu tính kế cho Lê Lợi; trận năm 938 do Ngô Quyền chỉ huy."},{id:"sd5-khoi-nghia-lam-son-31",type:"mc",q:"Điểm giống nhau giữa “Nam quốc sơn hà” và “Bình Ngô đại cáo” là gì?",options:["Đều do Nguyễn Trãi viết năm 1428","Đều khẳng định nền độc lập của nước ta","Đều được viết ra vào cùng một năm","Đều nói về thiên tai, lũ lụt"],answer:1,explain:"Cả hai đều được xem là những bản tuyên ngôn độc lập của dân tộc."},{id:"sd5-khoi-nghia-lam-son-32",type:"number",q:"Từ năm Lê Lợi lên ngôi (1428) đến năm Quang Trung đại phá quân Thanh (1789) là bao nhiêu năm?",answer:361,explain:"1789 − 1428 = 361 năm.",unit:"năm"}]},summary:["Năm 1418, Lê Lợi khởi nghĩa ở Lam Sơn chống quân Minh.","Năm 1427, chiến thắng Chi Lăng – Xương Giang buộc quân Minh rút về nước.","Năm 1428, Lê Lợi lên ngôi, lập nhà Hậu Lê; Nguyễn Trãi viết “Bình Ngô đại cáo”."]},{id:"sd5-nha-hau-le",title:"Nhà Hậu Lê và vua Lê Thánh Tông",weeks:[20,20],learn:[{title:"Lê Thánh Tông",text:"Lê Thánh Tông là vị vua nổi tiếng của nhà Hậu Lê. Dưới thời ông, đất nước phát triển mạnh về nhiều mặt.",example:"👑"},{title:"Bộ luật Hồng Đức",text:"Nhà Hậu Lê ban hành Bộ luật Hồng Đức để quản lí đất nước, có điều khoản bảo vệ chủ quyền và quyền lợi của phụ nữ. Nhà nước còn cho vẽ bản đồ cả nước.",example:"📕 luật · 🗺️ bản đồ"},{title:"Coi trọng giáo dục",text:"Nhà Hậu Lê mở nhiều khoa thi để chọn người tài. Thời Lê Thánh Tông bắt đầu dựng bia ghi tên tiến sĩ ở Văn Miếu.",example:"🐢📜 bia tiến sĩ"}],practice:[{questions:[{id:"sd5-nha-hau-le-01",type:"mc",q:"Bộ luật nổi tiếng thời Hậu Lê có tên là:",options:["Bộ luật Gia Long","Bộ luật Hồng Đức","Bộ luật Hình thư","Bộ luật Lý"],answer:1,explain:"Bộ luật Hồng Đức được ban hành thời Hậu Lê.",emoji:"📕"},{id:"sd5-nha-hau-le-02",type:"mc",q:"Vị vua nổi tiếng của nhà Hậu Lê đã cho ban hành Bộ luật Hồng Đức là:",options:["Lê Lợi","Lý Thường Kiệt","Lý Thái Tổ","Lê Thánh Tông"],answer:3,explain:"Bộ luật Hồng Đức gắn với vua Lê Thánh Tông."},{id:"sd5-nha-hau-le-03",type:"tf",q:"Bộ luật Hồng Đức có điều khoản bảo vệ quyền lợi của phụ nữ.",answer:!0,explain:"Đây là điểm tiến bộ của Bộ luật Hồng Đức."},{id:"sd5-nha-hau-le-04",type:"tf",q:"Nhà Hậu Lê dựng bia ghi tên tiến sĩ ở Văn Miếu.",answer:!0,explain:"Bia tiến sĩ đặt trên lưng rùa đá ở Văn Miếu.",emoji:"🐢"},{id:"sd5-nha-hau-le-05",type:"mc",q:"Nhà Hậu Lê mở các khoa thi để làm gì?",options:["Chọn người tài giỏi giúp nước","Chọn người khỏe nhất làm lính","Chọn người giàu nhất làm quan","Chọn người hát hay vào cung"],answer:0,explain:"Thi cử để tìm người tài ra giúp nước."},{id:"sd5-nha-hau-le-06",type:"fill",q:"Tên bia đá ở Văn Miếu ghi người đỗ … sĩ.",answer:["tiến"],explain:"Đó là bia tiến sĩ."},{id:"sd5-nha-hau-le-07",type:"tf",q:"Nhà Hậu Lê do Lê Lợi lập ra.",answer:!0,explain:"Năm 1428, Lê Lợi lập nhà Hậu Lê."},{id:"sd5-nha-hau-le-08",type:"mc",q:"Bia tiến sĩ ở Văn Miếu được đặt trên lưng con vật nào bằng đá?",options:["Con ngựa","Con rùa","Con voi","Con rồng"],answer:1,explain:"Mỗi tấm bia đặt trên lưng một con rùa đá.",emoji:"🐢"},{id:"sd5-nha-hau-le-09",type:"tf",q:"Thời Hậu Lê không có trường học, thi cử.",answer:!1,explain:"Thời Hậu Lê rất coi trọng giáo dục, thi cử."}]},{questions:[{id:"sd5-nha-hau-le-10",type:"multi",q:"Thành tựu nào thuộc thời Hậu Lê?",options:["Bộ luật Hồng Đức","Dựng bia tiến sĩ ở Văn Miếu","Vẽ bản đồ cả nước","Xây thành Cổ Loa"],answers:[0,1,2],explain:"Thành Cổ Loa do An Dương Vương xây từ thời Âu Lạc."},{id:"sd5-nha-hau-le-11",type:"mc",q:"Việc dựng bia tiến sĩ có ý nghĩa gì?",options:["Tôn vinh người tài, khuyến khích học","Để trang trí cho sân Văn Miếu thêm đẹp","Để đánh dấu đường đi trong Văn Miếu","Để làm chỗ ngồi nghỉ cho khách"],answer:0,explain:"Bia tiến sĩ tôn vinh người học giỏi, khuyến khích việc học."},{id:"sd5-nha-hau-le-12",type:"tf",q:"Bộ luật Hồng Đức cho phép bán đất đai của nước cho nước khác.",answer:!1,explain:"Bộ luật Hồng Đức nghiêm trị những ai làm mất đất đai của tổ quốc."},{id:"sd5-nha-hau-le-13",type:"match",q:"Nối triều đại với người lập ra.",pairs:[["Nhà Lý","Lý Công Uẩn"],["Nhà Hậu Lê","Lê Lợi"],["Nhà Ngô","Ngô Quyền"]],explain:"Lý Công Uẩn lập nhà Lý, Lê Lợi lập nhà Hậu Lê, Ngô Quyền lập nhà Ngô."},{id:"sd5-nha-hau-le-14",type:"mc",q:"Vì sao nhà Hậu Lê cho vẽ bản đồ cả nước?",options:["Để làm trò chơi trong cung","Để trang trí tường cung điện","Để bán bản đồ cho nước ngoài","Để quản lí, bảo vệ lãnh thổ"],answer:3,explain:"Bản đồ giúp nhà nước quản lí và bảo vệ đất nước."},{id:"sd5-nha-hau-le-15",type:"tf",q:"Văn Miếu – Quốc Tử Giám được xây dựng lần đầu dưới thời Hậu Lê.",answer:!1,explain:"Văn Miếu xây năm 1070 thời Lý; thời Hậu Lê mới dựng bia tiến sĩ."},{id:"sd5-nha-hau-le-16",type:"mc",q:"Lương Thế Vinh, người đỗ Trạng nguyên thời Lê Thánh Tông, nổi tiếng giỏi môn gì?",options:["Âm nhạc","Vẽ tranh","Bơi lội","Toán học"],answer:3,explain:"Lương Thế Vinh nổi tiếng giỏi tính toán, được gọi là “Trạng Lường”."},{id:"sd5-nha-hau-le-17",type:"mc",q:"Điều nào cho thấy nhà Hậu Lê quan tâm đến phụ nữ?",options:["Phụ nữ không được phép đi chợ","Có luật bảo vệ quyền lợi phụ nữ","Phụ nữ bắt buộc phải ở trong nhà","Không có điều luật nào về phụ nữ"],answer:1,explain:"Bộ luật Hồng Đức có những điều bảo vệ quyền lợi phụ nữ."},{id:"sd5-nha-hau-le-18",type:"tf",q:"Lê Thánh Tông là vua thời nhà Trần.",answer:!1,explain:"Lê Thánh Tông là vua thời Hậu Lê."}]},{questions:[{id:"sd5-nha-hau-le-19",type:"mc",q:"Hà đến Văn Miếu, thấy những tấm bia trên lưng rùa đá. Hà rút ra điều gì?",options:["Bia đá chỉ để trang trí cho đẹp","Ngày xưa ở Hà Nội có rất nhiều rùa","Ông cha ta rất coi trọng việc học","Người xưa không đi học, thi cử"],answer:2,explain:"Bia tiến sĩ thể hiện truyền thống hiếu học, tôn trọng người tài."},{id:"sd5-nha-hau-le-20",type:"multi",q:"Học sinh ngày nay tiếp nối truyền thống hiếu học bằng cách nào?",options:["Chăm chỉ học bài","Đọc sách mỗi ngày","Chép bài của bạn","Biết ơn thầy cô"],answers:[0,1,3],explain:"Chăm học, đọc sách, biết ơn thầy cô là tiếp nối truyền thống hiếu học."},{id:"sd5-nha-hau-le-21",type:"tf",q:"Câu “Hiền tài là nguyên khí của quốc gia” nói rằng người tài rất quan trọng với đất nước.",answer:!0,explain:"Câu nói khắc trên bia tiến sĩ, đề cao vai trò của người tài."},{id:"sd5-nha-hau-le-22",type:"mc",q:"Có luật pháp rõ ràng giúp đất nước thế nào?",options:["Rối loạn hơn","Ổn định, có trật tự","Không ai tuân theo","Bị chia cắt"],answer:1,explain:"Luật pháp giúp quản lí xã hội, giữ trật tự."},{id:"sd5-nha-hau-le-23",type:"mc",q:"Nếu ví đất nước như một ngôi nhà, “hiền tài” giống như:",options:["Đồ trang trí đẹp","Bức tranh treo tường","Cánh cửa sổ nhỏ","Rường cột vững chắc"],answer:3,explain:"Người tài là rường cột giúp đất nước vững mạnh."},{id:"sd5-nha-hau-le-24",type:"tf",q:"Bộ luật Hồng Đức ra đời trước Hội nghị Diên Hồng.",answer:!1,explain:"Hội nghị Diên Hồng thời Trần (thế kỉ XIII); Bộ luật Hồng Đức thời Hậu Lê (thế kỉ XV)."},{id:"sd5-nha-hau-le-25",type:"mc",q:"Vì sao nhà Hậu Lê cần có luật bảo vệ đất đai, biên giới?",options:["Để bỏ hoang ruộng đất","Để bán đất cho nước khác","Để giữ gìn đất đai của tổ tiên","Để mở rộng vùng sa mạc"],answer:2,explain:"Luật nghiêm trị kẻ làm mất đất, giữ vững chủ quyền."},{id:"sd5-nha-hau-le-26",type:"multi",q:"Thời Hậu Lê có những nhân vật nổi tiếng nào?",options:["Lê Thánh Tông","Lương Thế Vinh","Nguyễn Trãi","Trần Quốc Toản"],answers:[0,1,2],explain:"Trần Quốc Toản sống thời Trần."}]}],challenge:{questions:[{id:"sd5-nha-hau-le-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Xây Văn Miếu","Hội nghị Diên Hồng","Lê Lợi lập nhà Hậu Lê","Dựng bia tiến sĩ ở Văn Miếu"],explain:"Văn Miếu năm 1070 (Lý) → Diên Hồng (Trần) → năm 1428 Hậu Lê → thời Lê Thánh Tông dựng bia."},{id:"sd5-nha-hau-le-28",type:"match",q:"Nối triều đại với thành tựu.",pairs:[["Nhà Lý","Xây Văn Miếu"],["Nhà Trần","Lập chức Hà đê sứ"],["Nhà Hậu Lê","Bộ luật Hồng Đức"]],explain:"Lý – Văn Miếu, Trần – Hà đê sứ, Hậu Lê – Bộ luật Hồng Đức."},{id:"sd5-nha-hau-le-29",type:"tf",q:"Lương Thế Vinh được gọi là “Trạng Lường” vì giỏi bơi lội.",answer:!1,explain:"Ông được gọi là “Trạng Lường” vì giỏi đo lường, tính toán."},{id:"sd5-nha-hau-le-30",type:"multi",q:"Phát biểu nào đúng về nhà Hậu Lê?",options:["Do Lê Lợi lập năm 1428","Ban hành Bộ luật Hồng Đức","Đóng đô ở Phú Xuân","Coi trọng giáo dục, thi cử"],answers:[0,1,3],explain:"Nhà Hậu Lê đóng đô ở Thăng Long; Phú Xuân là kinh đô thời Nguyễn."},{id:"sd5-nha-hau-le-31",type:"mc",q:"Vì sao thời Lê Thánh Tông được xem là thời kì phát triển?",options:["Mất mùa, đói kém xảy ra liên tục","Có nhiều cuộc chiến tranh liên miên","Có luật pháp, giáo dục phát triển, đất nước ổn định","Đất nước bị chia cắt thành nhiều vùng"],answer:2,explain:"Luật pháp chặt chẽ, giáo dục phát triển, đất nước ổn định và vững mạnh."},{id:"sd5-nha-hau-le-32",type:"mc",q:"Ở Văn Miếu, Phúc thấy chữ “Hiền tài là nguyên khí của quốc gia”. Phúc có thể học được điều gì?",options:["Cố gắng học tập để có ích","Chỉ cần vui chơi là đủ","Người tài không cần học","Không cần đọc thêm sách"],answer:0,explain:"Câu nói khuyên ta học tập để trở thành người có ích."}]},summary:["Thời Lê Thánh Tông, đất nước phát triển mạnh.","Bộ luật Hồng Đức bảo vệ chủ quyền và quyền lợi phụ nữ.","Nhà Hậu Lê coi trọng học hành, dựng bia tiến sĩ ở Văn Miếu."]}]},{id:"tay-son-nguyen",title:"Tây Sơn và nhà Nguyễn",lessons:[{id:"sd5-quang-trung",title:"Quang Trung đại phá quân Thanh",weeks:[21,21],learn:[{title:"Phong trào Tây Sơn",text:"Ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ dựng cờ khởi nghĩa ở Tây Sơn (Bình Định cũ, nay thuộc tỉnh Gia Lai). Năm 1785, Nguyễn Huệ đánh tan quân Xiêm ở Rạch Gầm – Xoài Mút.",example:"🚩 Tây Sơn"},{title:"Lên ngôi Hoàng đế",text:"Cuối năm 1788, quân Thanh kéo sang xâm lược nước ta. Nguyễn Huệ lên ngôi Hoàng đế ở Phú Xuân (Huế), lấy niên hiệu Quang Trung, rồi thần tốc tiến quân ra Bắc.",example:"👑 Quang Trung"},{title:"Tết Kỷ Dậu 1789",text:"Dịp Tết Kỷ Dậu năm 1789, quân Tây Sơn đánh tan quân Thanh ở Ngọc Hồi, Đống Đa. Mùng 5 Tết, vua Quang Trung tiến vào Thăng Long.",example:"🎆 Ngọc Hồi – Đống Đa"}],practice:[{questions:[{id:"sd5-quang-trung-01",type:"mc",q:"Vua Quang Trung đại phá quân Thanh vào năm nào?",options:["Năm 1428","Năm 1945","Năm 1802","Năm 1789"],answer:3,explain:"Tết Kỷ Dậu năm 1789, Quang Trung đại phá quân Thanh.",emoji:"🎆"},{id:"sd5-quang-trung-02",type:"mc",q:"Quang Trung là niên hiệu của ai?",options:["Nguyễn Nhạc","Nguyễn Huệ","Nguyễn Lữ","Nguyễn Ánh"],answer:1,explain:"Nguyễn Huệ lên ngôi Hoàng đế, lấy niên hiệu Quang Trung."},{id:"sd5-quang-trung-03",type:"mc",q:"Năm 1789, quân Tây Sơn đánh tan quân xâm lược nào?",options:["Quân Minh","Quân Xiêm","Quân Tống","Quân Thanh"],answer:3,explain:"Năm 1789, quân Tây Sơn đánh tan quân Thanh."},{id:"sd5-quang-trung-04",type:"tf",q:"Trận đánh quân Thanh diễn ra vào dịp Tết Kỷ Dậu.",answer:!0,explain:"Quang Trung tấn công vào dịp Tết Kỷ Dậu năm 1789."},{id:"sd5-quang-trung-05",type:"multi",q:"Ba anh em nhà Tây Sơn là:",options:["Nguyễn Nhạc","Nguyễn Huệ","Nguyễn Lữ","Nguyễn Trãi"],answers:[0,1,2],explain:"Ba anh em Tây Sơn là Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ; Nguyễn Trãi sống thời Lê."},{id:"sd5-quang-trung-06",type:"fill",q:"Năm 1789, quân Tây Sơn thắng lớn ở Ngọc Hồi và Đống … .",answer:["Đa"],explain:"Đó là chiến thắng Ngọc Hồi – Đống Đa."},{id:"sd5-quang-trung-07",type:"mc",q:"Nguyễn Huệ lên ngôi Hoàng đế ở đâu?",options:["Thăng Long","Hoa Lư","Phú Xuân","Cổ Loa"],answer:2,explain:"Nguyễn Huệ lên ngôi ở Phú Xuân, tức Huế ngày nay."},{id:"sd5-quang-trung-08",type:"tf",q:"Năm 1785, Nguyễn Huệ đánh tan quân Thanh ở Rạch Gầm – Xoài Mút.",answer:!1,explain:"Ở Rạch Gầm – Xoài Mút năm 1785, Nguyễn Huệ đánh tan quân Xiêm; quân Thanh bị đánh tan năm 1789."},{id:"sd5-quang-trung-09",type:"tf",q:"Vua Quang Trung tiến vào Thăng Long vào ngày mùng 1 Tết.",answer:!1,explain:"Vua Quang Trung tiến vào Thăng Long vào mùng 5 Tết."}]},{questions:[{id:"sd5-quang-trung-10",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Chiến thắng Rạch Gầm – Xoài Mút","Nguyễn Huệ lên ngôi Hoàng đế","Đại phá quân Thanh ở Ngọc Hồi – Đống Đa"],explain:"Năm 1785 → năm 1788 → năm 1789."},{id:"sd5-quang-trung-11",type:"match",q:"Nối sự kiện với năm.",pairs:[["Rạch Gầm – Xoài Mút","Năm 1785"],["Nguyễn Huệ lên ngôi","Năm 1788"],["Ngọc Hồi – Đống Đa","Năm 1789"]],explain:"Rạch Gầm – Xoài Mút 1785, lên ngôi 1788, Ngọc Hồi – Đống Đa 1789."},{id:"sd5-quang-trung-12",type:"mc",q:"Vì sao Quang Trung chọn đánh vào dịp Tết?",options:["Vì quân Thanh lơ là, mải ăn Tết","Vì Tết thời tiết đẹp, dễ hành quân","Vì quân ta đông gấp nhiều lần","Vì không còn ngày nào khác"],answer:0,explain:"Quân Thanh chủ quan ăn Tết, bị đánh bất ngờ."},{id:"sd5-quang-trung-13",type:"tf",q:"Để hành quân nhanh, quân Tây Sơn dùng võng, cứ hai người khiêng một người, thay phiên nhau.",answer:!0,explain:"Cách hành quân này giúp quân Tây Sơn đi rất nhanh mà vẫn giữ sức."},{id:"sd5-quang-trung-14",type:"multi",q:"Điều nào thể hiện tài chỉ huy của vua Quang Trung?",options:["Hành quân thần tốc","Đánh bất ngờ vào dịp Tết","Cho quân ăn Tết sớm rồi lên đường","Chờ giặc đến tận Phú Xuân"],answers:[0,1,2],explain:"Quang Trung chủ động, nhanh chóng, bất ngờ – không chờ giặc đến."},{id:"sd5-quang-trung-15",type:"mc",q:"Tây Sơn, quê hương ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ, nay thuộc tỉnh nào?",options:["Thanh Hóa","Lạng Sơn","Nghệ An","Gia Lai"],answer:3,explain:"Tây Sơn trước thuộc Bình Định; Bình Định đã hợp nhất vào tỉnh Gia Lai."},{id:"sd5-quang-trung-16",type:"tf",q:"Quang Trung đánh quân Minh.",answer:!1,explain:"Quang Trung đánh quân Thanh; quân Minh bị Lê Lợi đánh bại năm 1427."},{id:"sd5-quang-trung-17",type:"mc",q:"Hằng năm, lễ hội Gò Đống Đa ở Hà Nội tổ chức vào ngày nào?",options:["Mùng 10 tháng 3 âm lịch","Ngày 2 tháng 9","Rằm tháng Tám","Mùng 5 tháng Giêng âm lịch"],answer:3,explain:"Lễ hội Gò Đống Đa vào mùng 5 Tết, kỉ niệm chiến thắng năm 1789."},{id:"sd5-quang-trung-18",type:"mc",q:"Vua Quang Trung còn được nhân dân gọi là:",options:["Thánh Gióng","Vua Hùng","Anh hùng “áo vải”","Ông Trạng Lường"],answer:2,explain:"Quang Trung xuất thân từ nhân dân nên được gọi là anh hùng áo vải."}]},{questions:[{id:"sd5-quang-trung-19",type:"mc",q:"Nếu Quang Trung chờ quân Thanh đánh vào Phú Xuân, điều gì có thể xảy ra?",options:["Giặc kịp chuẩn bị, ta khó thắng nhanh","Giặc tự rút quân về nước","Không có gì thay đổi cả","Ta sẽ thắng dễ dàng hơn nhiều"],answer:0,explain:"Chủ động đánh nhanh, bất ngờ giúp ta giành thắng lợi lớn."},{id:"sd5-quang-trung-20",type:"tf",q:"Chiến thắng năm 1789 giữ vững nền độc lập của đất nước.",answer:!0,explain:"Đánh tan quân Thanh, đất nước được bảo vệ."},{id:"sd5-quang-trung-21",type:"tf",q:"Vua Quang Trung cho quân sĩ ăn Tết trước rồi mới tiến quân ra Thăng Long.",answer:!0,explain:"Quân sĩ ăn Tết sớm để giữ tinh thần, rồi bất ngờ tấn công khi giặc đang ăn Tết."},{id:"sd5-quang-trung-22",type:"mc",q:"Vy làm báo tường về “Những người anh hùng áo vải”. Bức tranh nào phù hợp?",options:["Vua Lý Thái Tổ ban Chiếu dời đô","Lê Thánh Tông cho dựng bia tiến sĩ","Ngô Quyền xưng vương ở Cổ Loa","Vua Quang Trung cưỡi voi vào Thăng Long"],answer:3,explain:"Quang Trung là anh hùng áo vải của dân tộc.",emoji:"🐘"},{id:"sd5-quang-trung-23",type:"multi",q:"Bài học rút ra từ chiến thắng năm 1789?",options:["Chủ động, nhanh nhẹn","Biết chớp thời cơ","Chủ quan, lơ là","Đoàn kết, quyết tâm"],answers:[0,1,3],explain:"Quân Thanh chủ quan nên thất bại; ta thắng nhờ chủ động, quyết tâm."},{id:"sd5-quang-trung-24",type:"tf",q:"Quân Thanh thua vì đã chuẩn bị rất cẩn thận trong dịp Tết.",answer:!1,explain:"Quân Thanh thua vì chủ quan, lơ là, mải ăn Tết."},{id:"sd5-quang-trung-25",type:"number",q:"Năm 1789 cách năm 1428 bao nhiêu năm?",answer:361,explain:"1789 − 1428 = 361 năm.",unit:"năm"},{id:"sd5-quang-trung-26",type:"mc",q:"Ở Hà Nội có Gò Đống Đa. Đó là di tích gắn với ai?",options:["Lê Lợi","Trần Hưng Đạo","Quang Trung","Lý Thái Tổ"],answer:2,explain:"Gò Đống Đa gắn với chiến thắng của vua Quang Trung năm 1789."}]}],challenge:{questions:[{id:"sd5-quang-trung-27",type:"order",q:"Sắp xếp những người anh hùng theo thời gian lập chiến công.",items:["Ngô Quyền","Trần Hưng Đạo","Lê Lợi","Quang Trung"],explain:"Năm 938 → năm 1288 → năm 1427 → năm 1789."},{id:"sd5-quang-trung-28",type:"match",q:"Nối người anh hùng với quân xâm lược bị đánh bại.",pairs:[["Lý Thường Kiệt","Quân Tống"],["Lê Lợi","Quân Minh"],["Quang Trung","Quân Thanh"],["Trần Hưng Đạo","Quân Nguyên"]],explain:"Lý Thường Kiệt – Tống, Lê Lợi – Minh, Quang Trung – Thanh, Trần Hưng Đạo – Nguyên."},{id:"sd5-quang-trung-29",type:"multi",q:"Phát biểu nào đúng?",options:["Quang Trung tên thật là Nguyễn Huệ","Năm 1789 đại phá quân Thanh","Quang Trung đóng đô ở Hoa Lư","Chiến thắng vào dịp Tết Kỷ Dậu"],answers:[0,1,3],explain:"Quang Trung lên ngôi ở Phú Xuân, không phải Hoa Lư."},{id:"sd5-quang-trung-30",type:"tf",q:"Rạch Gầm – Xoài Mút là trận Nguyễn Huệ đánh quân Thanh.",answer:!1,explain:"Ở Rạch Gầm – Xoài Mút (năm 1785), Nguyễn Huệ đánh quân Xiêm."},{id:"sd5-quang-trung-31",type:"mc",q:"Vì sao gọi cuộc tiến quân ra Bắc của Quang Trung là “thần tốc”?",options:["Vì hành quân rất nhanh","Vì được thần linh giúp sức","Vì quân đi bằng ô tô","Vì chỉ có một người đi"],answer:0,explain:"Thần tốc nghĩa là nhanh như thần, khiến giặc bất ngờ."},{id:"sd5-quang-trung-32",type:"mc",q:"Lễ hội Gò Đống Đa nhắc nhở chúng ta điều gì?",options:["Ăn Tết thật lâu, thật vui","Đi chơi xa trong dịp Tết","Nhớ ơn vua Quang Trung","Đốt pháo đón năm mới"],answer:2,explain:"Lễ hội để tưởng nhớ chiến công năm 1789."}]},summary:["Nguyễn Huệ lên ngôi Hoàng đế năm 1788, lấy niên hiệu Quang Trung.","Tết Kỷ Dậu năm 1789, Quang Trung đại phá quân Thanh ở Ngọc Hồi, Đống Đa.","Cuộc hành quân thần tốc thể hiện tài chỉ huy của vua Quang Trung."]},{id:"sd5-nha-nguyen",title:"Nhà Nguyễn và Cố đô Huế",weeks:[22,22],learn:[{title:"Nhà Nguyễn thành lập",text:"Năm 1802, Nguyễn Ánh lên ngôi vua, lấy niên hiệu Gia Long, lập ra nhà Nguyễn, đóng đô ở Phú Xuân (Huế). Năm 1804, đặt quốc hiệu là Việt Nam.",example:"👑 Gia Long · 1802"},{title:"Kinh thành Huế",text:"Nhà Nguyễn xây dựng kinh thành Huế với nhiều cung điện, lăng tẩm, đền miếu. Quần thể di tích Cố đô Huế là Di sản văn hóa thế giới; Nhã nhạc cung đình Huế cũng được UNESCO ghi danh.",example:"🏯 Đại Nội · 🎶 Nhã nhạc"},{title:"Giữ gìn biển đảo",text:"Nhà Nguyễn tiếp tục cử người ra quần đảo Hoàng Sa đo đạc, cắm mốc, vẽ bản đồ, khẳng định chủ quyền.",example:"🇻🇳 Hoàng Sa"},{title:"Thực dân Pháp xâm lược",text:"Năm 1858, thực dân Pháp nổ súng xâm lược nước ta tại Đà Nẵng. Nhân dân ta nhiều lần đứng lên chống Pháp.",example:"⚓ 1858"}],practice:[{questions:[{id:"sd5-nha-nguyen-01",type:"mc",q:"Nhà Nguyễn được thành lập vào năm nào?",options:["Năm 1789","Năm 1802","Năm 1858","Năm 1945"],answer:1,explain:"Năm 1802, Nguyễn Ánh lên ngôi, lập ra nhà Nguyễn.",emoji:"👑"},{id:"sd5-nha-nguyen-02",type:"mc",q:"Ai là người lập ra nhà Nguyễn?",options:["Nguyễn Huệ","Nguyễn Nhạc","Nguyễn Trãi","Nguyễn Ánh"],answer:3,explain:"Nguyễn Ánh lập nhà Nguyễn, lấy niên hiệu Gia Long."},{id:"sd5-nha-nguyen-03",type:"mc",q:"Kinh đô của nhà Nguyễn ở đâu?",options:["Thăng Long","Phú Xuân","Hoa Lư","Cổ Loa"],answer:1,explain:"Nhà Nguyễn đóng đô ở Phú Xuân, tức Huế.",emoji:"🏯"},{id:"sd5-nha-nguyen-04",type:"tf",q:"Quần thể di tích Cố đô Huế là Di sản văn hóa thế giới.",answer:!0,explain:"Quần thể di tích Cố đô Huế được UNESCO công nhận."},{id:"sd5-nha-nguyen-05",type:"fill",q:"Nguyễn Ánh lên ngôi, lấy niên hiệu là Gia … .",answer:["Long"],explain:"Niên hiệu của Nguyễn Ánh là Gia Long."},{id:"sd5-nha-nguyen-06",type:"tf",q:"Năm 1858, thực dân Pháp nổ súng xâm lược nước ta tại Cần Thơ.",answer:!1,explain:"Năm 1858, Pháp nổ súng xâm lược nước ta tại Đà Nẵng.",emoji:"⚓"},{id:"sd5-nha-nguyen-07",type:"mc",q:"Nhã nhạc cung đình Huế là:",options:["Âm nhạc cung đình thời Nguyễn","Một món ăn trong cung","Một con sông chảy qua Huế","Một ngọn núi ở gần Huế"],answer:0,explain:"Nhã nhạc là âm nhạc cung đình, được UNESCO ghi danh.",emoji:"🎶"},{id:"sd5-nha-nguyen-08",type:"tf",q:"Nhà Nguyễn đóng đô ở Thăng Long.",answer:!1,explain:"Nhà Nguyễn đóng đô ở Phú Xuân (Huế)."},{id:"sd5-nha-nguyen-09",type:"mc",q:"Năm 1804, nhà Nguyễn đặt quốc hiệu là:",options:["Đại Việt","Văn Lang","Vạn Xuân","Việt Nam"],answer:3,explain:"Năm 1804, quốc hiệu Việt Nam được đặt."}]},{questions:[{id:"sd5-nha-nguyen-10",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Quang Trung đại phá quân Thanh","Nhà Nguyễn thành lập","Đặt quốc hiệu Việt Nam","Thực dân Pháp xâm lược Đà Nẵng"],explain:"Năm 1789 → năm 1802 → năm 1804 → năm 1858."},{id:"sd5-nha-nguyen-11",type:"match",q:"Nối kinh đô với triều đại.",pairs:[["Thăng Long","Nhà Lý"],["Phú Xuân","Nhà Nguyễn"],["Cổ Loa","Âu Lạc"]],explain:"Thăng Long – nhà Lý, Phú Xuân – nhà Nguyễn, Cổ Loa – Âu Lạc."},{id:"sd5-nha-nguyen-12",type:"multi",q:"Những di sản nào gắn với Huế được UNESCO ghi danh?",options:["Quần thể di tích Cố đô Huế","Nhã nhạc cung đình Huế","Vịnh Hạ Long","Thánh địa Mỹ Sơn"],answers:[0,1],explain:"Vịnh Hạ Long ở Quảng Ninh, Mỹ Sơn ở Đà Nẵng."},{id:"sd5-nha-nguyen-13",type:"tf",q:"Nhà Nguyễn cử người ra Hoàng Sa đo đạc, cắm mốc, khẳng định chủ quyền.",answer:!0,explain:"Đó là bằng chứng lịch sử về chủ quyền của Việt Nam ở Hoàng Sa."},{id:"sd5-nha-nguyen-14",type:"mc",q:"Kinh thành Huế nằm bên bờ sông nào?",options:["Sông Hồng","Sông Mê Công","Sông Bạch Đằng","Sông Hương"],answer:3,explain:"Kinh thành Huế nằm bên bờ sông Hương."},{id:"sd5-nha-nguyen-15",type:"mc",q:"Pháp nổ súng xâm lược nước ta đầu tiên ở đâu?",options:["Hà Nội","Đà Nẵng","Cần Thơ","Hải Phòng"],answer:1,explain:"Năm 1858, Pháp nổ súng tại Đà Nẵng."},{id:"sd5-nha-nguyen-16",type:"tf",q:"Huế hiện nay là một thành phố trực thuộc Trung ương.",answer:!0,explain:"Huế là một trong 6 thành phố trực thuộc Trung ương."},{id:"sd5-nha-nguyen-17",type:"mc",q:"Nhà Nguyễn là triều đại phong kiến cuối cùng của nước ta. Điều này nghĩa là:",options:["Nhà Nguyễn có trước cả nhà Lý","Sau nhà Nguyễn không còn triều đại vua chúa","Nhà Nguyễn chỉ có duy nhất một vua","Nhà Nguyễn đóng đô ở thành Thăng Long"],answer:1,explain:"Sau nhà Nguyễn, nước ta không còn chế độ vua chúa."},{id:"sd5-nha-nguyen-18",type:"mc",q:"Ai lãnh đạo nhân dân đánh quân Thanh trước khi nhà Nguyễn thành lập?",options:["Quang Trung","Gia Long","Lê Lợi","Ngô Quyền"],answer:0,explain:"Quang Trung đánh quân Thanh năm 1789, trước năm 1802."}]},{questions:[{id:"sd5-nha-nguyen-19",type:"mc",q:"Thảo đi tham quan Đại Nội Huế. Thảo nên làm gì?",options:["Leo lên tường thành để chụp ảnh","Khắc tên lên cột làm kỉ niệm","Đi đúng lối, không chạm hiện vật","Bẻ cành cây trong vườn ngự"],answer:2,explain:"Ứng xử văn minh giúp bảo vệ di tích."},{id:"sd5-nha-nguyen-20",type:"tf",q:"Những tư liệu thời Nguyễn về Hoàng Sa là bằng chứng giúp khẳng định chủ quyền của Việt Nam.",answer:!0,explain:"Tư liệu lịch sử chứng minh nhà nước Việt Nam đã quản lí Hoàng Sa từ lâu."},{id:"sd5-nha-nguyen-21",type:"multi",q:"Đâu là di tích, công trình ở Huế?",options:["Đại Nội","Lăng các vua Nguyễn","Chùa Thiên Mụ","Thành Cổ Loa"],answers:[0,1,2],explain:"Thành Cổ Loa ở Hà Nội."},{id:"sd5-nha-nguyen-22",type:"mc",q:"Vì sao cần bảo tồn, tu bổ di tích Cố đô Huế?",options:["Vì cần lấy chỗ để xây nhà ở","Vì đây là di sản quý của dân tộc","Vì di tích cần được phá bỏ","Vì di tích không có giá trị"],answer:1,explain:"Di sản giúp con cháu hiểu lịch sử và thu hút du khách."},{id:"sd5-nha-nguyen-23",type:"number",q:"Từ năm nhà Nguyễn thành lập (1802) đến năm Pháp xâm lược (1858) là bao nhiêu năm?",answer:56,explain:"1858 − 1802 = 56 năm.",unit:"năm"},{id:"sd5-nha-nguyen-24",type:"tf",q:"Phú Xuân và Thăng Long là cùng một nơi.",answer:!1,explain:"Phú Xuân là Huế, Thăng Long là Hà Nội."},{id:"sd5-nha-nguyen-25",type:"mc",q:"Dũng muốn giới thiệu với bạn nước ngoài về âm nhạc cung đình Việt Nam. Dũng nên giới thiệu:",options:["Quan họ Bắc Ninh","Đờn ca tài tử Nam Bộ","Nhã nhạc cung đình Huế","Hát xoan Phú Thọ"],answer:2,explain:"Nhã nhạc cung đình Huế là âm nhạc cung đình triều Nguyễn."},{id:"sd5-nha-nguyen-26",type:"mc",q:"Sau năm 1858, nhân dân ta đã làm gì?",options:["Nhiều lần đứng lên chống Pháp","Chào đón quân Pháp","Bỏ đất nước ra nước ngoài","Không có phản ứng gì"],answer:0,explain:"Nhân dân ta liên tục kháng chiến chống Pháp xâm lược."}]}],challenge:{questions:[{id:"sd5-nha-nguyen-27",type:"order",q:"Sắp xếp các kinh đô theo thứ tự thời gian.",items:["Cổ Loa","Hoa Lư","Thăng Long","Phú Xuân"],explain:"Cổ Loa (Âu Lạc) → Hoa Lư → Thăng Long (năm 1010) → Phú Xuân (nhà Nguyễn)."},{id:"sd5-nha-nguyen-28",type:"match",q:"Nối năm với sự kiện.",pairs:[["Năm 1802","Nhà Nguyễn thành lập"],["Năm 1804","Đặt quốc hiệu Việt Nam"],["Năm 1858","Pháp xâm lược Đà Nẵng"],["Năm 1789","Đại phá quân Thanh"]],explain:"Mỗi năm gắn với một sự kiện lịch sử."},{id:"sd5-nha-nguyen-29",type:"multi",q:"Phát biểu nào đúng về nhà Nguyễn?",options:["Đóng đô ở Huế","Đặt quốc hiệu Việt Nam năm 1804","Đánh thắng quân Mông – Nguyên","Cắm mốc chủ quyền ở Hoàng Sa"],answers:[0,1,3],explain:"Đánh thắng quân Mông – Nguyên là chiến công của nhà Trần."},{id:"sd5-nha-nguyen-30",type:"tf",q:"Nhà Nguyễn là triều đại phong kiến đầu tiên của Việt Nam.",answer:!1,explain:"Nhà Nguyễn là triều đại phong kiến cuối cùng của Việt Nam."},{id:"sd5-nha-nguyen-31",type:"number",q:"Từ năm 1804 (đặt quốc hiệu Việt Nam) đến năm 1945 là bao nhiêu năm?",answer:141,explain:"1945 − 1804 = 141 năm.",unit:"năm"},{id:"sd5-nha-nguyen-32",type:"mc",q:"Tư liệu nào giúp khẳng định Hoàng Sa là của Việt Nam?",options:["Sách sử, bản đồ của nhà nước Việt Nam","Các truyện cổ tích về biển","Những bài hát thiếu nhi","Trò chơi điện tử về đảo"],answer:0,explain:"Bản đồ, sách sử, châu bản ghi chép việc quản lí Hoàng Sa là bằng chứng lịch sử."}]},summary:["Năm 1802, Nguyễn Ánh lập nhà Nguyễn, đóng đô ở Phú Xuân (Huế).","Quần thể di tích Cố đô Huế là Di sản văn hóa thế giới.","Nhà Nguyễn cắm mốc chủ quyền ở Hoàng Sa; năm 1858 Pháp xâm lược nước ta."]}]},{id:"doc-lap-tu-do",title:"Giành độc lập và kháng chiến chống Pháp",lessons:[{id:"sd5-cach-mang-thang-tam",title:"Cách mạng tháng Tám năm 1945",weeks:[23,23],learn:[{title:"Người tìm đường cứu nước",text:"Ngày 5 tháng 6 năm 1911, Nguyễn Tất Thành (sau này là Chủ tịch Hồ Chí Minh) rời bến Nhà Rồng ra đi tìm đường cứu nước. Ngày 3 tháng 2 năm 1930, Đảng Cộng sản Việt Nam được thành lập.",example:"🚢 1911 · ☭ 1930"},{title:"Tổng khởi nghĩa tháng Tám",text:"Tháng 8 năm 1945, nhân dân cả nước nổi dậy giành chính quyền. Ngày 19 tháng 8 giành chính quyền ở Hà Nội, ngày 23 tháng 8 ở Huế, ngày 25 tháng 8 ở Sài Gòn.",example:"✊ 19/8 · 23/8 · 25/8"},{title:"Tuyên ngôn Độc lập",text:"Ngày 2 tháng 9 năm 1945, tại Quảng trường Ba Đình (Hà Nội), Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Ngày 2 tháng 9 trở thành ngày Quốc khánh.",example:"🇻🇳 2/9/1945 · Ba Đình"}],practice:[{questions:[{id:"sd5-cach-mang-thang-tam-01",type:"mc",q:"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập vào ngày nào?",options:["19 tháng 8 năm 1945","30 tháng 4 năm 1975","2 tháng 9 năm 1945","7 tháng 5 năm 1954"],answer:2,explain:"Ngày 2 tháng 9 năm 1945, Bác Hồ đọc Tuyên ngôn Độc lập.",emoji:"🇻🇳"},{id:"sd5-cach-mang-thang-tam-02",type:"mc",q:"Tuyên ngôn Độc lập được đọc ở đâu?",options:["Quảng trường Ba Đình","Dinh Độc Lập","Bến Nhà Rồng","Văn Miếu – Quốc Tử Giám"],answer:0,explain:"Bác Hồ đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, Hà Nội."},{id:"sd5-cach-mang-thang-tam-03",type:"tf",q:"Ngày 2 tháng 9 là ngày Quốc khánh của nước ta.",answer:!0,explain:"Ngày 2 tháng 9 năm 1945 nước Việt Nam Dân chủ Cộng hòa ra đời.",emoji:"🎉"},{id:"sd5-cach-mang-thang-tam-04",type:"mc",q:"Ngày nhân dân Hà Nội giành chính quyền trong Cách mạng tháng Tám là:",options:["25 tháng 8 năm 1945","19 tháng 8 năm 1945","2 tháng 9 năm 1945","3 tháng 2 năm 1930"],answer:1,explain:"Ngày 19 tháng 8 năm 1945, Hà Nội giành chính quyền."},{id:"sd5-cach-mang-thang-tam-05",type:"fill",q:"Ngày 2 tháng 9 năm 1945, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn … lập.",answer:["Độc"],explain:"Đó là bản Tuyên ngôn Độc lập."},{id:"sd5-cach-mang-thang-tam-06",type:"mc",q:"Đảng Cộng sản Việt Nam được thành lập ngày nào?",options:["2 tháng 9 năm 1945","3 tháng 2 năm 1930","5 tháng 6 năm 1911","19 tháng 8 năm 1945"],answer:1,explain:"Đảng Cộng sản Việt Nam ra đời ngày 3 tháng 2 năm 1930."},{id:"sd5-cach-mang-thang-tam-07",type:"tf",q:"Năm 1911, Nguyễn Tất Thành rời bến Nhà Rồng ra đi tìm đường cứu nước.",answer:!0,explain:"Ngày 5 tháng 6 năm 1911, Người ra đi từ bến Nhà Rồng.",emoji:"🚢"},{id:"sd5-cach-mang-thang-tam-08",type:"mc",q:"Tuyên ngôn Độc lập khai sinh ra nước nào?",options:["Đại Việt","Cộng hòa xã hội chủ nghĩa Việt Nam","Việt Nam Dân chủ Cộng hòa","Đại Nam"],answer:2,explain:"Năm 1945, nước Việt Nam Dân chủ Cộng hòa ra đời."},{id:"sd5-cach-mang-thang-tam-09",type:"tf",q:"Cách mạng tháng Tám diễn ra năm 1954.",answer:!1,explain:"Cách mạng tháng Tám diễn ra năm 1945."}]},{questions:[{id:"sd5-cach-mang-thang-tam-10",type:"order",q:"Sắp xếp các nơi giành chính quyền theo thứ tự thời gian.",items:["Hà Nội","Huế","Sài Gòn"],explain:"Hà Nội ngày 19, Huế ngày 23, Sài Gòn ngày 25 tháng 8 năm 1945."},{id:"sd5-cach-mang-thang-tam-11",type:"match",q:"Nối sự kiện với thời gian.",pairs:[["Nguyễn Tất Thành ra đi tìm đường cứu nước","Năm 1911"],["Thành lập Đảng Cộng sản Việt Nam","Năm 1930"],["Cách mạng tháng Tám","Năm 1945"]],explain:"Năm 1911 → năm 1930 → năm 1945."},{id:"sd5-cach-mang-thang-tam-12",type:"mc",q:"Câu nào được trích từ Tuyên ngôn Độc lập năm 1945?",options:["“Sông núi nước Nam vua Nam ở, rành rành định phận…”","“Nước Việt Nam có quyền hưởng tự do và độc lập…”","“Đem đại nghĩa để thắng hung tàn, lấy chí nhân…”","“Ta thường tới bữa quên ăn, nửa đêm vỗ gối…”"],answer:1,explain:"Tuyên ngôn Độc lập khẳng định quyền tự do, độc lập của nước Việt Nam."},{id:"sd5-cach-mang-thang-tam-13",type:"multi",q:"Ý nghĩa của Cách mạng tháng Tám là gì?",options:["Nhân dân giành được chính quyền","Nước Việt Nam Dân chủ Cộng hòa ra đời","Nhân dân từ thân phận nô lệ trở thành người làm chủ đất nước","Đất nước bị chia cắt"],answers:[0,1,2],explain:"Cách mạng tháng Tám đem lại độc lập, tự do cho nhân dân."},{id:"sd5-cach-mang-thang-tam-14",type:"tf",q:"Ngày 19 tháng 8 hằng năm là ngày kỉ niệm Cách mạng tháng Tám.",answer:!0,explain:"Ngày 19 tháng 8 năm 1945 nhân dân Hà Nội giành chính quyền."},{id:"sd5-cach-mang-thang-tam-15",type:"mc",q:"Thành phố Sài Gòn giành chính quyền vào ngày nào?",options:["19 tháng 8 năm 1945","23 tháng 8 năm 1945","25 tháng 8 năm 1945","2 tháng 9 năm 1945"],answer:2,explain:"Sài Gòn giành chính quyền ngày 25 tháng 8 năm 1945."},{id:"sd5-cach-mang-thang-tam-16",type:"tf",q:"Bến Nhà Rồng ở thành phố Hải Phòng.",answer:!1,explain:"Bến Nhà Rồng ở Thành phố Hồ Chí Minh."},{id:"sd5-cach-mang-thang-tam-17",type:"mc",q:"Vì sao Cách mạng tháng Tám giành thắng lợi nhanh?",options:["Vì trời mưa to nên giặc bỏ chạy","Vì không có ai chống lại cả","Toàn dân đồng lòng, có Đảng lãnh đạo","Vì có quân nước ngoài đánh giúp"],answer:2,explain:"Sự lãnh đạo đúng đắn và tinh thần đoàn kết toàn dân đem lại thắng lợi."},{id:"sd5-cach-mang-thang-tam-18",type:"number",q:"Từ năm Bác Hồ ra đi tìm đường cứu nước (1911) đến năm 1945 là bao nhiêu năm?",answer:34,explain:"1945 − 1911 = 34 năm.",unit:"năm"}]},{questions:[{id:"sd5-cach-mang-thang-tam-19",type:"mc",q:"Lớp Minh tổ chức hoạt động chào mừng ngày Quốc khánh. Hoạt động đó diễn ra vào ngày nào?",options:["30 tháng 4","2 tháng 9","19 tháng 5","1 tháng 6"],answer:1,explain:"Quốc khánh nước ta là ngày 2 tháng 9."},{id:"sd5-cach-mang-thang-tam-20",type:"tf",q:"Ngày nay, Lăng Chủ tịch Hồ Chí Minh nằm ở Quảng trường Ba Đình.",answer:!0,explain:"Lăng Bác ở Quảng trường Ba Đình, nơi Người đọc Tuyên ngôn Độc lập."},{id:"sd5-cach-mang-thang-tam-21",type:"multi",q:"Em có thể làm gì vào dịp Quốc khánh?",options:["Treo cờ Tổ quốc","Tìm hiểu về Cách mạng tháng Tám","Vẽ bậy lên cờ","Tham gia văn nghệ chào mừng"],answers:[0,1,3],explain:"Treo cờ, tìm hiểu lịch sử, tham gia văn nghệ là việc làm ý nghĩa."},{id:"sd5-cach-mang-thang-tam-22",type:"mc",q:"Hình ảnh nào phù hợp với ngày 2 tháng 9 năm 1945?",options:["Xe tăng húc đổ cổng Dinh Độc Lập","Thuyền giặc mắc cọc trên sông","Biển người ở Ba Đình nghe Bác đọc","Bộ đội kéo pháo lên núi cao"],answer:2,explain:"Ngày 2 tháng 9 năm 1945, hàng chục vạn người dự lễ ở Ba Đình."},{id:"sd5-cach-mang-thang-tam-23",type:"tf",q:"Sau Cách mạng tháng Tám, nước ta vẫn là thuộc địa của Pháp.",answer:!1,explain:"Cách mạng tháng Tám giành độc lập, lập nên nước Việt Nam Dân chủ Cộng hòa."},{id:"sd5-cach-mang-thang-tam-24",type:"number",q:"Năm 2025, nước ta kỉ niệm bao nhiêu năm ngày Quốc khánh 2 tháng 9?",answer:80,explain:"2025 − 1945 = 80 năm.",unit:"năm"},{id:"sd5-cach-mang-thang-tam-25",type:"mc",q:"Vì sao Tuyên ngôn Độc lập năm 1945 là văn kiện rất quan trọng?",options:["Vì đó là một bài thơ rất hay","Tuyên bố nền độc lập của Việt Nam","Vì văn bản nói về thời tiết","Vì đó là bộ luật giao thông"],answer:1,explain:"Tuyên ngôn khẳng định quyền độc lập, tự do của dân tộc."},{id:"sd5-cach-mang-thang-tam-26",type:"mc",q:"Ngọc kể: “Bác Hồ đọc Tuyên ngôn Độc lập ở Dinh Độc Lập.” Câu đó cần sửa thế nào?",options:["Câu đó đúng, không cần sửa","Bác đọc ở bến Nhà Rồng","Bác đọc ở Kinh thành Huế","Bác đọc ở Quảng trường Ba Đình"],answer:3,explain:"Tuyên ngôn Độc lập được đọc tại Quảng trường Ba Đình, Hà Nội."}]}],challenge:{questions:[{id:"sd5-cach-mang-thang-tam-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Bác Hồ ra đi tìm đường cứu nước","Thành lập Đảng Cộng sản Việt Nam","Hà Nội giành chính quyền","Đọc Tuyên ngôn Độc lập"],explain:"Năm 1911 → năm 1930 → 19/8/1945 → 2/9/1945."},{id:"sd5-cach-mang-thang-tam-28",type:"match",q:"Nối ngày với sự kiện năm 1945.",pairs:[["19 tháng 8","Hà Nội giành chính quyền"],["23 tháng 8","Huế giành chính quyền"],["25 tháng 8","Sài Gòn giành chính quyền"],["2 tháng 9","Đọc Tuyên ngôn Độc lập"]],explain:"Các mốc thời gian quan trọng của năm 1945."},{id:"sd5-cach-mang-thang-tam-29",type:"multi",q:"Phát biểu nào đúng?",options:["Tuyên ngôn Độc lập đọc tại Ba Đình","Đảng Cộng sản Việt Nam thành lập năm 1930","Cách mạng tháng Tám năm 1975","Ngày 2 tháng 9 là Quốc khánh"],answers:[0,1,3],explain:"Cách mạng tháng Tám diễn ra năm 1945."},{id:"sd5-cach-mang-thang-tam-30",type:"tf",q:"Sau Cách mạng tháng Tám, nhân dân ta vẫn chưa được làm chủ đất nước.",answer:!1,explain:"Cách mạng tháng Tám đem lại độc lập, nhân dân trở thành người làm chủ đất nước."},{id:"sd5-cach-mang-thang-tam-31",type:"number",q:"Ngày Huế giành chính quyền (23 tháng 8) sau ngày Hà Nội (19 tháng 8) mấy ngày?",answer:4,explain:"23 − 19 = 4 ngày.",unit:"ngày"},{id:"sd5-cach-mang-thang-tam-32",type:"mc",q:"Ý nào thể hiện đúng nhất lòng biết ơn Bác Hồ của học sinh?",options:["Trêu chọc bạn","Chỉ nói “Em yêu Bác” mà không làm gì","Không học bài","Thực hiện tốt Năm điều Bác Hồ dạy"],answer:3,explain:"Làm theo lời Bác dạy là cách thể hiện lòng biết ơn thiết thực."}]},summary:["Tháng 8 năm 1945, nhân dân cả nước tổng khởi nghĩa giành chính quyền.","Ngày 2 tháng 9 năm 1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình.","Nước Việt Nam Dân chủ Cộng hòa ra đời; ngày 2 tháng 9 là ngày Quốc khánh."]},{id:"sd5-dien-bien-phu",title:"Chiến dịch Điện Biên Phủ năm 1954",weeks:[24,24],learn:[{title:"Tập đoàn cứ điểm",text:"Thực dân Pháp xây dựng ở Điện Biên Phủ một tập đoàn cứ điểm mạnh, cho là “không thể công phá”.",example:"⛰️ Điện Biên Phủ"},{title:"56 ngày đêm",text:"Chiến dịch Điện Biên Phủ do Đại tướng Võ Nguyên Giáp chỉ huy, bắt đầu ngày 13 tháng 3 năm 1954 và kết thúc thắng lợi ngày 7 tháng 5 năm 1954, sau 56 ngày đêm.",example:"13/3 ➜ 7/5/1954"},{title:"Những tấm gương anh hùng",text:"Bộ đội kéo pháo vào trận địa; dân công dùng xe đạp thồ chở lương thực. Nhiều anh hùng như Tô Vĩnh Diện, Phan Đình Giót đã chiến đấu, hi sinh anh dũng.",example:"🚲 xe đạp thồ"},{title:"Ý nghĩa",text:"Chiến thắng Điện Biên Phủ “lừng lẫy năm châu, chấn động địa cầu”, buộc Pháp kí Hiệp định Giơ-ne-vơ năm 1954, chấm dứt chiến tranh ở Đông Dương.",example:"🏆 1954"}],practice:[{questions:[{id:"sd5-dien-bien-phu-01",type:"mc",q:"Chiến thắng Điện Biên Phủ diễn ra năm nào?",options:["Năm 1945","Năm 1975","Năm 1954","Năm 1986"],answer:2,explain:"Chiến dịch Điện Biên Phủ thắng lợi năm 1954.",emoji:"🏆"},{id:"sd5-dien-bien-phu-02",type:"mc",q:"Ai là người chỉ huy chiến dịch Điện Biên Phủ?",options:["Đại tướng Võ Nguyên Giáp","Trần Hưng Đạo","Vua Quang Trung","Lý Thường Kiệt"],answer:0,explain:"Đại tướng Võ Nguyên Giáp chỉ huy chiến dịch Điện Biên Phủ."},{id:"sd5-dien-bien-phu-03",type:"number",q:"Chiến dịch Điện Biên Phủ kéo dài bao nhiêu ngày đêm?",answer:56,explain:"Chiến dịch kéo dài 56 ngày đêm, từ 13/3 đến 7/5/1954.",unit:"ngày đêm"},{id:"sd5-dien-bien-phu-04",type:"mc",q:"Chiến dịch Điện Biên Phủ kết thúc thắng lợi vào ngày nào?",options:["13 tháng 3 năm 1954","7 tháng 5 năm 1954","2 tháng 9 năm 1945","30 tháng 4 năm 1975"],answer:1,explain:"Ngày 7 tháng 5 năm 1954, chiến dịch toàn thắng."},{id:"sd5-dien-bien-phu-05",type:"tf",q:"Ở Điện Biên Phủ, ta chiến đấu chống thực dân Pháp.",answer:!0,explain:"Điện Biên Phủ là tập đoàn cứ điểm mạnh nhất của thực dân Pháp ở Đông Dương."},{id:"sd5-dien-bien-phu-06",type:"fill",q:"Chiến thắng Điện Biên Phủ “lừng lẫy năm châu, chấn động địa …”.",answer:["cầu"],explain:"Câu đầy đủ: “lừng lẫy năm châu, chấn động địa cầu”."},{id:"sd5-dien-bien-phu-07",type:"tf",q:"Dân công chở lương thực cho chiến dịch Điện Biên Phủ chủ yếu bằng máy bay.",answer:!1,explain:"Dân công dùng xe đạp thồ, gánh gồng để chở lương thực qua đường rừng núi.",emoji:"🚲"},{id:"sd5-dien-bien-phu-08",type:"mc",q:"Điện Biên Phủ thuộc tỉnh nào?",options:["Lạng Sơn","Thái Nguyên","Điện Biên","Lào Cai"],answer:2,explain:"Điện Biên Phủ thuộc tỉnh Điện Biên."},{id:"sd5-dien-bien-phu-09",type:"tf",q:"Chiến dịch Điện Biên Phủ do vua Quang Trung chỉ huy.",answer:!1,explain:"Chiến dịch do Đại tướng Võ Nguyên Giáp chỉ huy."}]},{questions:[{id:"sd5-dien-bien-phu-10",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Cách mạng tháng Tám","Chiến dịch Điện Biên Phủ mở màn","Chiến dịch Điện Biên Phủ toàn thắng","Kí Hiệp định Giơ-ne-vơ"],explain:"Năm 1945 → 13/3/1954 → 7/5/1954 → Hiệp định Giơ-ne-vơ cùng năm 1954."},{id:"sd5-dien-bien-phu-11",type:"match",q:"Nối anh hùng với việc làm.",pairs:[["Tô Vĩnh Diện","Lấy thân mình chèn pháo"],["Phan Đình Giót","Lấy thân mình lấp lỗ châu mai"],["Võ Nguyên Giáp","Chỉ huy chiến dịch"]],explain:"Mỗi người góp phần làm nên chiến thắng Điện Biên Phủ."},{id:"sd5-dien-bien-phu-12",type:"multi",q:"Vì sao ta thắng ở Điện Biên Phủ?",options:["Bộ đội chiến đấu dũng cảm","Nhân dân hết lòng ủng hộ, tiếp tế","Có sự chỉ huy tài giỏi","Quân Pháp không có vũ khí"],answers:[0,1,2],explain:"Pháp có nhiều vũ khí hiện đại; ta thắng nhờ dũng cảm, toàn dân ủng hộ và chỉ huy giỏi."},{id:"sd5-dien-bien-phu-13",type:"tf",q:"Thực dân Pháp cho rằng Điện Biên Phủ là pháo đài “không thể công phá”.",answer:!0,explain:"Pháp tự tin vào tập đoàn cứ điểm này nhưng đã thất bại."},{id:"sd5-dien-bien-phu-14",type:"mc",q:"Hiệp định nào được kí sau chiến thắng Điện Biên Phủ?",options:["Hiệp định Giơ-ne-vơ","Hiệp định Pa-ri","Hiệp định Bạch Đằng","Bình Ngô đại cáo"],answer:0,explain:"Năm 1954, Pháp kí Hiệp định Giơ-ne-vơ, chấm dứt chiến tranh ở Đông Dương."},{id:"sd5-dien-bien-phu-15",type:"mc",q:"Vì sao việc kéo pháo vào trận địa rất gian khổ?",options:["Vì pháo rất nhẹ, dễ bị gió thổi","Vì đường đi bằng phẳng, rộng rãi","Vì đường núi dốc, pháo rất nặng","Vì đã có ô tô chở sẵn đến nơi"],answer:2,explain:"Bộ đội phải dùng sức người kéo pháo nặng qua núi đèo."},{id:"sd5-dien-bien-phu-16",type:"tf",q:"Sau năm 1954, đất nước tạm thời bị chia cắt làm hai miền.",answer:!0,explain:"Sau Hiệp định Giơ-ne-vơ, nước ta tạm chia hai miền, lấy vĩ tuyến 17 làm ranh giới tạm thời."},{id:"sd5-dien-bien-phu-17",type:"number",q:"Chiến thắng Điện Biên Phủ (1954) cách Cách mạng tháng Tám (1945) bao nhiêu năm?",answer:9,explain:"1954 − 1945 = 9 năm.",unit:"năm"},{id:"sd5-dien-bien-phu-18",type:"mc",q:"Ranh giới tạm thời chia cắt hai miền sau năm 1954 là:",options:["Sông Hồng","Sông Mê Công ở Nam Bộ","Dãy Bạch Mã","Vĩ tuyến 17 (sông Bến Hải)"],answer:3,explain:"Vĩ tuyến 17, dọc sông Bến Hải ở Quảng Trị, là ranh giới tạm thời."}]},{questions:[{id:"sd5-dien-bien-phu-19",type:"mc",q:"Hình ảnh xe đạp thồ ở Điện Biên Phủ cho thấy điều gì?",options:["Nhân dân không quan tâm đến chiến dịch","Toàn dân góp sức đánh giặc","Quân ta có rất nhiều ô tô","Đường lên Điện Biên rất bằng phẳng"],answer:1,explain:"Dân công bằng sức người, xe đạp thồ đã góp phần làm nên chiến thắng."},{id:"sd5-dien-bien-phu-20",type:"tf",q:"Chiến thắng Điện Biên Phủ cổ vũ nhiều dân tộc bị áp bức trên thế giới đấu tranh giành độc lập.",answer:!0,explain:"Chiến thắng có ý nghĩa quốc tế to lớn."},{id:"sd5-dien-bien-phu-21",type:"mc",q:"Bình đến thăm đồi A1 và Bảo tàng Chiến thắng lịch sử Điện Biên Phủ. Bình đang ở tỉnh nào?",options:["Điện Biên","Sơn La","Lai Châu","Lào Cai"],answer:0,explain:"Các di tích chiến trường Điện Biên Phủ ở tỉnh Điện Biên."},{id:"sd5-dien-bien-phu-22",type:"multi",q:"Học tập các anh hùng ở Điện Biên Phủ, học sinh có thể:",options:["Vượt khó trong học tập","Biết ơn các thương binh, liệt sĩ","Bỏ cuộc khi gặp bài khó","Đoàn kết giúp bạn"],answers:[0,1,3],explain:"Vượt khó, biết ơn, đoàn kết là những việc làm tốt."},{id:"sd5-dien-bien-phu-23",type:"mc",q:"Ngày 7 tháng 5 hằng năm nhắc ta nhớ đến sự kiện nào?",options:["Chiến thắng Điện Biên Phủ","Ngày Quốc khánh","Ngày Giải phóng miền Nam","Ngày Giỗ Tổ Hùng Vương"],answer:0,explain:"Ngày 7 tháng 5 năm 1954 là ngày chiến thắng Điện Biên Phủ."},{id:"sd5-dien-bien-phu-24",type:"tf",q:"Ở Điện Biên Phủ, ta chỉ cần vài ngày là đã thắng.",answer:!1,explain:"Chiến dịch kéo dài 56 ngày đêm, rất gian khổ."},{id:"sd5-dien-bien-phu-25",type:"number",q:"Năm 2024, nước ta kỉ niệm chiến thắng Điện Biên Phủ tròn bao nhiêu năm?",answer:70,explain:"2024 − 1954 = 70 năm.",unit:"năm"},{id:"sd5-dien-bien-phu-26",type:"mc",q:"Vì sao gọi là chiến dịch “56 ngày đêm”?",options:["Vì chỉ có 56 chiến sĩ tham gia","Vì chỉ đánh vào ban đêm","Vì ta đánh đúng 56 trận","Vì đánh liên tục suốt 56 ngày"],answer:3,explain:"Từ 13/3 đến 7/5/1954, quân ta chiến đấu liên tục 56 ngày đêm."}]}],challenge:{questions:[{id:"sd5-dien-bien-phu-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Đảng Cộng sản Việt Nam ra đời","Tuyên ngôn Độc lập","Chiến thắng Điện Biên Phủ","Kí Hiệp định Giơ-ne-vơ"],explain:"Năm 1930 → năm 1945 → 7/5/1954 → Hiệp định Giơ-ne-vơ tháng 7 năm 1954."},{id:"sd5-dien-bien-phu-28",type:"match",q:"Nối ngày với sự kiện.",pairs:[["13 tháng 3 năm 1954","Mở màn chiến dịch Điện Biên Phủ"],["7 tháng 5 năm 1954","Chiến dịch Điện Biên Phủ toàn thắng"],["2 tháng 9 năm 1945","Đọc Tuyên ngôn Độc lập"]],explain:"Các mốc thời gian quan trọng."},{id:"sd5-dien-bien-phu-29",type:"multi",q:"Phát biểu nào đúng về chiến dịch Điện Biên Phủ?",options:["Kéo dài 56 ngày đêm","Kết thúc ngày 7 tháng 5 năm 1954","Đánh quân Thanh","Đại tướng Võ Nguyên Giáp chỉ huy"],answers:[0,1,3],explain:"Ở Điện Biên Phủ ta đánh thực dân Pháp, không phải quân Thanh."},{id:"sd5-dien-bien-phu-30",type:"tf",q:"Trận mở màn chiến dịch Điện Biên Phủ diễn ra ngày 7 tháng 5 năm 1954.",answer:!1,explain:"Chiến dịch mở màn ngày 13 tháng 3 năm 1954; ngày 7 tháng 5 là ngày toàn thắng."},{id:"sd5-dien-bien-phu-31",type:"mc",q:"Điểm giống nhau giữa chiến thắng Bạch Đằng năm 938 và Điện Biên Phủ năm 1954 là:",options:["Đều là trận đánh trên sông lớn","Đều kết thúc ách đô hộ, xâm lược","Đều do Ngô Quyền chỉ huy","Đều đánh thắng quân Thanh"],answer:1,explain:"Năm 938 chấm dứt Bắc thuộc; năm 1954 chấm dứt ách thống trị của thực dân Pháp ở miền Bắc."},{id:"sd5-dien-bien-phu-32",type:"number",q:"Từ ngày 13 tháng 3 đến ngày 7 tháng 5 năm 1954, chiến dịch kéo dài 56 ngày đêm. Đó là bao nhiêu tuần?",answer:8,explain:"56 : 7 = 8 tuần.",unit:"tuần"}]},summary:["Chiến dịch Điện Biên Phủ diễn ra từ 13/3 đến 7/5/1954, kéo dài 56 ngày đêm.","Đại tướng Võ Nguyên Giáp là người chỉ huy chiến dịch.","Chiến thắng buộc Pháp kí Hiệp định Giơ-ne-vơ, kết thúc chiến tranh ở Đông Dương."]}]},{id:"thong-nhat-doi-moi",title:"Thống nhất đất nước và Đổi mới",lessons:[{id:"sd5-giai-phong-mien-nam",title:"Giải phóng miền Nam, thống nhất đất nước năm 1975",weeks:[25,25],learn:[{title:"Đường Trường Sơn",text:"Trong kháng chiến chống Mỹ, cứu nước, đường Trường Sơn (đường Hồ Chí Minh) là con đường chi viện sức người, sức của từ miền Bắc cho chiến trường miền Nam.",example:"🛣️ Trường Sơn"},{title:"Mùa xuân năm 1975",text:"Mùa xuân năm 1975, quân dân ta tiến hành Tổng tiến công và nổi dậy với ba chiến dịch lớn: Tây Nguyên, Huế – Đà Nẵng và chiến dịch Hồ Chí Minh.",example:"🌸 1975"},{title:"Ngày 30 tháng 4 năm 1975",text:"Chiến dịch Hồ Chí Minh bắt đầu ngày 26 tháng 4 năm 1975. Trưa ngày 30 tháng 4 năm 1975, xe tăng quân giải phóng tiến vào Dinh Độc Lập, lá cờ cách mạng tung bay trên nóc dinh. Miền Nam hoàn toàn giải phóng.",example:"🚩 30/4/1975 · Dinh Độc Lập"},{title:"Thống nhất đất nước",text:"Năm 1976, Quốc hội nước Việt Nam thống nhất quyết định đặt tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam; thành phố Sài Gòn – Gia Định được đổi tên là Thành phố Hồ Chí Minh.",example:"🇻🇳 1976"}],practice:[{questions:[{id:"sd5-giai-phong-mien-nam-01",type:"mc",q:"Miền Nam hoàn toàn giải phóng vào ngày nào?",options:["30 tháng 4 năm 1975","7 tháng 5 năm 1954","2 tháng 9 năm 1945","19 tháng 8 năm 1945"],answer:0,explain:"Ngày 30 tháng 4 năm 1975, miền Nam hoàn toàn giải phóng.",emoji:"🚩"},{id:"sd5-giai-phong-mien-nam-02",type:"mc",q:"Chiến dịch cuối cùng giải phóng miền Nam mang tên ai?",options:["Chiến dịch Quang Trung","Chiến dịch Lê Lợi","Chiến dịch Hồ Chí Minh","Chiến dịch Trần Hưng Đạo"],answer:2,explain:"Đó là chiến dịch Hồ Chí Minh lịch sử."},{id:"sd5-giai-phong-mien-nam-03",type:"mc",q:"Xe tăng quân giải phóng tiến vào đâu vào trưa ngày 30 tháng 4 năm 1975?",options:["Dinh Độc Lập","Quảng trường Ba Đình","Bến Nhà Rồng","Đồi A1"],answer:0,explain:"Xe tăng quân giải phóng tiến vào Dinh Độc Lập ở Sài Gòn."},{id:"sd5-giai-phong-mien-nam-04",type:"tf",q:"Đường Trường Sơn còn được gọi là đường Hồ Chí Minh.",answer:!0,explain:"Đường Trường Sơn mang tên Bác Hồ – đường Hồ Chí Minh.",emoji:"🛣️"},{id:"sd5-giai-phong-mien-nam-05",type:"tf",q:"Năm 1976, nước ta có tên là Đại Việt.",answer:!1,explain:"Năm 1976, nước ta có tên là Cộng hòa xã hội chủ nghĩa Việt Nam."},{id:"sd5-giai-phong-mien-nam-06",type:"fill",q:"Thành phố Sài Gòn – Gia Định được đổi tên thành Thành phố Hồ Chí … .",answer:["Minh"],explain:"Từ năm 1976, Sài Gòn – Gia Định mang tên Thành phố Hồ Chí Minh."},{id:"sd5-giai-phong-mien-nam-07",type:"mc",q:"Chiến dịch Hồ Chí Minh bắt đầu vào ngày nào?",options:["30 tháng 4 năm 1975","26 tháng 4 năm 1975","13 tháng 3 năm 1954","2 tháng 9 năm 1945"],answer:1,explain:"Chiến dịch Hồ Chí Minh bắt đầu ngày 26 tháng 4 năm 1975."},{id:"sd5-giai-phong-mien-nam-08",type:"tf",q:"Sau ngày 30 tháng 4 năm 1975, đất nước vẫn bị chia cắt.",answer:!1,explain:"Ngày 30 tháng 4 năm 1975 mở ra thời kì đất nước thống nhất."},{id:"sd5-giai-phong-mien-nam-09",type:"mc",q:"Ngày 30 tháng 4 hằng năm là ngày gì?",options:["Ngày Quốc khánh","Ngày Nhà giáo Việt Nam","Ngày Giải phóng miền Nam","Ngày Quốc tế Thiếu nhi"],answer:2,explain:"Ngày 30 tháng 4 là ngày Giải phóng miền Nam, thống nhất đất nước."}]},{questions:[{id:"sd5-giai-phong-mien-nam-10",type:"order",q:"Sắp xếp các chiến dịch mùa xuân năm 1975 theo thứ tự.",items:["Chiến dịch Tây Nguyên","Chiến dịch Huế – Đà Nẵng","Chiến dịch Hồ Chí Minh"],explain:"Tây Nguyên mở màn, tiếp đến Huế – Đà Nẵng, cuối cùng là chiến dịch Hồ Chí Minh."},{id:"sd5-giai-phong-mien-nam-11",type:"match",q:"Nối năm với sự kiện.",pairs:[["Năm 1945","Cách mạng tháng Tám"],["Năm 1954","Chiến thắng Điện Biên Phủ"],["Năm 1975","Giải phóng miền Nam"],["Năm 1976","Đặt tên nước Cộng hòa xã hội chủ nghĩa Việt Nam"]],explain:"Các mốc lịch sử quan trọng của thế kỉ XX."},{id:"sd5-giai-phong-mien-nam-12",type:"multi",q:"Đường Trường Sơn có vai trò gì?",options:["Chở vũ khí, lương thực vào miền Nam","Đưa bộ đội vào chiến trường","Là đường du lịch thời đó","Nối hậu phương miền Bắc với tiền tuyến miền Nam"],answers:[0,1,3],explain:"Đường Trường Sơn chi viện sức người, sức của cho miền Nam."},{id:"sd5-giai-phong-mien-nam-13",type:"tf",q:"Chiến dịch Hồ Chí Minh kéo dài 5 ngày, từ 26 đến 30 tháng 4 năm 1975.",answer:!0,explain:"Tính cả ngày đầu và ngày cuối, từ 26 đến 30 tháng 4 là 5 ngày."},{id:"sd5-giai-phong-mien-nam-14",type:"mc",q:"Vì sao ngày 30 tháng 4 năm 1975 có ý nghĩa rất lớn?",options:["Thực dân Pháp nổ súng xâm lược nước ta","Bắt đầu cuộc kháng chiến chống Pháp","Kết thúc chiến tranh, đất nước thống nhất","Nhà Nguyễn dời kinh đô về Huế"],answer:2,explain:"Ngày 30 tháng 4 năm 1975 kết thúc kháng chiến chống Mỹ, thống nhất đất nước."},{id:"sd5-giai-phong-mien-nam-15",type:"mc",q:"Dinh Độc Lập nay ở thành phố nào?",options:["Thành phố Hồ Chí Minh","Huế","Hà Nội","Thành phố Đà Nẵng"],answer:0,explain:"Dinh Độc Lập (nay là Hội trường Thống Nhất) ở Thành phố Hồ Chí Minh."},{id:"sd5-giai-phong-mien-nam-16",type:"tf",q:"Kháng chiến chống Mỹ, cứu nước kết thúc bằng chiến thắng Điện Biên Phủ.",answer:!1,explain:"Kháng chiến chống Mỹ kết thúc ngày 30 tháng 4 năm 1975; Điện Biên Phủ năm 1954 là chiến thắng chống Pháp."},{id:"sd5-giai-phong-mien-nam-17",type:"number",q:"Từ năm 1954 đến năm 1975, đất nước bị chia cắt bao nhiêu năm?",answer:21,explain:"1975 − 1954 = 21 năm.",unit:"năm"},{id:"sd5-giai-phong-mien-nam-18",type:"mc",q:"Lá cờ tung bay trên nóc Dinh Độc Lập trưa ngày 30 tháng 4 năm 1975 báo hiệu điều gì?",options:["Chiến dịch Hồ Chí Minh bắt đầu","Chiến dịch Hồ Chí Minh toàn thắng","Ngày khai giảng năm học mới","Ngày Tết Nguyên đán đến"],answer:1,explain:"Lá cờ trên nóc dinh báo hiệu chiến dịch toàn thắng."}]},{questions:[{id:"sd5-giai-phong-mien-nam-19",type:"mc",q:"Gia đình Khoa nghỉ lễ ngày 30 tháng 4 và 1 tháng 5. Ngày 30 tháng 4 nhắc nhớ sự kiện nào?",options:["Cách mạng tháng Tám","Quốc khánh nước ta","Chiến thắng Bạch Đằng","Giải phóng miền Nam"],answer:3,explain:"Ngày 30 tháng 4 năm 1975 là ngày Giải phóng miền Nam."},{id:"sd5-giai-phong-mien-nam-20",type:"tf",q:"Câu “Nam Bắc một nhà” nói lên niềm vui khi đất nước thống nhất.",answer:!0,explain:"Sau năm 1975, nhân dân hai miền được đoàn tụ, sum họp."},{id:"sd5-giai-phong-mien-nam-21",type:"multi",q:"Để tri ân những người đã hi sinh vì Tổ quốc, em có thể làm gì?",options:["Thăm nghĩa trang liệt sĩ","Thăm hỏi gia đình thương binh, liệt sĩ","Đùa nghịch ở nghĩa trang","Tìm hiểu về các anh hùng"],answers:[0,1,3],explain:"Thăm viếng, quan tâm, tìm hiểu là cách tri ân thiết thực."},{id:"sd5-giai-phong-mien-nam-22",type:"mc",q:"Lan tham quan Hội trường Thống Nhất. Trước đây nơi này có tên là gì?",options:["Dinh Độc Lập","Dinh Bảo Đại","Đại Nội","Văn Miếu"],answer:0,explain:"Hội trường Thống Nhất chính là Dinh Độc Lập trước đây."},{id:"sd5-giai-phong-mien-nam-23",type:"number",q:"Năm 2025, nước ta kỉ niệm bao nhiêu năm ngày Giải phóng miền Nam?",answer:50,explain:"2025 − 1975 = 50 năm.",unit:"năm"},{id:"sd5-giai-phong-mien-nam-24",type:"tf",q:"Nghĩa trang liệt sĩ quốc gia Trường Sơn ghi nhớ công ơn những người đã hi sinh trên tuyến đường Trường Sơn.",answer:!0,explain:"Nghĩa trang Trường Sơn là nơi an nghỉ của nhiều liệt sĩ."},{id:"sd5-giai-phong-mien-nam-25",type:"mc",q:"Vì sao bộ đội và thanh niên xung phong trên đường Trường Sơn được nhân dân ghi nhớ?",options:["Vì họ trồng chè trên dãy Trường Sơn","Vì họ đi du lịch qua núi rừng","Vì họ làm đường cao tốc hiện đại","Vì họ vượt gian khổ chi viện miền Nam"],answer:3,explain:"Họ đã hi sinh tuổi xuân để đất nước thống nhất."},{id:"sd5-giai-phong-mien-nam-26",type:"mc",q:"Câu nào đúng về năm 1975 và năm 1976?",options:["1975 đọc Tuyên ngôn Độc lập; 1976 dời đô","1975 giải phóng miền Nam; 1976 đặt tên nước mới","1975 bắt đầu Đổi mới; 1976 gia nhập ASEAN","1975 thắng Điện Biên Phủ; 1976 lập nhà Nguyễn"],answer:1,explain:"Năm 1975 thống nhất về lãnh thổ, năm 1976 thống nhất về nhà nước."}]}],challenge:{questions:[{id:"sd5-giai-phong-mien-nam-27",type:"order",q:"Sắp xếp các sự kiện thế kỉ XX theo thứ tự thời gian.",items:["Thành lập Đảng Cộng sản Việt Nam","Cách mạng tháng Tám","Chiến thắng Điện Biên Phủ","Giải phóng miền Nam","Đặt tên nước Cộng hòa xã hội chủ nghĩa Việt Nam"],explain:"Năm 1930 → 1945 → 1954 → 1975 → 1976."},{id:"sd5-giai-phong-mien-nam-28",type:"match",q:"Nối địa danh với sự kiện.",pairs:[["Quảng trường Ba Đình","Đọc Tuyên ngôn Độc lập"],["Dinh Độc Lập","Giải phóng miền Nam"],["Đồi A1","Chiến dịch Điện Biên Phủ"],["Bến Nhà Rồng","Bác Hồ ra đi tìm đường cứu nước"]],explain:"Mỗi địa danh gắn với một sự kiện lịch sử."},{id:"sd5-giai-phong-mien-nam-29",type:"multi",q:"Phát biểu nào đúng?",options:["Chiến dịch Hồ Chí Minh bắt đầu ngày 26 tháng 4 năm 1975","Đường Trường Sơn còn gọi là đường Hồ Chí Minh","Miền Nam giải phóng năm 1954","Năm 1976 nước ta đặt tên là Cộng hòa xã hội chủ nghĩa Việt Nam"],answers:[0,1,3],explain:"Miền Nam giải phóng năm 1975, không phải năm 1954."},{id:"sd5-giai-phong-mien-nam-30",type:"tf",q:"Chiến dịch Hồ Chí Minh mở màn cuộc Tổng tiến công và nổi dậy mùa xuân năm 1975.",answer:!1,explain:"Chiến dịch Tây Nguyên mở màn; chiến dịch Hồ Chí Minh là chiến dịch cuối cùng."},{id:"sd5-giai-phong-mien-nam-31",type:"number",q:"Từ năm Cách mạng tháng Tám (1945) đến năm giải phóng miền Nam (1975) là bao nhiêu năm?",answer:30,explain:"1975 − 1945 = 30 năm.",unit:"năm"},{id:"sd5-giai-phong-mien-nam-32",type:"mc",q:"Ý nghĩa lớn nhất của đại thắng mùa xuân năm 1975 là:",options:["Đất nước bị chia cắt làm hai","Đất nước độc lập, thống nhất","Mở đầu thời kì Bắc thuộc","Nhà Nguyễn được thành lập"],answer:1,explain:"Đại thắng 1975 thống nhất đất nước, mở ra thời kì mới."}]},summary:["Ngày 30 tháng 4 năm 1975, miền Nam hoàn toàn giải phóng, đất nước thống nhất.","Chiến dịch Hồ Chí Minh là chiến dịch cuối cùng, kết thúc ở Dinh Độc Lập.","Năm 1976, nước ta có tên là Cộng hòa xã hội chủ nghĩa Việt Nam."]},{id:"sd5-doi-moi",title:"Công cuộc Đổi mới từ năm 1986",weeks:[26,26],learn:[{title:"Đổi mới năm 1986",text:"Tháng 12 năm 1986, Đại hội VI của Đảng Cộng sản Việt Nam đề ra đường lối Đổi mới, nhằm đưa đất nước thoát khỏi khó khăn, phát triển kinh tế, nâng cao đời sống nhân dân.",example:"🔄 1986"},{title:"Thành tựu",text:"Từ một nước thiếu lương thực, Việt Nam trở thành một trong những nước xuất khẩu gạo hàng đầu thế giới. Đời sống người dân được cải thiện; đường sá, trường học, bệnh viện được xây dựng nhiều.",example:"🌾 xuất khẩu gạo"},{title:"Hội nhập quốc tế",text:"Năm 1995, Việt Nam gia nhập ASEAN. Năm 2007, Việt Nam trở thành thành viên Tổ chức Thương mại Thế giới (WTO).",example:"🤝 ASEAN 1995 · WTO 2007"}],practice:[{questions:[{id:"sd5-doi-moi-01",type:"mc",q:"Công cuộc Đổi mới ở nước ta bắt đầu từ năm nào?",options:["Năm 1975","Năm 1986","Năm 1995","Năm 2007"],answer:1,explain:"Năm 1986, Đại hội VI của Đảng đề ra đường lối Đổi mới.",emoji:"🔄"},{id:"sd5-doi-moi-02",type:"tf",q:"Sau Đổi mới, Việt Nam trở thành một trong những nước xuất khẩu gạo hàng đầu thế giới.",answer:!0,explain:"Đây là một thành tựu nổi bật của công cuộc Đổi mới.",emoji:"🌾"},{id:"sd5-doi-moi-03",type:"mc",q:"Việt Nam gia nhập ASEAN năm nào?",options:["Năm 1986","Năm 1995","Năm 2007","Năm 1975"],answer:1,explain:"Năm 1995, Việt Nam gia nhập ASEAN."},{id:"sd5-doi-moi-04",type:"mc",q:"Năm 2007, Việt Nam trở thành thành viên của tổ chức nào?",options:["ASEAN","Liên Hợp Quốc","Tổ chức Thương mại Thế giới","Liên minh châu Âu"],answer:2,explain:"Năm 2007, Việt Nam gia nhập WTO."},{id:"sd5-doi-moi-05",type:"tf",q:"Trước Đổi mới, nước ta đã là nước xuất khẩu gạo hàng đầu thế giới.",answer:!1,explain:"Trước Đổi mới, nước ta có lúc thiếu lương thực; sau Đổi mới mới xuất khẩu gạo hàng đầu."},{id:"sd5-doi-moi-06",type:"multi",q:"Đâu là thành tựu của công cuộc Đổi mới?",options:["Đời sống nhân dân được nâng cao","Nhiều đường sá, cầu cống được xây dựng","Xuất khẩu gạo","Đất nước thiếu lương thực trầm trọng hơn"],answers:[0,1,2],explain:"Đổi mới giúp kinh tế phát triển, đời sống được cải thiện."},{id:"sd5-doi-moi-07",type:"fill",q:"Năm 1986, nước ta bắt đầu công cuộc … mới.",answer:["Đổi"],explain:"Đó là công cuộc Đổi mới."},{id:"sd5-doi-moi-08",type:"mc",q:"Đường lối Đổi mới do đâu đề ra?",options:["Hội nghị Diên Hồng","Đại hội VI của Đảng","Liên Hợp Quốc","Hiệp định Giơ-ne-vơ"],answer:1,explain:"Tháng 12 năm 1986, Đại hội VI của Đảng đề ra đường lối Đổi mới."},{id:"sd5-doi-moi-09",type:"tf",q:"Đổi mới chỉ làm thay đổi ở thành phố, không thay đổi ở nông thôn.",answer:!1,explain:"Đổi mới đem lại thay đổi ở cả thành thị và nông thôn."}]},{questions:[{id:"sd5-doi-moi-10",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Thống nhất đất nước","Bắt đầu công cuộc Đổi mới","Gia nhập ASEAN","Gia nhập WTO"],explain:"Năm 1975 → năm 1986 → năm 1995 → năm 2007."},{id:"sd5-doi-moi-11",type:"match",q:"Nối năm với sự kiện.",pairs:[["Năm 1986","Bắt đầu Đổi mới"],["Năm 1995","Gia nhập ASEAN"],["Năm 2007","Gia nhập WTO"]],explain:"Ba mốc quan trọng của thời kì Đổi mới và hội nhập."},{id:"sd5-doi-moi-12",type:"mc",q:"Mục tiêu chính của công cuộc Đổi mới là gì?",options:["Giảm bớt số trường học, bệnh viện","Đóng cửa, không giao lưu với thế giới","Phát triển kinh tế, nâng cao đời sống","Bỏ hoang ruộng đất ở nông thôn"],answer:2,explain:"Đổi mới nhằm đưa đất nước phát triển, nhân dân ấm no."},{id:"sd5-doi-moi-13",type:"tf",q:"Gia nhập ASEAN và WTO giúp Việt Nam mở rộng hợp tác, buôn bán với nhiều nước.",answer:!0,explain:"Hội nhập giúp hàng hóa Việt Nam đến được nhiều nước."},{id:"sd5-doi-moi-14",type:"multi",q:"Biểu hiện nào cho thấy đời sống nhân dân được cải thiện sau Đổi mới?",options:["Nhiều gia đình có nhà ở khang trang","Trẻ em được đến trường đầy đủ hơn","Nhiều nơi có điện, nước sạch","Nhiều người thiếu ăn hơn trước"],answers:[0,1,2],explain:"Sau Đổi mới, đời sống vật chất, tinh thần được nâng lên rõ rệt."},{id:"sd5-doi-moi-15",type:"mc",q:"Trước Đổi mới, nhiều mặt hàng được mua theo:",options:["Thẻ ngân hàng","Tem phiếu","Mạng internet","Ví điện tử"],answer:1,explain:"Thời bao cấp, người dân mua nhiều hàng hóa bằng tem phiếu."},{id:"sd5-doi-moi-16",type:"tf",q:"Năm 1986 là năm nước ta giải phóng miền Nam.",answer:!1,explain:"Giải phóng miền Nam năm 1975; năm 1986 bắt đầu Đổi mới."},{id:"sd5-doi-moi-17",type:"number",q:"Từ năm Đổi mới (1986) đến năm gia nhập WTO (2007) là bao nhiêu năm?",answer:21,explain:"2007 − 1986 = 21 năm.",unit:"năm"},{id:"sd5-doi-moi-18",type:"mc",q:"Mặt hàng nông sản nào nước ta xuất khẩu nhiều?",options:["Gạo, cà phê","Lúa mì","Băng tuyết","Dầu ô liu"],answer:0,explain:"Gạo và cà phê là những nông sản xuất khẩu chủ lực.",emoji:"☕"}]},{questions:[{id:"sd5-doi-moi-19",type:"mc",q:"Ông của Phúc kể: “Ngày xưa mua gạo phải xếp hàng, dùng tem phiếu.” Câu chuyện nói về thời kì nào?",options:["Thời nhà Lý","Sau năm 2007","Trước Đổi mới","Thời Văn Lang"],answer:2,explain:"Thời bao cấp trước Đổi mới, hàng hóa mua bằng tem phiếu."},{id:"sd5-doi-moi-20",type:"tf",q:"Học sinh chăm học, rèn luyện tốt cũng là góp phần xây dựng đất nước.",answer:!0,explain:"Học tập tốt hôm nay là chuẩn bị xây dựng đất nước mai sau."},{id:"sd5-doi-moi-21",type:"multi",q:"Em có thể góp phần xây dựng quê hương bằng việc làm nào?",options:["Học tập chăm chỉ","Giữ gìn vệ sinh nơi ở","Tiết kiệm điện, nước","Phá hoại cây xanh"],answers:[0,1,2],explain:"Những việc nhỏ hằng ngày cũng góp phần xây dựng quê hương."},{id:"sd5-doi-moi-22",type:"mc",q:"Ở quê Chi trước đây đường đất, nay đã có đường bê tông, trường học mới. Điều đó cho thấy:",options:["Quê Chi kém phát triển hơn","Thành tựu của công cuộc Đổi mới","Không có thay đổi","Đất nước đang chiến tranh"],answer:1,explain:"Đường sá, trường học mới là thành quả của Đổi mới."},{id:"sd5-doi-moi-23",type:"tf",q:"Đổi mới giúp Việt Nam có quan hệ với nhiều nước trên thế giới.",answer:!0,explain:"Việt Nam mở rộng quan hệ hữu nghị, hợp tác với nhiều quốc gia."},{id:"sd5-doi-moi-24",type:"number",q:"Từ năm 1986 đến năm 2026 là bao nhiêu năm?",answer:40,explain:"2026 − 1986 = 40 năm.",unit:"năm"},{id:"sd5-doi-moi-25",type:"mc",q:"Vì sao nói Đổi mới là “bước ngoặt” của đất nước?",options:["Vì từ đó chiến tranh bắt đầu","Vì từ đó nước ta mất độc lập","Vì giúp đất nước phát triển mạnh","Vì từ đó kinh đô được dời đi"],answer:2,explain:"Đổi mới thay đổi căn bản cách làm kinh tế, giúp đất nước phát triển."},{id:"sd5-doi-moi-26",type:"mc",q:"Khi đất nước hội nhập, học sinh nên chuẩn bị điều gì?",options:["Học tốt ngoại ngữ, giữ bản sắc","Quên dần tiếng mẹ đẻ","Không cần học hành gì","Chỉ chơi trò chơi điện tử"],answer:0,explain:"Vừa học hỏi thế giới, vừa giữ bản sắc là điều cần thiết."}]}],challenge:{questions:[{id:"sd5-doi-moi-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Cách mạng tháng Tám","Chiến thắng Điện Biên Phủ","Giải phóng miền Nam","Bắt đầu Đổi mới","Gia nhập ASEAN"],explain:"Năm 1945 → 1954 → 1975 → 1986 → 1995."},{id:"sd5-doi-moi-28",type:"match",q:"Nối thời kì với đặc điểm.",pairs:[["Trước Đổi mới","Mua hàng bằng tem phiếu"],["Sau Đổi mới","Xuất khẩu gạo hàng đầu"],["Hội nhập","Gia nhập ASEAN, WTO"]],explain:"Đổi mới làm thay đổi căn bản đời sống đất nước."},{id:"sd5-doi-moi-29",type:"multi",q:"Phát biểu nào đúng về Đổi mới?",options:["Bắt đầu năm 1986","Đời sống nhân dân được nâng cao","Bắt đầu năm 1975","Việt Nam hội nhập quốc tế"],answers:[0,1,3],explain:"Đổi mới bắt đầu năm 1986, không phải năm 1975."},{id:"sd5-doi-moi-30",type:"tf",q:"Việt Nam gia nhập WTO trước khi gia nhập ASEAN.",answer:!1,explain:"Việt Nam gia nhập ASEAN năm 1995, gia nhập WTO năm 2007."},{id:"sd5-doi-moi-31",type:"mc",q:"Nếu không Đổi mới, điều gì có thể xảy ra?",options:["Không có gì khác so với nay","Đất nước giàu lên rất nhanh","Đất nước tiếp tục khó khăn","Có nhiều hàng xuất khẩu hơn"],answer:2,explain:"Đổi mới đã giúp đất nước thoát khỏi khủng hoảng."},{id:"sd5-doi-moi-32",type:"number",q:"Từ năm 1975 đến năm 1986 là bao nhiêu năm?",answer:11,explain:"1986 − 1975 = 11 năm.",unit:"năm"}]},summary:["Năm 1986, nước ta bắt đầu công cuộc Đổi mới.","Việt Nam từ thiếu lương thực trở thành nước xuất khẩu gạo hàng đầu.","Việt Nam hội nhập quốc tế: gia nhập ASEAN (1995), WTO (2007)."]}]},{id:"lang-gieng-asean",title:"Các nước láng giềng và ASEAN",lessons:[{id:"sd5-trung-quoc",title:"Nước láng giềng Trung Quốc",weeks:[27,27],learn:[{title:"Vị trí và dân cư",text:"Trung Quốc nằm ở phía bắc nước ta, có diện tích rất rộng và là một trong những nước đông dân nhất thế giới. Thủ đô là Bắc Kinh.",example:"🇨🇳 Bắc Kinh"},{title:"Thiên nhiên",text:"Trung Quốc có nhiều núi cao, cao nguyên ở phía tây và các đồng bằng rộng ở phía đông. Hai con sông lớn là Hoàng Hà và Trường Giang.",example:"🏔️ tây · 🌾 đông"},{title:"Công trình và phát minh",text:"Vạn Lý Trường Thành là công trình nổi tiếng thế giới. Người Trung Quốc thời xưa đã phát minh ra giấy, la bàn, thuốc súng và kĩ thuật in.",example:"🧱 Vạn Lý Trường Thành · 📜 giấy"}],practice:[{questions:[{id:"sd5-trung-quoc-01",type:"mc",q:"Thủ đô của Trung Quốc là:",options:["Bắc Kinh","Thượng Hải","Viêng Chăn","Phnôm Pênh"],answer:0,explain:"Thủ đô của Trung Quốc là Bắc Kinh.",emoji:"🇨🇳"},{id:"sd5-trung-quoc-02",type:"mc",q:"Trung Quốc nằm ở phía nào của nước ta?",options:["Phía tây","Phía nam","Phía bắc","Phía đông"],answer:2,explain:"Trung Quốc giáp phía bắc nước ta."},{id:"sd5-trung-quoc-03",type:"tf",q:"Trung Quốc là một trong những nước đông dân nhất thế giới.",answer:!0,explain:"Trung Quốc có số dân rất đông, hơn một tỉ người."},{id:"sd5-trung-quoc-04",type:"mc",q:"Công trình nổi tiếng nhất của Trung Quốc là:",options:["Kim tự tháp","Ăng-co Vát","Đấu trường Cô-li-dê","Vạn Lý Trường Thành"],answer:3,explain:"Vạn Lý Trường Thành là bức tường thành dài hàng nghìn cây số.",emoji:"🧱"},{id:"sd5-trung-quoc-05",type:"multi",q:"Người Trung Quốc thời xưa đã phát minh ra những gì?",options:["Giấy","La bàn","Thuốc súng","Điện thoại"],answers:[0,1,2],explain:"Giấy, la bàn, thuốc súng, kĩ thuật in là bốn phát minh nổi tiếng của Trung Quốc thời xưa."},{id:"sd5-trung-quoc-06",type:"fill",q:"Thủ đô của Trung Quốc là Bắc … .",answer:["Kinh"],explain:"Thủ đô của Trung Quốc là Bắc Kinh."},{id:"sd5-trung-quoc-07",type:"tf",q:"Sông Nin và sông Hằng là hai con sông lớn của Trung Quốc.",answer:!1,explain:"Sông Nin ở châu Phi, sông Hằng ở Ấn Độ; hai sông lớn của Trung Quốc là Hoàng Hà và Trường Giang."},{id:"sd5-trung-quoc-08",type:"tf",q:"Trung Quốc là một quốc gia nhỏ, ít dân.",answer:!1,explain:"Trung Quốc có diện tích rất rộng và rất đông dân."},{id:"sd5-trung-quoc-09",type:"mc",q:"Cố Cung (Tử Cấm Thành), cung điện của các hoàng đế xưa, nằm ở thành phố nào?",options:["Thượng Hải","Hồng Kông","Bắc Kinh","Quảng Châu"],answer:2,explain:"Cố Cung nằm ở trung tâm thủ đô Bắc Kinh."}]},{questions:[{id:"sd5-trung-quoc-10",type:"match",q:"Nối thành tựu với nước.",pairs:[["Vạn Lý Trường Thành","Trung Quốc"],["Ăng-co Vát","Campuchia"],["Thạt Luổng","Lào"]],explain:"Mỗi nước láng giềng có công trình nổi tiếng riêng."},{id:"sd5-trung-quoc-11",type:"mc",q:"Địa hình phía tây Trung Quốc chủ yếu là:",options:["Đồng bằng thấp","Núi cao, cao nguyên","Biển và đảo","Đầm lầy rộng lớn"],answer:1,explain:"Phía tây Trung Quốc có nhiều núi cao, cao nguyên."},{id:"sd5-trung-quoc-12",type:"mc",q:"Các đồng bằng rộng lớn của Trung Quốc tập trung ở phía nào?",options:["Phía tây","Giữa sa mạc","Phía bắc lạnh giá","Phía đông"],answer:3,explain:"Phía đông Trung Quốc có nhiều đồng bằng màu mỡ, dân cư đông đúc."},{id:"sd5-trung-quoc-13",type:"tf",q:"Phát minh ra giấy giúp việc ghi chép, lưu giữ kiến thức dễ dàng hơn.",answer:!0,explain:"Giấy giúp con người viết sách, lưu giữ và truyền bá kiến thức.",emoji:"📜"},{id:"sd5-trung-quoc-14",type:"multi",q:"Việt Nam và Trung Quốc có quan hệ như thế nào?",options:["Là hai nước láng giềng","Có biên giới trên đất liền","Hợp tác buôn bán","Cách nhau bởi đại dương"],answers:[0,1,2],explain:"Hai nước là láng giềng, chung biên giới đất liền, hợp tác nhiều mặt."},{id:"sd5-trung-quoc-15",type:"mc",q:"La bàn được dùng để làm gì?",options:["Xác định phương hướng","Đo nhiệt độ","Đo thời gian trong ngày","Đo chiều cao của núi"],answer:0,explain:"La bàn giúp xác định phương hướng khi đi đường, đi biển.",emoji:"🧭"},{id:"sd5-trung-quoc-16",type:"tf",q:"Vạn Lý Trường Thành được xây để phòng thủ, bảo vệ đất nước.",answer:!0,explain:"Bức tường dài được xây qua nhiều thời kì để chống các cuộc tấn công từ phía bắc."},{id:"sd5-trung-quoc-17",type:"mc",q:"Vì sao dân cư Trung Quốc tập trung đông ở phía đông?",options:["Vì có đồng bằng màu mỡ, gần biển","Vì phía đông có nhiều núi cao","Vì phía đông là sa mạc rộng lớn","Vì phía đông lạnh giá quanh năm"],answer:0,explain:"Đồng bằng, khí hậu thuận lợi và gần biển thu hút dân cư."},{id:"sd5-trung-quoc-18",type:"tf",q:"Trung Quốc chỉ có núi, không có đồng bằng.",answer:!1,explain:"Phía đông Trung Quốc có nhiều đồng bằng rộng."}]},{questions:[{id:"sd5-trung-quoc-19",type:"mc",q:"Ngọc muốn tìm hiểu bức tường thành dài nhất thế giới. Ngọc nên tìm về nước nào?",options:["Lào","Ai Cập","Campuchia","Trung Quốc"],answer:3,explain:"Vạn Lý Trường Thành ở Trung Quốc."},{id:"sd5-trung-quoc-20",type:"multi",q:"Phát minh nào của Trung Quốc thời xưa ngày nay vẫn được dùng rộng rãi?",options:["Giấy","La bàn","Kĩ thuật in","Kim tự tháp"],answers:[0,1,2],explain:"Kim tự tháp là công trình của Ai Cập, không phải phát minh của Trung Quốc."},{id:"sd5-trung-quoc-21",type:"tf",q:"Việt Nam và Trung Quốc có đường biên giới trên đất liền.",answer:!0,explain:"Trung Quốc giáp với các tỉnh phía bắc nước ta."},{id:"sd5-trung-quoc-22",type:"mc",q:"Tỉnh nào sau đây của nước ta giáp với Trung Quốc?",options:["Lạng Sơn","Cà Mau","Cần Thơ","Khánh Hòa"],answer:0,explain:"Lạng Sơn là tỉnh biên giới phía bắc, giáp Trung Quốc."},{id:"sd5-trung-quoc-23",type:"mc",q:"Nếu không có giấy, việc học tập ngày xưa sẽ gặp khó khăn gì?",options:["Không có gì thay đổi cả","Việc học sẽ nhanh hơn trước","Khó ghi chép, lưu giữ sách vở","Việc học dễ dàng hơn nhiều"],answer:2,explain:"Giấy giúp ghi chép và làm sách thuận tiện."},{id:"sd5-trung-quoc-24",type:"tf",q:"La bàn được dùng để đo nhiệt độ nước biển.",answer:!1,explain:"La bàn dùng để xác định phương hướng."},{id:"sd5-trung-quoc-25",type:"mc",q:"Điều nào giúp quan hệ Việt Nam – Trung Quốc hữu nghị, ổn định?",options:["Đóng cửa biên giới mãi mãi","Không giao lưu, không qua lại với nhau","Tranh chấp liên tục ở biên giới","Tôn trọng chủ quyền, hợp tác cùng có lợi"],answer:3,explain:"Tôn trọng lẫn nhau và hợp tác là nền tảng của quan hệ láng giềng."},{id:"sd5-trung-quoc-26",type:"multi",q:"Đâu là thông tin đúng về Trung Quốc?",options:["Thủ đô Bắc Kinh","Có sông Hoàng Hà","Không giáp Việt Nam","Có Vạn Lý Trường Thành"],answers:[0,1,3],explain:"Trung Quốc giáp phía bắc Việt Nam."}]}],challenge:{questions:[{id:"sd5-trung-quoc-27",type:"match",q:"Nối nước với thủ đô.",pairs:[["Trung Quốc","Bắc Kinh"],["Lào","Viêng Chăn"],["Campuchia","Phnôm Pênh"],["Việt Nam","Hà Nội"]],explain:"Thủ đô của các nước láng giềng và Việt Nam."},{id:"sd5-trung-quoc-28",type:"multi",q:"Đâu là bốn phát minh nổi tiếng của Trung Quốc thời xưa?",options:["Giấy","La bàn","Thuốc súng","Kĩ thuật in","Bóng đèn điện"],answers:[0,1,2,3],explain:"Bóng đèn điện ra đời muộn hơn rất nhiều, ở phương Tây."},{id:"sd5-trung-quoc-29",type:"tf",q:"Trường Giang là con sông lớn ở Trung Quốc.",answer:!0,explain:"Trường Giang là một trong hai con sông lớn nhất Trung Quốc."},{id:"sd5-trung-quoc-30",type:"mc",q:"Điểm khác nhau về địa hình giữa phía tây và phía đông Trung Quốc là gì?",options:["Phía tây là biển, phía đông là núi cao","Phía tây nhiều núi, phía đông nhiều đồng bằng","Cả phía tây và phía đông đều là sa mạc","Hai phía có địa hình giống hệt nhau"],answer:1,explain:"Địa hình Trung Quốc cao ở phía tây, thấp dần về phía đông."},{id:"sd5-trung-quoc-31",type:"mc",q:"Vì sao sông ở Trung Quốc phần lớn chảy về phía đông?",options:["Vì các con sông chảy ngược dòng","Vì gió luôn thổi từ tây sang đông","Vì phía đông có nhiều núi rất cao","Vì địa hình cao ở tây, thấp dần về đông"],answer:3,explain:"Nước chảy từ nơi cao xuống nơi thấp."},{id:"sd5-trung-quoc-32",type:"tf",q:"Cố Cung ở Bắc Kinh từng là nơi ở của các hoàng đế Trung Quốc.",answer:!0,explain:"Cố Cung (Tử Cấm Thành) là cung điện của các hoàng đế xưa."}]},summary:["Trung Quốc ở phía bắc nước ta, thủ đô là Bắc Kinh.","Trung Quốc rộng lớn, đông dân, có sông Hoàng Hà và Trường Giang.","Vạn Lý Trường Thành, giấy, la bàn là những thành tựu nổi tiếng của Trung Quốc."]},{id:"sd5-lao-campuchia",title:"Nước láng giềng Lào và Campuchia",weeks:[28,28],learn:[{title:"Lào",text:"Lào nằm ở phía tây nước ta, không giáp biển. Địa hình phần lớn là núi và cao nguyên. Thủ đô là Viêng Chăn. Thạt Luổng là công trình nổi tiếng; cố đô Luông Pha-bang là di sản thế giới.",example:"🇱🇦 Viêng Chăn · Thạt Luổng"},{title:"Campuchia",text:"Campuchia nằm ở phía tây nam nước ta, giáp biển. Địa hình chủ yếu là đồng bằng, giữa có Biển Hồ rất rộng. Thủ đô là Phnôm Pênh. Ăng-co Vát là công trình kiến trúc nổi tiếng.",example:"🇰🇭 Phnôm Pênh · Ăng-co Vát"},{title:"Tình hữu nghị",text:"Việt Nam, Lào, Campuchia là ba nước láng giềng trên bán đảo Đông Dương, có truyền thống đoàn kết, giúp đỡ nhau. Sông Mê Công chảy qua cả ba nước.",example:"🤝 Việt – Lào – Campuchia"}],practice:[{questions:[{id:"sd5-lao-campuchia-01",type:"mc",q:"Thủ đô của Lào là:",options:["Viêng Chăn","Phnôm Pênh","Băng Cốc","Bắc Kinh"],answer:0,explain:"Thủ đô của Lào là Viêng Chăn.",emoji:"🇱🇦"},{id:"sd5-lao-campuchia-02",type:"mc",q:"Thủ đô của Campuchia là:",options:["Hà Nội","Viêng Chăn","Phnôm Pênh","Gia-các-ta"],answer:2,explain:"Thủ đô của Campuchia là Phnôm Pênh.",emoji:"🇰🇭"},{id:"sd5-lao-campuchia-03",type:"tf",q:"Lào là quốc gia không giáp biển.",answer:!0,explain:"Lào nằm sâu trong lục địa, không giáp biển."},{id:"sd5-lao-campuchia-04",type:"mc",q:"Công trình kiến trúc nổi tiếng của Campuchia là:",options:["Thạt Luổng","Kim tự tháp","Vạn Lý Trường Thành","Ăng-co Vát"],answer:3,explain:"Ăng-co Vát là quần thể đền nổi tiếng của Campuchia."},{id:"sd5-lao-campuchia-05",type:"mc",q:"Thạt Luổng là công trình nổi tiếng của nước nào?",options:["Campuchia","Lào","Trung Quốc","Thái Lan"],answer:1,explain:"Thạt Luổng ở Viêng Chăn, Lào."},{id:"sd5-lao-campuchia-06",type:"tf",q:"Địa hình Campuchia chủ yếu là núi cao hiểm trở.",answer:!1,explain:"Địa hình Campuchia chủ yếu là đồng bằng, giữa có Biển Hồ."},{id:"sd5-lao-campuchia-07",type:"fill",q:"Sông … Công chảy qua cả Lào, Campuchia và Việt Nam.",answer:["Mê"],explain:"Đó là sông Mê Công."},{id:"sd5-lao-campuchia-08",type:"tf",q:"Campuchia nằm ở phía bắc nước ta.",answer:!1,explain:"Campuchia nằm ở phía tây nam nước ta."},{id:"sd5-lao-campuchia-09",type:"multi",q:"Những nước nào là láng giềng có chung đường biên giới đất liền với Việt Nam?",options:["Lào","Campuchia","Trung Quốc","Nhật Bản"],answers:[0,1,2],explain:"Việt Nam giáp Trung Quốc, Lào, Campuchia trên đất liền."}]},{questions:[{id:"sd5-lao-campuchia-10",type:"match",q:"Nối nước với đặc điểm.",pairs:[["Lào","Không giáp biển, nhiều núi"],["Campuchia","Có Biển Hồ, nhiều đồng bằng"],["Trung Quốc","Rất rộng, đông dân"]],explain:"Mỗi nước láng giềng có đặc điểm tự nhiên riêng."},{id:"sd5-lao-campuchia-11",type:"mc",q:"Biển Hồ ở Campuchia thực chất là:",options:["Một vùng biển nước mặn","Một hồ nước ngọt rất lớn","Một con sông nhỏ, hẹp","Một ngọn núi cao"],answer:1,explain:"Biển Hồ là hồ nước ngọt rất rộng, nhiều cá."},{id:"sd5-lao-campuchia-12",type:"tf",q:"Vì không giáp biển nên Lào thường vận chuyển hàng hóa ra biển qua nước khác, trong đó có Việt Nam.",answer:!0,explain:"Lào có thể dùng cảng biển của Việt Nam để buôn bán với thế giới."},{id:"sd5-lao-campuchia-13",type:"multi",q:"Điểm giống nhau giữa Việt Nam, Lào và Campuchia là gì?",options:["Cùng ở bán đảo Đông Dương","Cùng có sông Mê Công chảy qua","Đều là thành viên ASEAN","Đều không giáp biển"],answers:[0,1,2],explain:"Việt Nam và Campuchia đều giáp biển; chỉ Lào không giáp biển."},{id:"sd5-lao-campuchia-14",type:"mc",q:"Hình ảnh nào có trên quốc kì Campuchia?",options:["Ngôi sao năm cánh","Vạn Lý Trường Thành","Đền Ăng-co Vát","Lá phong"],answer:2,explain:"Quốc kì Campuchia có hình đền Ăng-co Vát."},{id:"sd5-lao-campuchia-15",type:"mc",q:"Ngành nào phát triển ở Lào nhờ có nhiều rừng và sông dốc?",options:["Khai thác gỗ, thủy điện","Đánh bắt hải sản xa bờ","Khai thác dầu trên biển","Du lịch biển"],answer:0,explain:"Lào không có biển nhưng có nhiều rừng và sông để làm thủy điện."},{id:"sd5-lao-campuchia-16",type:"tf",q:"Lào và Campuchia đều giáp biển.",answer:!1,explain:"Chỉ Campuchia giáp biển; Lào không giáp biển."},{id:"sd5-lao-campuchia-17",type:"mc",q:"Cố đô Luông Pha-bang là di sản thế giới thuộc nước nào?",options:["Lào","Campuchia","Thái Lan","Trung Quốc"],answer:0,explain:"Luông Pha-bang là cố đô của Lào."},{id:"sd5-lao-campuchia-18",type:"mc",q:"Ở Campuchia, Biển Hồ đem lại nguồn lợi lớn nào?",options:["Than đá","Cá nước ngọt","Băng tuyết","Dầu mỏ"],answer:1,explain:"Biển Hồ có rất nhiều cá nước ngọt.",emoji:"🐟"}]},{questions:[{id:"sd5-lao-campuchia-19",type:"mc",q:"Nam muốn đến xem quần thể đền đá cổ nổi tiếng nhất Đông Nam Á. Nam nên đến nước nào?",options:["Lào","Ấn Độ","Trung Quốc","Campuchia"],answer:3,explain:"Ăng-co Vát ở Campuchia."},{id:"sd5-lao-campuchia-20",type:"tf",q:"Việt Nam, Lào, Campuchia đã từng giúp đỡ nhau trong đấu tranh giành độc lập.",answer:!0,explain:"Ba nước có truyền thống đoàn kết, giúp đỡ nhau."},{id:"sd5-lao-campuchia-21",type:"multi",q:"Người dân ba nước có thể hợp tác trong việc gì?",options:["Bảo vệ nguồn nước sông Mê Công","Buôn bán, du lịch","Giáo dục, đào tạo","Phá rừng biên giới"],answers:[0,1,2],explain:"Hợp tác bảo vệ môi trường, buôn bán, giáo dục đem lại lợi ích chung."},{id:"sd5-lao-campuchia-22",type:"mc",q:"Vì sao sông Mê Công quan trọng với cả ba nước?",options:["Vì cho nước, cá, phù sa và đường đi lại","Vì sông rất ngắn, chỉ chảy qua một nước","Vì sông đóng băng vào mùa đông","Vì sông chỉ chảy trên đất Lào"],answer:0,explain:"Sông Mê Công nuôi sống hàng triệu người ở các nước."},{id:"sd5-lao-campuchia-23",type:"mc",q:"Tết cổ truyền của Lào và Campuchia thường diễn ra vào tháng mấy dương lịch?",options:["Tháng 1","Tháng 9","Tháng 4","Tháng 12"],answer:2,explain:"Tết cổ truyền của Lào (Bun-pi-mai) và Campuchia (Chôl Chnăm Thmây) vào khoảng giữa tháng 4."},{id:"sd5-lao-campuchia-24",type:"tf",q:"Học sinh Lào, Campuchia sang Việt Nam học tập là một hình thức hợp tác giữa các nước.",answer:!0,explain:"Hợp tác giáo dục giúp tăng thêm tình hữu nghị."},{id:"sd5-lao-campuchia-25",type:"mc",q:"Lào nhiều núi, không giáp biển. Vì vậy, đời sống người dân Lào chủ yếu gắn với:",options:["Đóng tàu biển lớn","Đánh bắt cá ngoài biển","Làm muối ven biển","Nương rẫy, rừng và sông"],answer:3,explain:"Không có biển nên người Lào gắn bó với rừng núi, sông ngòi."},{id:"sd5-lao-campuchia-26",type:"multi",q:"Thông tin nào đúng?",options:["Phnôm Pênh là thủ đô Campuchia","Viêng Chăn là thủ đô Lào","Lào giáp biển","Ăng-co Vát ở Campuchia"],answers:[0,1,3],explain:"Lào không giáp biển."}]}],challenge:{questions:[{id:"sd5-lao-campuchia-27",type:"match",q:"Nối công trình với nước.",pairs:[["Thạt Luổng","Lào"],["Ăng-co Vát","Campuchia"],["Vạn Lý Trường Thành","Trung Quốc"],["Văn Miếu – Quốc Tử Giám","Việt Nam"]],explain:"Mỗi công trình là niềm tự hào của một dân tộc."},{id:"sd5-lao-campuchia-28",type:"multi",q:"Phát biểu nào đúng về Lào và Campuchia?",options:["Đều là láng giềng của Việt Nam","Đều có sông Mê Công chảy qua","Đều có thủ đô là Viêng Chăn","Đều là thành viên ASEAN"],answers:[0,1,3],explain:"Viêng Chăn là thủ đô của Lào; thủ đô Campuchia là Phnôm Pênh."},{id:"sd5-lao-campuchia-29",type:"tf",q:"Lào có biển, Campuchia không có biển.",answer:!1,explain:"Ngược lại: Campuchia giáp biển, Lào không giáp biển."},{id:"sd5-lao-campuchia-30",type:"mc",q:"Vì sao Biển Hồ được gọi là “Biển” dù là hồ nước ngọt?",options:["Vì nước trong hồ rất mặn","Vì hồ rộng mênh mông như biển","Vì hồ nằm sát cạnh biển","Vì trong hồ có cá voi sống"],answer:1,explain:"Biển Hồ rất rộng, nhất là vào mùa mưa."},{id:"sd5-lao-campuchia-31",type:"mc",q:"Bạn Tùng nói: “Việt Nam giáp Lào ở phía đông.” Em sửa lại thế nào?",options:["Không cần sửa","Lào nằm ở phía nam Việt Nam","Lào nằm ở phía bắc Việt Nam","Lào nằm ở phía tây Việt Nam"],answer:3,explain:"Lào ở phía tây Việt Nam, nên Việt Nam ở phía đông Lào."},{id:"sd5-lao-campuchia-32",type:"tf",q:"Ba nước Việt Nam, Lào, Campuchia đều nằm trên bán đảo Đông Dương.",answer:!0,explain:"Bán đảo Đông Dương gồm Việt Nam, Lào, Campuchia và một số nước khác."}]},summary:["Lào không giáp biển, nhiều núi và cao nguyên, thủ đô Viêng Chăn.","Campuchia có đồng bằng, Biển Hồ, đền Ăng-co Vát, thủ đô Phnôm Pênh.","Việt Nam, Lào, Campuchia đoàn kết, hợp tác, cùng phát triển."]},{id:"sd5-asean",title:"Hiệp hội các quốc gia Đông Nam Á (ASEAN)",weeks:[29,29],learn:[{title:"ASEAN ra đời",text:"Hiệp hội các quốc gia Đông Nam Á (ASEAN) được thành lập ngày 8 tháng 8 năm 1967 tại Băng Cốc (Thái Lan), với 5 nước đầu tiên: In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po và Thái Lan.",example:"🤝 8/8/1967"},{title:"Việt Nam trong ASEAN",text:"Ngày 28 tháng 7 năm 1995, Việt Nam trở thành thành viên của ASEAN. Việt Nam tích cực đóng góp để ASEAN đoàn kết, vững mạnh.",example:"🇻🇳 1995"},{title:"Mục tiêu",text:"ASEAN hợp tác để giữ gìn hòa bình, ổn định và cùng phát triển kinh tế, văn hóa, xã hội. Biểu tượng của ASEAN là bó lúa.",example:"🌾 “Một tầm nhìn, một bản sắc, một cộng đồng”"}],practice:[{questions:[{id:"sd5-asean-01",type:"mc",q:"ASEAN được thành lập năm nào?",options:["Năm 1967","Năm 1945","Năm 1995","Năm 2007"],answer:0,explain:"ASEAN thành lập ngày 8 tháng 8 năm 1967.",emoji:"🤝"},{id:"sd5-asean-02",type:"mc",q:"Việt Nam gia nhập ASEAN năm nào?",options:["Năm 1967","Năm 1986","Năm 1995","Năm 2007"],answer:2,explain:"Ngày 28 tháng 7 năm 1995, Việt Nam gia nhập ASEAN."},{id:"sd5-asean-03",type:"tf",q:"ASEAN là tên viết tắt của Hiệp hội các quốc gia Đông Nam Á.",answer:!0,explain:"ASEAN là Hiệp hội các quốc gia Đông Nam Á."},{id:"sd5-asean-04",type:"mc",q:"ASEAN được thành lập tại thành phố nào?",options:["Hà Nội","Phnôm Pênh","Bắc Kinh","Băng Cốc"],answer:3,explain:"ASEAN ra đời tại Băng Cốc, Thái Lan."},{id:"sd5-asean-05",type:"multi",q:"Những nước nào là thành viên ASEAN?",options:["Việt Nam","Thái Lan","Xin-ga-po","Nhật Bản"],answers:[0,1,2],explain:"Nhật Bản ở Đông Á, không phải thành viên ASEAN."},{id:"sd5-asean-06",type:"number",q:"Khi mới thành lập, ASEAN có bao nhiêu nước?",answer:5,explain:"Năm nước đầu tiên: In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po, Thái Lan.",unit:"nước"},{id:"sd5-asean-07",type:"tf",q:"Việt Nam là một trong năm nước sáng lập ASEAN.",answer:!1,explain:"Việt Nam gia nhập năm 1995, không phải nước sáng lập."},{id:"sd5-asean-08",type:"fill",q:"Biểu tượng của ASEAN là bó … .",answer:["lúa"],explain:"Biểu tượng ASEAN là bó lúa, thể hiện sự đoàn kết.",emoji:"🌾"},{id:"sd5-asean-09",type:"mc",q:"ASEAN hợp tác để đạt mục tiêu nào?",options:["Chia rẽ các nước trong khu vực","Gây chiến tranh với các nước khác","Hòa bình, ổn định, cùng phát triển","Đóng cửa biên giới với nhau"],answer:2,explain:"ASEAN hướng đến hòa bình, ổn định, cùng phát triển."}]},{questions:[{id:"sd5-asean-10",type:"order",q:"Sắp xếp theo thứ tự thời gian.",items:["ASEAN thành lập","Việt Nam bắt đầu Đổi mới","Việt Nam gia nhập ASEAN"],explain:"Năm 1967 → năm 1986 → năm 1995."},{id:"sd5-asean-11",type:"match",q:"Nối nước ASEAN với thủ đô.",pairs:[["Thái Lan","Băng Cốc"],["Lào","Viêng Chăn"],["Campuchia","Phnôm Pênh"],["Việt Nam","Hà Nội"]],explain:"Thủ đô một số nước ASEAN."},{id:"sd5-asean-12",type:"multi",q:"Những nước nào là thành viên sáng lập ASEAN?",options:["In-đô-nê-xi-a","Ma-lai-xi-a","Phi-líp-pin","Thái Lan","Việt Nam"],answers:[0,1,2,3],explain:"Năm nước sáng lập là In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po và Thái Lan; Việt Nam gia nhập năm 1995."},{id:"sd5-asean-13",type:"tf",q:"Bó lúa trên biểu tượng ASEAN thể hiện mong muốn các nước gắn bó, đoàn kết với nhau.",answer:!0,explain:"Các nhánh lúa được bó lại thể hiện sự đoàn kết."},{id:"sd5-asean-14",type:"mc",q:"Việc hợp tác trong ASEAN đem lại lợi ích gì cho Việt Nam?",options:["Hạn chế việc học tập ở nước ngoài","Làm Việt Nam bị cô lập với thế giới","Mở rộng buôn bán, du lịch, giao lưu","Không đem lại lợi ích gì"],answer:2,explain:"Hợp tác giúp kinh tế, văn hóa, giáo dục phát triển."},{id:"sd5-asean-15",type:"number",q:"Việt Nam gia nhập ASEAN sau khi ASEAN thành lập bao nhiêu năm?",answer:28,explain:"1995 − 1967 = 28 năm.",unit:"năm"},{id:"sd5-asean-16",type:"tf",q:"Nhật Bản và Hàn Quốc là thành viên của ASEAN.",answer:!1,explain:"ASEAN là tổ chức của các nước Đông Nam Á; Nhật Bản và Hàn Quốc ở Đông Á."},{id:"sd5-asean-17",type:"mc",q:"Phần lớn các nước Đông Nam Á có khí hậu gì?",options:["Nhiệt đới, nóng ẩm","Ôn đới mát mẻ","Hàn đới băng giá","Hoang mạc khô lạnh"],answer:0,explain:"Đông Nam Á nằm trong vùng nhiệt đới, nóng ẩm, mưa nhiều."},{id:"sd5-asean-18",type:"mc",q:"Cây lương thực chính của nhiều nước Đông Nam Á là:",options:["Lúa mì","Lúa gạo","Khoai tây","Lúa mạch"],answer:1,explain:"Lúa gạo là cây lương thực chính ở Đông Nam Á.",emoji:"🍚"}]},{questions:[{id:"sd5-asean-19",type:"mc",q:"Trường Vy tổ chức “Ngày hội ASEAN”. Hoạt động nào phù hợp?",options:["Không tìm hiểu gì về các nước","Chê bai văn hóa của các nước bạn","Chỉ chơi trò chơi điện tử cả ngày","Giới thiệu trang phục, món ăn các nước"],answer:3,explain:"Tìm hiểu văn hóa các nước giúp tăng hiểu biết và tình hữu nghị."},{id:"sd5-asean-20",type:"tf",q:"Khẩu hiệu của ASEAN là “Một tầm nhìn, một bản sắc, một cộng đồng”.",answer:!0,explain:"Khẩu hiệu thể hiện mong muốn các nước cùng chung mục tiêu."},{id:"sd5-asean-21",type:"multi",q:"Học sinh có thể làm gì để tăng tình hữu nghị với bạn bè ASEAN?",options:["Tìm hiểu về đất nước, con người các nước bạn","Học tiếng Anh để giao lưu","Tham gia giao lưu văn hóa","Chế giễu người nước ngoài"],answers:[0,1,2],explain:"Tôn trọng, học hỏi và giao lưu là việc làm tốt."},{id:"sd5-asean-22",type:"mc",q:"Thái Lan là thành viên sáng lập ASEAN. Thủ đô của Thái Lan là:",options:["Băng Cốc","Viêng Chăn","Gia-các-ta","Ma-ni-la"],answer:0,explain:"Băng Cốc là thủ đô của Thái Lan, cũng là nơi ASEAN ra đời."},{id:"sd5-asean-23",type:"tf",q:"Việt Nam gia nhập ASEAN trước khi bắt đầu công cuộc Đổi mới.",answer:!1,explain:"Đổi mới năm 1986; gia nhập ASEAN năm 1995."},{id:"sd5-asean-24",type:"mc",q:"Vì sao các nước Đông Nam Á cần hợp tác với nhau?",options:["Vì các nước không có điểm chung","Vì gần nhau, có nhiều điểm chung","Vì các nước ở rất xa nhau","Vì các nước muốn gây chiến"],answer:1,explain:"Gần gũi về địa lí, văn hóa nên hợp tác đem lại lợi ích chung."},{id:"sd5-asean-25",type:"mc",q:"Thủ đô của In-đô-nê-xi-a là:",options:["Ma-ni-la","Băng Cốc","Viêng Chăn","Gia-các-ta"],answer:3,explain:"Gia-các-ta là thủ đô của In-đô-nê-xi-a."},{id:"sd5-asean-26",type:"multi",q:"Điểm chung về nông nghiệp của nhiều nước Đông Nam Á là:",options:["Trồng lúa nước","Trồng cây nhiệt đới như cà phê, cao su","Trồng lúa mì là chính","Nuôi tuần lộc"],answers:[0,1],explain:"Khí hậu nhiệt đới nóng ẩm hợp với lúa nước và cây nhiệt đới."}]}],challenge:{questions:[{id:"sd5-asean-27",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["ASEAN thành lập","Giải phóng miền Nam","Việt Nam gia nhập ASEAN","Việt Nam gia nhập WTO"],explain:"Năm 1967 → 1975 → 1995 → 2007."},{id:"sd5-asean-28",type:"match",q:"Nối ngày với sự kiện.",pairs:[["8 tháng 8 năm 1967","ASEAN thành lập"],["28 tháng 7 năm 1995","Việt Nam gia nhập ASEAN"],["30 tháng 4 năm 1975","Giải phóng miền Nam"]],explain:"Các mốc thời gian quan trọng."},{id:"sd5-asean-29",type:"tf",q:"Việt Nam là một trong năm nước sáng lập ASEAN.",answer:!1,explain:"Năm nước sáng lập là In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po, Thái Lan; Việt Nam gia nhập năm 1995."},{id:"sd5-asean-30",type:"multi",q:"Phát biểu nào đúng về ASEAN?",options:["Thành lập năm 1967","Biểu tượng là bó lúa","Được thành lập ở Hà Nội","Việt Nam là thành viên"],answers:[0,1,3],explain:"ASEAN ra đời ở Băng Cốc, Thái Lan."},{id:"sd5-asean-31",type:"mc",q:"Ma-ni-la là thủ đô của nước nào?",options:["Ma-lai-xi-a","Xin-ga-po","Thái Lan","Phi-líp-pin"],answer:3,explain:"Ma-ni-la là thủ đô của Phi-líp-pin."},{id:"sd5-asean-32",type:"mc",q:"Hình ảnh bó lúa trên biểu tượng ASEAN gợi điều gì về khu vực?",options:["Khu vực toàn sa mạc khô cằn","Khu vực trồng lúa lâu đời, đoàn kết","Khu vực lạnh giá quanh năm","Khu vực không trồng trọt được gì"],answer:1,explain:"Lúa gắn với đời sống Đông Nam Á; bó lúa tượng trưng cho đoàn kết."}]},summary:["ASEAN thành lập ngày 8 tháng 8 năm 1967.","Việt Nam gia nhập ASEAN ngày 28 tháng 7 năm 1995.","ASEAN hợp tác vì hòa bình, ổn định và cùng phát triển."]}]},{id:"tim-hieu-the-gioi",title:"Tìm hiểu thế giới",lessons:[{id:"sd5-chau-luc-dai-duong",title:"Các châu lục và đại dương trên thế giới",weeks:[30,30],learn:[{title:"Sáu châu lục",text:"Theo cách chia thường dùng ở nước ta, Trái Đất có 6 châu lục: châu Á, châu Âu, châu Phi, châu Mỹ, châu Đại Dương và châu Nam Cực. Việt Nam thuộc châu Á.",example:"🌏 🌍 🌎"},{title:"Đặc điểm nổi bật",text:"Châu Á rộng nhất và đông dân nhất. Châu Đại Dương có diện tích nhỏ nhất. Châu Nam Cực lạnh nhất, quanh năm băng tuyết, không có dân cư sinh sống thường xuyên. Châu Phi có khí hậu nóng, nhiều hoang mạc.",example:"🧊 Nam Cực · 🏜️ châu Phi"},{title:"Các đại dương",text:"Bao quanh các châu lục là các đại dương như Thái Bình Dương, Đại Tây Dương, Ấn Độ Dương, Bắc Băng Dương. Thái Bình Dương rộng nhất; Bắc Băng Dương nhỏ nhất và lạnh giá. Biển Đông thuộc Thái Bình Dương.",example:"🌊 Thái Bình Dương"}],practice:[{questions:[{id:"sd5-chau-luc-dai-duong-01",type:"number",q:"Theo cách chia thường dùng ở nước ta, Trái Đất có bao nhiêu châu lục?",answer:6,explain:"Sáu châu lục: Á, Âu, Phi, Mỹ, Đại Dương, Nam Cực.",unit:"châu lục",emoji:"🌏"},{id:"sd5-chau-luc-dai-duong-02",type:"mc",q:"Việt Nam thuộc châu lục nào?",options:["Châu Âu","Châu Á","Châu Phi","Châu Mỹ"],answer:1,explain:"Việt Nam nằm ở Đông Nam Á, thuộc châu Á."},{id:"sd5-chau-luc-dai-duong-03",type:"mc",q:"Châu lục nào rộng nhất thế giới?",options:["Châu Âu","Châu Phi","Châu Mỹ","Châu Á"],answer:3,explain:"Châu Á có diện tích lớn nhất."},{id:"sd5-chau-luc-dai-duong-04",type:"mc",q:"Đại dương nào rộng nhất thế giới?",options:["Thái Bình Dương","Ấn Độ Dương","Đại Tây Dương","Bắc Băng Dương"],answer:0,explain:"Thái Bình Dương là đại dương rộng nhất.",emoji:"🌊"},{id:"sd5-chau-luc-dai-duong-05",type:"tf",q:"Châu Nam Cực quanh năm băng tuyết, rất lạnh.",answer:!0,explain:"Nam Cực là châu lục lạnh nhất thế giới.",emoji:"🧊"},{id:"sd5-chau-luc-dai-duong-06",type:"mc",q:"Châu lục nào có diện tích nhỏ nhất?",options:["Châu Đại Dương","Châu Âu","Châu Nam Cực","Châu Phi"],answer:0,explain:"Châu Đại Dương có diện tích nhỏ nhất."},{id:"sd5-chau-luc-dai-duong-07",type:"fill",q:"Biển Đông là một bộ phận của … Bình Dương.",answer:["Thái"],explain:"Biển Đông thuộc Thái Bình Dương."},{id:"sd5-chau-luc-dai-duong-08",type:"tf",q:"Châu Phi có khí hậu lạnh giá quanh năm.",answer:!1,explain:"Châu Phi có khí hậu nóng, nhiều hoang mạc.",emoji:"🏜️"},{id:"sd5-chau-luc-dai-duong-09",type:"mc",q:"Đại dương nào nhỏ nhất và lạnh giá?",options:["Thái Bình Dương","Bắc Băng Dương","Ấn Độ Dương","Đại Tây Dương"],answer:1,explain:"Bắc Băng Dương nhỏ nhất, phần lớn bị băng bao phủ."}]},{questions:[{id:"sd5-chau-luc-dai-duong-10",type:"match",q:"Nối châu lục với đặc điểm.",pairs:[["Châu Á","Rộng nhất, đông dân nhất"],["Châu Nam Cực","Lạnh nhất, phủ băng"],["Châu Phi","Khí hậu nóng, nhiều hoang mạc"],["Châu Đại Dương","Diện tích nhỏ nhất"]],explain:"Mỗi châu lục có đặc điểm nổi bật riêng."},{id:"sd5-chau-luc-dai-duong-11",type:"tf",q:"Châu Nam Cực là châu lục đông dân nhất thế giới.",answer:!1,explain:"Châu Nam Cực không có dân cư sinh sống thường xuyên; châu Á đông dân nhất."},{id:"sd5-chau-luc-dai-duong-12",type:"mc",q:"Vì sao châu Nam Cực không có người sinh sống thường xuyên?",options:["Vì quá lạnh, phủ băng","Vì quá nóng, khô hạn","Vì có nhiều rừng rậm","Vì có quá nhiều người"],answer:0,explain:"Khí hậu cực kì lạnh khiến con người khó sinh sống."},{id:"sd5-chau-luc-dai-duong-13",type:"multi",q:"Những đại dương nào sau đây có trên Trái Đất?",options:["Thái Bình Dương","Đại Tây Dương","Ấn Độ Dương","Biển Đông Dương"],answers:[0,1,2],explain:"Biển Đông là biển, không phải đại dương; “Biển Đông Dương” không phải tên đại dương."},{id:"sd5-chau-luc-dai-duong-14",type:"mc",q:"Đại dương nào nằm giữa châu Mỹ và châu Âu, châu Phi?",options:["Thái Bình Dương","Đại Tây Dương","Ấn Độ Dương","Bắc Băng Dương"],answer:1,explain:"Đại Tây Dương ngăn cách châu Mỹ với châu Âu và châu Phi."},{id:"sd5-chau-luc-dai-duong-15",type:"mc",q:"Phần lớn bề mặt Trái Đất được bao phủ bởi:",options:["Đất liền","Rừng rậm nhiệt đới","Băng tuyết","Biển và đại dương"],answer:3,explain:"Biển và đại dương chiếm phần lớn bề mặt Trái Đất."},{id:"sd5-chau-luc-dai-duong-16",type:"tf",q:"Châu Á là châu lục đông dân nhất thế giới.",answer:!0,explain:"Châu Á có nhiều nước đông dân, chiếm hơn một nửa dân số thế giới."},{id:"sd5-chau-luc-dai-duong-17",type:"mc",q:"Trên quả địa cầu, màu xanh dương thường biểu thị:",options:["Núi cao","Hoang mạc","Đồng bằng thấp","Biển và đại dương"],answer:3,explain:"Màu xanh dương thể hiện biển và đại dương."},{id:"sd5-chau-luc-dai-duong-18",type:"mc",q:"Châu Mỹ nổi tiếng với khu rừng rậm nhiệt đới nào?",options:["Rừng Taiga lạnh","Rừng Cúc Phương","Rừng A-ma-dôn","Rừng U Minh"],answer:2,explain:"Rừng A-ma-dôn ở Nam Mỹ là khu rừng rậm nhiệt đới rộng lớn."}]},{questions:[{id:"sd5-chau-luc-dai-duong-19",type:"mc",q:"Thảo muốn tìm hiểu nơi lạnh nhất Trái Đất có loài chim cánh cụt. Thảo nên tìm hiểu về châu lục nào?",options:["Châu Nam Cực","Châu Phi","Châu Á","Châu Đại Dương"],answer:0,explain:"Châu Nam Cực rất lạnh, có nhiều chim cánh cụt.",emoji:"🐧"},{id:"sd5-chau-luc-dai-duong-20",type:"tf",q:"Tàu thuyền từ Việt Nam đi theo Biển Đông có thể ra Thái Bình Dương.",answer:!0,explain:"Biển Đông là một phần của Thái Bình Dương."},{id:"sd5-chau-luc-dai-duong-21",type:"mc",q:"Lạc đà thích nghi tốt với môi trường hoang mạc. Em có thể gặp nhiều lạc đà ở châu lục nào?",options:["Châu Nam Cực","Châu Phi","Châu Đại Dương","Không châu lục nào"],answer:1,explain:"Châu Phi có hoang mạc rộng, lạc đà sống thích nghi tốt.",emoji:"🐪"},{id:"sd5-chau-luc-dai-duong-22",type:"multi",q:"Những châu lục nào giáp Ấn Độ Dương?",options:["Châu Á","Châu Phi","Châu Đại Dương","Châu Nam Mỹ"],answers:[0,1,2],explain:"Ấn Độ Dương nằm giữa châu Phi, châu Á và châu Đại Dương; không giáp châu Mỹ."},{id:"sd5-chau-luc-dai-duong-23",type:"tf",q:"Bạn Hà nói: “Châu Đại Dương rộng hơn châu Á.” Bạn Hà nói đúng.",answer:!1,explain:"Châu Á rộng nhất; châu Đại Dương nhỏ nhất."},{id:"sd5-chau-luc-dai-duong-24",type:"mc",q:"Vì sao cần bảo vệ các đại dương?",options:["Vì đại dương có diện tích rất nhỏ","Vì đại dương không có sinh vật nào sống","Vì đại dương cho thức ăn, điều hòa khí hậu","Vì đại dương không quan trọng với con người"],answer:2,explain:"Đại dương nuôi sống nhiều sinh vật và điều hòa khí hậu."},{id:"sd5-chau-luc-dai-duong-25",type:"mc",q:"Khi đọc bản đồ thế giới, Bình thấy Việt Nam ở rìa phía đông nam của châu lục nào?",options:["Châu Á","Châu Âu","Châu Mỹ","Châu Phi"],answer:0,explain:"Việt Nam nằm ở phía đông nam châu Á, ven Biển Đông."},{id:"sd5-chau-luc-dai-duong-26",type:"tf",q:"Dân số thế giới hiện nay đã vượt 8 tỉ người.",answer:!0,explain:"Dân số thế giới đã vượt mốc 8 tỉ người."}]}],challenge:{questions:[{id:"sd5-chau-luc-dai-duong-27",type:"match",q:"Nối đại dương với đặc điểm.",pairs:[["Thái Bình Dương","Rộng nhất"],["Bắc Băng Dương","Nhỏ nhất, lạnh giá"],["Ấn Độ Dương","Nằm giữa châu Phi, châu Á, châu Đại Dương"],["Đại Tây Dương","Ngăn cách châu Mỹ với châu Âu"]],explain:"Mỗi đại dương có vị trí và đặc điểm riêng."},{id:"sd5-chau-luc-dai-duong-28",type:"multi",q:"Phát biểu nào đúng?",options:["Việt Nam thuộc châu Á","Châu Nam Cực lạnh nhất","Bắc Băng Dương rộng nhất","Châu Á đông dân nhất"],answers:[0,1,3],explain:"Thái Bình Dương rộng nhất; Bắc Băng Dương nhỏ nhất."},{id:"sd5-chau-luc-dai-duong-29",type:"tf",q:"Châu Mỹ và châu Á nằm liền nhau, không có đại dương ngăn cách.",answer:!1,explain:"Châu Mỹ ngăn cách với châu Á bởi Thái Bình Dương."},{id:"sd5-chau-luc-dai-duong-30",type:"mc",q:"Vì sao châu Á đông dân nhất?",options:["Vì có diện tích nhỏ nhất thế giới","Vì phủ toàn băng tuyết quanh năm","Vì rộng lớn, nhiều đồng bằng màu mỡ","Vì không có con sông lớn nào"],answer:2,explain:"Châu Á rộng lớn, có nhiều đồng bằng lớn thuận lợi cho sinh sống."},{id:"sd5-chau-luc-dai-duong-31",type:"order",q:"Sắp xếp các châu lục từ rộng nhất đến nhỏ nhất.",items:["Châu Á","Châu Mỹ","Châu Phi","Châu Đại Dương"],explain:"Châu Á rộng nhất, rồi đến châu Mỹ, châu Phi; châu Đại Dương nhỏ nhất."},{id:"sd5-chau-luc-dai-duong-32",type:"mc",q:"Nếu đi thuyền từ Việt Nam sang châu Phi theo hướng tây, thuyền sẽ đi qua đại dương nào?",options:["Bắc Băng Dương","Đại Tây Dương","Ấn Độ Dương","Không qua đại dương nào"],answer:2,explain:"Từ Đông Nam Á sang châu Phi, tàu đi qua Ấn Độ Dương."}]},summary:["Trái Đất có 6 châu lục; Việt Nam thuộc châu Á.","Châu Á rộng nhất, đông dân nhất; châu Đại Dương nhỏ nhất; châu Nam Cực lạnh nhất.","Thái Bình Dương là đại dương rộng nhất; Biển Đông thuộc Thái Bình Dương."]},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma",title:"Văn minh Ai Cập, Hy Lạp và La Mã cổ đại",weeks:[31,31],learn:[{title:"Ai Cập cổ đại",text:"Văn minh Ai Cập hình thành bên bờ sông Nin, ở châu Phi. Người Ai Cập xây kim tự tháp làm lăng mộ cho các vua (pha-ra-ông), sáng tạo chữ tượng hình và làm giấy từ cây pa-pi-rút.",example:"🔺 kim tự tháp · 🏞️ sông Nin"},{title:"Hy Lạp cổ đại",text:"Người Hy Lạp cổ đại xây đền Pác-tê-nông ở thành A-ten. Thế vận hội Ô-lim-pích ra đời ở Hy Lạp cổ đại.",example:"🏛️ Pác-tê-nông · 🏅 Ô-lim-pích"},{title:"La Mã cổ đại",text:"Người La Mã xây đấu trường Cô-li-dê ở thành Rô-ma (I-ta-li-a), làm nhiều đường sá, cầu dẫn nước. Họ dùng chữ số La Mã và chữ cái La-tinh – loại chữ cái mà chữ Quốc ngữ của ta cũng sử dụng.",example:"🏟️ Cô-li-dê · I V X"}],practice:[{questions:[{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-01",type:"mc",q:"Kim tự tháp là công trình nổi tiếng của nền văn minh nào?",options:["Hy Lạp","La Mã","Ai Cập","Ấn Độ"],answer:2,explain:"Kim tự tháp là công trình của người Ai Cập cổ đại.",emoji:"🔺"},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-02",type:"mc",q:"Văn minh Ai Cập hình thành bên bờ con sông nào?",options:["Sông Nin","Sông Hoàng Hà","Sông Hằng","Sông Mê Công"],answer:0,explain:"Văn minh Ai Cập gắn với sông Nin."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-03",type:"tf",q:"Thế vận hội Ô-lim-pích ra đời ở Hy Lạp cổ đại.",answer:!0,explain:"Thế vận hội Ô-lim-pích có nguồn gốc từ Hy Lạp cổ đại.",emoji:"🏅"},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-04",type:"mc",q:"Đấu trường Cô-li-dê là công trình của người:",options:["Ai Cập","La Mã","Hy Lạp","Trung Quốc"],answer:1,explain:"Đấu trường Cô-li-dê ở Rô-ma, do người La Mã xây dựng.",emoji:"🏟️"},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-05",type:"mc",q:"Đền Pác-tê-nông là công trình nổi tiếng của nước nào?",options:["Campuchia","Ai Cập","Ấn Độ","Hy Lạp"],answer:3,explain:"Đền Pác-tê-nông ở thành A-ten, Hy Lạp.",emoji:"🏛️"},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-06",type:"tf",q:"Chữ tượng hình là sáng tạo của người La Mã.",answer:!1,explain:"Chữ tượng hình là sáng tạo của người Ai Cập cổ đại; người La Mã dùng chữ cái La-tinh."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-07",type:"fill",q:"Kim tự tháp được xây làm lăng mộ cho các vua Ai Cập, gọi là pha-ra-… .",answer:["ông"],explain:"Vua Ai Cập cổ đại gọi là pha-ra-ông."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-08",type:"tf",q:"Đấu trường Cô-li-dê nằm ở Ai Cập.",answer:!1,explain:"Đấu trường Cô-li-dê ở Rô-ma, I-ta-li-a."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-09",type:"mc",q:"Chữ Quốc ngữ của Việt Nam sử dụng loại chữ cái nào?",options:["Chữ cái La-tinh","Chữ tượng hình","Chữ Phạn","Chữ Hán"],answer:0,explain:"Chữ Quốc ngữ dùng chữ cái La-tinh, có thêm dấu."}]},{questions:[{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-10",type:"match",q:"Nối công trình với nền văn minh.",pairs:[["Kim tự tháp","Ai Cập"],["Đền Pác-tê-nông","Hy Lạp"],["Đấu trường Cô-li-dê","La Mã"],["Vạn Lý Trường Thành","Trung Quốc"]],explain:"Mỗi công trình là biểu tượng của một nền văn minh."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-11",type:"mc",q:"Vì sao sông Nin quan trọng với người Ai Cập cổ đại?",options:["Vì sông không có nước, dễ xây nhà","Vì sông đóng băng, dễ đi lại trên mặt","Vì sông chảy qua nhiều núi tuyết cao","Vì cho nước và phù sa giữa hoang mạc"],answer:3,explain:"Ai Cập phần lớn là hoang mạc; sông Nin mang nước và phù sa nuôi sống cư dân."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-12",type:"number",q:"Chữ số La Mã X có giá trị bằng bao nhiêu?",answer:10,explain:"Trong chữ số La Mã, X là 10."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-13",type:"number",q:"Chữ số La Mã V có giá trị bằng bao nhiêu?",answer:5,explain:"Trong chữ số La Mã, V là 5."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-14",type:"tf",q:"Ngày nay, mặt đồng hồ đôi khi vẫn ghi giờ bằng chữ số La Mã.",answer:!0,explain:"Chữ số La Mã vẫn được dùng trên đồng hồ, đánh số chương sách.",emoji:"🕰️"},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-15",type:"multi",q:"Thành tựu nào thuộc văn minh Ai Cập cổ đại?",options:["Kim tự tháp","Chữ tượng hình","Giấy pa-pi-rút","Đền Pác-tê-nông"],answers:[0,1,2],explain:"Đền Pác-tê-nông thuộc Hy Lạp."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-16",type:"mc",q:"Người Ai Cập làm giấy từ đâu?",options:["Từ cây pa-pi-rút ven sông Nin","Từ vỏ cây thông trên núi","Từ những phiến đá mỏng","Từ lá cây cọ khô"],answer:0,explain:"Cây pa-pi-rút mọc ven sông Nin được dùng làm giấy."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-17",type:"tf",q:"Thế vận hội Ô-lim-pích ngày nay vẫn được tổ chức, quy tụ vận động viên nhiều nước.",answer:!0,explain:"Thế vận hội hiện đại kế thừa tinh thần Thế vận hội cổ đại Hy Lạp."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-18",type:"mc",q:"Người La Mã nổi tiếng xây dựng công trình nào phục vụ đời sống?",options:["Đền Ăng-co bằng đá","Kim tự tháp bằng đá","Vạn Lý Trường Thành","Đường sá và cầu dẫn nước"],answer:3,explain:"Người La Mã xây nhiều đường sá, cầu dẫn nước vào thành phố."}]},{questions:[{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-19",type:"mc",q:"Chương XIV của một cuốn sách là chương thứ mấy?",options:["Chương 12","Chương 14","Chương 16","Chương 9"],answer:1,explain:"X là 10, IV là 4, nên XIV là 14."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-20",type:"number",q:"Số La Mã XII bằng bao nhiêu?",answer:12,explain:"X là 10, II là 2, nên XII là 12."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-21",type:"tf",q:"Ai Cập nằm ở châu Phi.",answer:!0,explain:"Ai Cập ở đông bắc châu Phi."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-22",type:"mc",q:"Hà xem ảnh ngọn lửa Ô-lim-pích được thắp lên trước mỗi kì Thế vận hội. Truyền thống này bắt nguồn từ đâu?",options:["Ai Cập","Trung Quốc","Hy Lạp","Ấn Độ"],answer:2,explain:"Thế vận hội và ngọn lửa Ô-lim-pích gắn với Hy Lạp cổ đại.",emoji:"🔥"},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-23",type:"multi",q:"Vì sao các công trình cổ đại được xem là di sản của nhân loại?",options:["Thể hiện trí tuệ, tài năng của con người thời xưa","Giúp ta hiểu về lịch sử","Vì mới được xây","Có giá trị nghệ thuật cao"],answers:[0,1,3],explain:"Công trình cổ đại có giá trị lịch sử, nghệ thuật lớn."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-24",type:"tf",q:"Người Ai Cập xây kim tự tháp để làm nơi họp chợ.",answer:!1,explain:"Kim tự tháp là lăng mộ của các pha-ra-ông."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-25",type:"mc",q:"Nếu được tham quan cả kim tự tháp và đấu trường Cô-li-dê, Khoa phải đến những nước nào?",options:["Hy Lạp và Trung Quốc","Ai Cập và I-ta-li-a","Ấn Độ và Lào","Campuchia và Thái Lan"],answer:1,explain:"Kim tự tháp ở Ai Cập, đấu trường Cô-li-dê ở Rô-ma, I-ta-li-a."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-26",type:"mc",q:"Chữ cái La-tinh có ảnh hưởng gì đến Việt Nam ngày nay?",options:["Ta hoàn toàn không dùng chữ cái","Không có ảnh hưởng gì đến nước ta","Ta viết bằng chữ tượng hình Ai Cập","Chữ Quốc ngữ dùng chữ cái La-tinh"],answer:3,explain:"Chữ Quốc ngữ được xây dựng trên chữ cái La-tinh."}]}],challenge:{questions:[{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-27",type:"match",q:"Nối nền văn minh với con sông hoặc thành phố gắn bó.",pairs:[["Ai Cập","Sông Nin"],["Hy Lạp","Thành A-ten"],["La Mã","Thành Rô-ma"],["Trung Quốc","Sông Hoàng Hà"]],explain:"Mỗi nền văn minh gắn với một dòng sông hay thành phố nổi tiếng."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-28",type:"number",q:"Số La Mã XX bằng bao nhiêu?",answer:20,explain:"X là 10, XX là 10 + 10 = 20."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-29",type:"multi",q:"Phát biểu nào đúng?",options:["Kim tự tháp ở Ai Cập","Đền Pác-tê-nông ở Hy Lạp","Đấu trường Cô-li-dê ở Trung Quốc","Thế vận hội bắt nguồn từ Hy Lạp"],answers:[0,1,3],explain:"Đấu trường Cô-li-dê ở Rô-ma, I-ta-li-a."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-30",type:"tf",q:"Văn minh Ai Cập phát triển nhờ sông Hằng.",answer:!1,explain:"Văn minh Ai Cập gắn với sông Nin; sông Hằng ở Ấn Độ."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-31",type:"mc",q:"Thế kỉ XXI được viết bằng chữ số La Mã. Thế kỉ đó là thế kỉ thứ mấy?",options:["19","21","20","22"],answer:1,explain:"XX là 20, I là 1, nên XXI là 21."},{id:"sd5-van-minh-ai-cap-hy-lap-la-ma-32",type:"mc",q:"Điều gì giúp người Ai Cập cổ đại xây được kim tự tháp đồ sộ?",options:["Chỉ cần một người thợ giỏi","Có máy móc hiện đại như ngày nay","Có cần cẩu chạy bằng điện","Hiểu biết toán học, kĩ thuật và nhiều người lao động"],answer:3,explain:"Kiến thức toán học, kĩ thuật và sức lao động lớn đã tạo nên kim tự tháp."}]},summary:["Ai Cập cổ đại: sông Nin, kim tự tháp, chữ tượng hình.","Hy Lạp cổ đại: đền Pác-tê-nông, Thế vận hội Ô-lim-pích.","La Mã cổ đại: đấu trường Cô-li-dê, chữ số La Mã, chữ cái La-tinh."]},{id:"sd5-van-minh-an-do-trung-quoc",title:"Văn minh Ấn Độ và Trung Quốc cổ đại",weeks:[32,32],learn:[{title:"Ấn Độ cổ đại",text:"Văn minh Ấn Độ hình thành bên lưu vực sông Ấn và sông Hằng. Người Ấn Độ sáng tạo ra hệ chữ số mà ngày nay ta dùng, trong đó có số 0. Phật giáo ra đời ở Ấn Độ.",example:"0 1 2 3 · 🪷"},{title:"Công trình Ấn Độ",text:"Ấn Độ có nhiều đền, chùa, lăng nổi tiếng. Lăng Ta-giơ Ma-han bằng đá cẩm thạch trắng là một kì quan được cả thế giới biết đến.",example:"🕌 Ta-giơ Ma-han"},{title:"Trung Quốc cổ đại",text:"Văn minh Trung Quốc gắn với sông Hoàng Hà và Trường Giang. Người Trung Quốc xây Vạn Lý Trường Thành, sáng tạo chữ Hán và phát minh ra giấy, la bàn, thuốc súng, kĩ thuật in.",example:"🧱 Vạn Lý Trường Thành"}],practice:[{questions:[{id:"sd5-van-minh-an-do-trung-quoc-01",type:"mc",q:"Văn minh Ấn Độ hình thành bên những con sông nào?",options:["Sông Ấn và sông Hằng","Sông Nin","Sông Hồng","Hoàng Hà và Trường Giang"],answer:0,explain:"Văn minh Ấn Độ gắn với sông Ấn và sông Hằng."},{id:"sd5-van-minh-an-do-trung-quoc-02",type:"tf",q:"Phật giáo ra đời ở Ấn Độ.",answer:!0,explain:"Phật giáo ra đời ở Ấn Độ rồi truyền sang nhiều nước.",emoji:"🪷"},{id:"sd5-van-minh-an-do-trung-quoc-03",type:"mc",q:"Người Ấn Độ cổ đại có đóng góp gì cho toán học?",options:["Hệ chữ số có số 0","Chữ số La Mã","Chữ tượng hình","Chiếc bàn tính gỗ"],answer:0,explain:"Hệ chữ số ta dùng ngày nay, có số 0, bắt nguồn từ Ấn Độ."},{id:"sd5-van-minh-an-do-trung-quoc-04",type:"mc",q:"Lăng Ta-giơ Ma-han ở nước nào?",options:["Hy Lạp","Trung Quốc","Ai Cập","Ấn Độ"],answer:3,explain:"Lăng Ta-giơ Ma-han ở Ấn Độ.",emoji:"🕌"},{id:"sd5-van-minh-an-do-trung-quoc-05",type:"mc",q:"Vạn Lý Trường Thành là công trình của nền văn minh nào?",options:["Ấn Độ","Trung Quốc","La Mã","Ai Cập"],answer:1,explain:"Vạn Lý Trường Thành ở Trung Quốc.",emoji:"🧱"},{id:"sd5-van-minh-an-do-trung-quoc-06",type:"tf",q:"Chữ Hán là chữ viết do người Ai Cập sáng tạo.",answer:!1,explain:"Chữ Hán do người Trung Quốc sáng tạo."},{id:"sd5-van-minh-an-do-trung-quoc-07",type:"fill",q:"Văn minh Trung Quốc gắn với sông Hoàng … và sông Trường Giang.",answer:["Hà"],explain:"Đó là sông Hoàng Hà."},{id:"sd5-van-minh-an-do-trung-quoc-08",type:"tf",q:"Lăng Ta-giơ Ma-han được xây bằng gỗ.",answer:!1,explain:"Lăng Ta-giơ Ma-han được xây bằng đá cẩm thạch trắng."},{id:"sd5-van-minh-an-do-trung-quoc-09",type:"multi",q:"Phát minh nào của Trung Quốc cổ đại?",options:["Giấy","La bàn","Kim tự tháp","Kĩ thuật in"],answers:[0,1,3],explain:"Kim tự tháp là công trình của Ai Cập."}]},{questions:[{id:"sd5-van-minh-an-do-trung-quoc-10",type:"match",q:"Nối nền văn minh với thành tựu.",pairs:[["Ấn Độ","Chữ số có số 0"],["Trung Quốc","Giấy, la bàn"],["Ai Cập","Chữ tượng hình"],["La Mã","Chữ cái La-tinh"]],explain:"Mỗi nền văn minh có những đóng góp riêng cho nhân loại."},{id:"sd5-van-minh-an-do-trung-quoc-11",type:"mc",q:"Phật giáo được truyền vào Việt Nam từ rất sớm. Phật giáo bắt nguồn từ nước nào?",options:["Trung Quốc","Ấn Độ","Nhật Bản","Hy Lạp"],answer:1,explain:"Phật giáo ra đời ở Ấn Độ."},{id:"sd5-van-minh-an-do-trung-quoc-12",type:"tf",q:"Champa và Phù Nam chịu ảnh hưởng văn hóa Ấn Độ.",answer:!0,explain:"Chữ viết, tôn giáo, kiến trúc của Champa và Phù Nam chịu ảnh hưởng Ấn Độ."},{id:"sd5-van-minh-an-do-trung-quoc-13",type:"multi",q:"Điểm chung của các nền văn minh cổ đại Ai Cập, Ấn Độ, Trung Quốc là gì?",options:["Đều hình thành bên những con sông lớn","Đều có chữ viết","Đều có những công trình nổi tiếng","Đều ở châu Âu"],answers:[0,1,2],explain:"Các nền văn minh này đều ra đời bên sông lớn, có chữ viết và công trình đồ sộ."},{id:"sd5-van-minh-an-do-trung-quoc-14",type:"mc",q:"Vì sao các nền văn minh cổ đại thường ra đời bên những con sông lớn?",options:["Vì sông ở gần các núi lửa","Vì sông có nhiều băng tuyết","Vì có nước, đất phù sa màu mỡ","Vì ven sông không có người"],answer:2,explain:"Sông cung cấp nước và đất màu mỡ cho nông nghiệp."},{id:"sd5-van-minh-an-do-trung-quoc-15",type:"tf",q:"Số 0 do người La Mã sáng tạo.",answer:!1,explain:"Số 0 trong hệ chữ số ngày nay bắt nguồn từ Ấn Độ; chữ số La Mã không có số 0."},{id:"sd5-van-minh-an-do-trung-quoc-16",type:"mc",q:"Ảnh hưởng của chữ Hán đến Việt Nam thời xưa là gì?",options:["Ta dùng chữ tượng hình của Ai Cập","Không có ảnh hưởng gì đến nước ta","Ông cha ta dùng chữ Hán viết sách, thi cử","Từ xưa ta chỉ dùng chữ cái La-tinh"],answer:2,explain:"Thời phong kiến, chữ Hán được dùng trong sách vở, thi cử ở nước ta."},{id:"sd5-van-minh-an-do-trung-quoc-17",type:"mc",q:"Phát minh nào giúp người đi biển xác định phương hướng?",options:["La bàn","Giấy","Thuốc súng","Kĩ thuật in"],answer:0,explain:"La bàn giúp xác định phương hướng.",emoji:"🧭"},{id:"sd5-van-minh-an-do-trung-quoc-18",type:"mc",q:"Sông Hằng chảy qua nước nào?",options:["Trung Quốc","Ấn Độ","Ai Cập","Hy Lạp"],answer:1,explain:"Sông Hằng là con sông lớn ở Ấn Độ."}]},{questions:[{id:"sd5-van-minh-an-do-trung-quoc-19",type:"mc",q:"Khi viết số 105, em đang dùng thành tựu của nền văn minh nào?",options:["Ai Cập","La Mã","Hy Lạp","Ấn Độ"],answer:3,explain:"Hệ chữ số có số 0 mà ta dùng bắt nguồn từ Ấn Độ."},{id:"sd5-van-minh-an-do-trung-quoc-20",type:"tf",q:"Bia tiến sĩ ở Văn Miếu được khắc bằng chữ Hán.",answer:!0,explain:"Thời phong kiến, nước ta dùng chữ Hán để ghi chép."},{id:"sd5-van-minh-an-do-trung-quoc-21",type:"multi",q:"Thành tựu nào của các nền văn minh cổ đại em vẫn dùng hằng ngày?",options:["Chữ số có số 0","Giấy","Chữ cái La-tinh","Xây kim tự tháp"],answers:[0,1,2],explain:"Ta vẫn dùng chữ số, giấy, chữ cái La-tinh hằng ngày."},{id:"sd5-van-minh-an-do-trung-quoc-22",type:"mc",q:"Phúc muốn giới thiệu công trình bằng đá cẩm thạch trắng nổi tiếng của Ấn Độ. Đó là:",options:["Lăng Ta-giơ Ma-han","Vạn Lý Trường Thành","Kim tự tháp","Đền Pác-tê-nông"],answer:0,explain:"Lăng Ta-giơ Ma-han xây bằng đá cẩm thạch trắng."},{id:"sd5-van-minh-an-do-trung-quoc-23",type:"tf",q:"Nếu không có số 0, việc viết các số như 10, 100 sẽ khó khăn hơn nhiều.",answer:!0,explain:"Số 0 giúp ta viết số theo hàng rất thuận tiện."},{id:"sd5-van-minh-an-do-trung-quoc-24",type:"mc",q:"Vì sao Vạn Lý Trường Thành được xây rất dài?",options:["Để làm đường đua ngựa thật dài","Để phòng thủ biên giới rộng lớn","Để làm khu chợ lớn nhất","Để chắn sóng biển tràn vào"],answer:1,explain:"Bức tường kéo dài để bảo vệ vùng biên giới phía bắc rộng lớn."},{id:"sd5-van-minh-an-do-trung-quoc-25",type:"multi",q:"Văn hóa Ấn Độ đã ảnh hưởng đến những quốc gia cổ nào trên đất nước ta?",options:["Champa","Phù Nam","Văn Lang","Âu Lạc"],answers:[0,1],explain:"Champa và Phù Nam chịu ảnh hưởng văn hóa Ấn Độ."},{id:"sd5-van-minh-an-do-trung-quoc-26",type:"mc",q:"Thái độ đúng khi tìm hiểu văn minh các nước khác là:",options:["Chê bai cái khác mình","Tôn trọng, học hỏi điều hay","Không quan tâm, bỏ qua","Cho rằng chỉ nước mình hay"],answer:1,explain:"Tôn trọng và học hỏi giúp ta hiểu biết rộng hơn."}]}],challenge:{questions:[{id:"sd5-van-minh-an-do-trung-quoc-27",type:"match",q:"Nối nền văn minh với dòng sông.",pairs:[["Ai Cập","Sông Nin"],["Ấn Độ","Sông Hằng"],["Trung Quốc","Sông Hoàng Hà"]],explain:"Các nền văn minh lớn đều gắn với những con sông."},{id:"sd5-van-minh-an-do-trung-quoc-28",type:"match",q:"Nối công trình với nước.",pairs:[["Lăng Ta-giơ Ma-han","Ấn Độ"],["Vạn Lý Trường Thành","Trung Quốc"],["Kim tự tháp","Ai Cập"],["Đền Pác-tê-nông","Hy Lạp"]],explain:"Mỗi công trình là niềm tự hào của một nền văn minh."},{id:"sd5-van-minh-an-do-trung-quoc-29",type:"multi",q:"Phát biểu nào đúng?",options:["Phật giáo ra đời ở Ấn Độ","Giấy do người Trung Quốc phát minh","Số 0 do người Ai Cập sáng tạo","Văn minh Trung Quốc gắn với sông Hoàng Hà"],answers:[0,1,3],explain:"Số 0 trong hệ chữ số ngày nay bắt nguồn từ Ấn Độ."},{id:"sd5-van-minh-an-do-trung-quoc-30",type:"tf",q:"Ấn Độ và Trung Quốc đều nằm ở châu Phi.",answer:!1,explain:"Ấn Độ và Trung Quốc đều thuộc châu Á."},{id:"sd5-van-minh-an-do-trung-quoc-31",type:"mc",q:"Thành tựu nào giúp sách được in nhiều và nhanh hơn?",options:["La bàn","Thuốc súng","Chữ tượng hình","Kĩ thuật in"],answer:3,explain:"Kĩ thuật in giúp làm ra nhiều bản sách."},{id:"sd5-van-minh-an-do-trung-quoc-32",type:"mc",q:"Tại sao nói các nền văn minh cổ đại là tài sản chung của nhân loại?",options:["Vì chỉ một nước được phép sử dụng","Vì thành tựu được nhiều dân tộc dùng","Vì các thành tựu đã bị lãng quên","Vì các thành tựu không có giá trị"],answer:1,explain:"Chữ số, giấy, chữ cái… được cả thế giới sử dụng."}]},summary:["Văn minh Ấn Độ gắn với sông Ấn, sông Hằng; sáng tạo chữ số, có số 0.","Phật giáo ra đời ở Ấn Độ; lăng Ta-giơ Ma-han nổi tiếng thế giới.","Văn minh Trung Quốc: Vạn Lý Trường Thành, chữ Hán, giấy, la bàn."]}]},{id:"the-gioi-xanh",title:"Xây dựng thế giới xanh – sạch – đẹp",lessons:[{id:"sd5-hoa-binh-hop-tac",title:"Xây dựng thế giới hòa bình",weeks:[33,33],learn:[{title:"Liên Hợp Quốc",text:"Liên Hợp Quốc được thành lập năm 1945 để giữ gìn hòa bình, an ninh thế giới và thúc đẩy hợp tác giữa các nước. Việt Nam trở thành thành viên Liên Hợp Quốc năm 1977.",example:"🇺🇳 1945 · 🇻🇳 1977"},{title:"Hợp tác quốc tế",text:"Các nước hợp tác để giải quyết những vấn đề chung như đói nghèo, dịch bệnh, thiên tai, biến đổi khí hậu. Việt Nam cử lực lượng tham gia gìn giữ hòa bình của Liên Hợp Quốc.",example:"🤝 🌍"},{title:"Em góp phần vì hòa bình",text:"Chim bồ câu trắng là biểu tượng của hòa bình. Mỗi học sinh có thể góp phần vì hòa bình bằng cách sống thân thiện, biết lắng nghe, giải quyết bất đồng bằng lời nói ôn hòa.",example:"🕊️"}],practice:[{questions:[{id:"sd5-hoa-binh-hop-tac-01",type:"mc",q:"Biểu tượng của hòa bình là con vật nào?",options:["Đại bàng","Bồ câu trắng","Sư tử","Hổ vằn"],answer:1,explain:"Chim bồ câu trắng là biểu tượng của hòa bình.",emoji:"🕊️"},{id:"sd5-hoa-binh-hop-tac-02",type:"mc",q:"Liên Hợp Quốc được thành lập năm nào?",options:["Năm 1930","Năm 1995","Năm 1967","Năm 1945"],answer:3,explain:"Liên Hợp Quốc ra đời năm 1945."},{id:"sd5-hoa-binh-hop-tac-03",type:"mc",q:"Việt Nam trở thành thành viên Liên Hợp Quốc năm nào?",options:["Năm 1945","Năm 1977","Năm 1975","Năm 1995"],answer:1,explain:"Năm 1977, Việt Nam gia nhập Liên Hợp Quốc."},{id:"sd5-hoa-binh-hop-tac-04",type:"tf",q:"Liên Hợp Quốc có mục tiêu giữ gìn hòa bình và an ninh thế giới.",answer:!0,explain:"Đó là mục tiêu quan trọng nhất của Liên Hợp Quốc.",emoji:"🇺🇳"},{id:"sd5-hoa-binh-hop-tac-05",type:"tf",q:"Chiến tranh mang lại cuộc sống ấm no cho mọi người.",answer:!1,explain:"Chiến tranh gây chết chóc, đau thương, tàn phá cuộc sống."},{id:"sd5-hoa-binh-hop-tac-06",type:"multi",q:"Vấn đề nào cần các nước cùng hợp tác giải quyết?",options:["Biến đổi khí hậu","Dịch bệnh","Đói nghèo","Bài tập về nhà của em"],answers:[0,1,2],explain:"Những vấn đề toàn cầu cần nhiều nước chung tay."},{id:"sd5-hoa-binh-hop-tac-07",type:"fill",q:"Chim bồ câu trắng là biểu tượng của hòa … .",answer:["bình"],explain:"Chim bồ câu trắng tượng trưng cho hòa bình."},{id:"sd5-hoa-binh-hop-tac-08",type:"tf",q:"Việt Nam cử lực lượng tham gia gìn giữ hòa bình của Liên Hợp Quốc.",answer:!0,explain:"Các chiến sĩ mũ nồi xanh Việt Nam đã làm nhiệm vụ ở nhiều nơi."},{id:"sd5-hoa-binh-hop-tac-09",type:"mc",q:"Khi có bất đồng với bạn, em nên làm gì?",options:["Đánh nhau cho xong","Giận dỗi mãi không nói","Nói xấu bạn với lớp","Bình tĩnh nói chuyện"],answer:3,explain:"Giải quyết bằng lời nói ôn hòa là cách sống hòa bình."}]},{questions:[{id:"sd5-hoa-binh-hop-tac-10",type:"order",q:"Sắp xếp các sự kiện theo thứ tự thời gian.",items:["Liên Hợp Quốc ra đời","Việt Nam gia nhập Liên Hợp Quốc","Việt Nam gia nhập ASEAN"],explain:"Năm 1945 → năm 1977 → năm 1995."},{id:"sd5-hoa-binh-hop-tac-11",type:"match",q:"Nối tổ chức với năm Việt Nam gia nhập.",pairs:[["Liên Hợp Quốc","Năm 1977"],["ASEAN","Năm 1995"],["WTO","Năm 2007"]],explain:"Các mốc hội nhập quốc tế của Việt Nam."},{id:"sd5-hoa-binh-hop-tac-12",type:"mc",q:"Vì sao các nước cần hợp tác để chống biến đổi khí hậu?",options:["Vì việc đó không quan trọng","Vì chỉ một nước bị ảnh hưởng","Vì khí hậu ảnh hưởng đến mọi nước","Vì khí hậu không bao giờ thay đổi"],answer:2,explain:"Biến đổi khí hậu là vấn đề chung của cả Trái Đất."},{id:"sd5-hoa-binh-hop-tac-13",type:"tf",q:"Chiến tranh làm nhiều trẻ em mất nhà cửa, không được đến trường.",answer:!0,explain:"Chiến tranh gây hậu quả nặng nề, nhất là với trẻ em."},{id:"sd5-hoa-binh-hop-tac-14",type:"multi",q:"Việc làm nào góp phần xây dựng hòa bình?",options:["Tôn trọng người khác","Giúp đỡ người gặp khó khăn","Bắt nạt bạn yếu hơn","Giao lưu, kết bạn với bạn bè nước ngoài"],answers:[0,1,3],explain:"Tôn trọng, giúp đỡ, giao lưu giúp mọi người gần nhau hơn."},{id:"sd5-hoa-binh-hop-tac-15",type:"mc",q:"Lực lượng gìn giữ hòa bình của Liên Hợp Quốc thường được gọi là:",options:["Đội cứu hỏa","Lực lượng mũ nồi xanh","Đội bóng đá","Đội văn nghệ quốc tế"],answer:1,explain:"Họ đội mũ nồi xanh, giúp giữ hòa bình ở nhiều nơi."},{id:"sd5-hoa-binh-hop-tac-16",type:"tf",q:"Việt Nam là thành viên của Liên Hợp Quốc từ năm 1945.",answer:!1,explain:"Liên Hợp Quốc ra đời năm 1945; Việt Nam gia nhập năm 1977."},{id:"sd5-hoa-binh-hop-tac-17",type:"number",q:"Việt Nam gia nhập Liên Hợp Quốc sau khi tổ chức này ra đời bao nhiêu năm?",answer:32,explain:"1977 − 1945 = 32 năm.",unit:"năm"},{id:"sd5-hoa-binh-hop-tac-18",type:"mc",q:"Khi một nước bị động đất, các nước khác gửi đội cứu hộ sang giúp. Đó là biểu hiện của:",options:["Hợp tác quốc tế","Chiến tranh","Cạnh tranh","Buôn bán kiếm lời"],answer:0,explain:"Giúp đỡ nhau khi hoạn nạn là tinh thần hợp tác quốc tế."}]},{questions:[{id:"sd5-hoa-binh-hop-tac-19",type:"mc",q:"Lớp Lan quyên góp sách vở gửi các bạn ở vùng bị thiên tai. Việc làm này thể hiện điều gì?",options:["Việc không cần thiết","Lãng phí đồ dùng","Tinh thần chia sẻ","Muốn khoe khoang"],answer:2,explain:"Chia sẻ khó khăn là biểu hiện của lòng nhân ái."},{id:"sd5-hoa-binh-hop-tac-20",type:"tf",q:"Dùng vũ lực là cách tốt nhất để giải quyết mâu thuẫn.",answer:!1,explain:"Thương lượng, hòa bình tránh được tổn thất và giữ được tình hữu nghị."},{id:"sd5-hoa-binh-hop-tac-21",type:"multi",q:"Học sinh có thể làm gì để thể hiện tình yêu hòa bình?",options:["Vẽ tranh, viết thư về chủ đề hòa bình","Sống hòa thuận với bạn bè","Chơi trò chơi bạo lực, đánh bạn","Tham gia các hoạt động từ thiện"],answers:[0,1,3],explain:"Những việc làm nhỏ cũng lan tỏa tinh thần hòa bình."},{id:"sd5-hoa-binh-hop-tac-22",type:"mc",q:"Hai bạn tranh nhau một cuốn truyện. Cách giải quyết hòa bình nhất là:",options:["Giật lấy cuốn truyện","Thay phiên nhau đọc","Mách cô để bạn bị phạt","Xé đôi cuốn truyện"],answer:1,explain:"Thay phiên nhau là cách công bằng, giữ được tình bạn."},{id:"sd5-hoa-binh-hop-tac-23",type:"tf",q:"Nhân dân Việt Nam từng chịu nhiều đau thương vì chiến tranh nên càng quý trọng hòa bình.",answer:!0,explain:"Trải qua chiến tranh, nhân dân ta hiểu giá trị của hòa bình."},{id:"sd5-hoa-binh-hop-tac-24",type:"mc",q:"Vì sao cần bảo vệ hòa bình?",options:["Để mọi người sống an toàn, trẻ em được học","Để các nước có cớ gây chiến tranh","Vì hòa bình không cần bảo vệ","Để các nước xa lánh nhau"],answer:0,explain:"Hòa bình là điều kiện để con người sống hạnh phúc."},{id:"sd5-hoa-binh-hop-tac-25",type:"mc",q:"Phúc có bạn qua thư ở Lào. Việc làm này góp phần:",options:["Không có ý nghĩa","Gây mâu thuẫn","Tăng tình hữu nghị","Làm hai nước xa nhau"],answer:2,explain:"Kết bạn quốc tế giúp hiểu và gắn bó với nhau hơn."},{id:"sd5-hoa-binh-hop-tac-26",type:"multi",q:"Việt Nam đóng góp cho hòa bình thế giới bằng cách nào?",options:["Tham gia lực lượng gìn giữ hòa bình","Hợp tác hữu nghị với các nước","Cứu trợ nước bị thiên tai","Gây chiến với nước khác"],answers:[0,1,2],explain:"Việt Nam là thành viên tích cực, có trách nhiệm của cộng đồng quốc tế."}]}],challenge:{questions:[{id:"sd5-hoa-binh-hop-tac-27",type:"order",q:"Sắp xếp các mốc thời gian.",items:["Liên Hợp Quốc ra đời","ASEAN ra đời","Việt Nam gia nhập Liên Hợp Quốc","Việt Nam gia nhập WTO"],explain:"Năm 1945 → năm 1967 → năm 1977 → năm 2007."},{id:"sd5-hoa-binh-hop-tac-28",type:"match",q:"Nối biểu tượng với ý nghĩa.",pairs:[["Chim bồ câu trắng","Hòa bình"],["Bó lúa","ASEAN đoàn kết"],["Mũ nồi xanh","Gìn giữ hòa bình"]],explain:"Mỗi biểu tượng mang một ý nghĩa."},{id:"sd5-hoa-binh-hop-tac-29",type:"multi",q:"Phát biểu nào đúng?",options:["Liên Hợp Quốc ra đời năm 1945","Việt Nam gia nhập Liên Hợp Quốc năm 1977","Việt Nam gia nhập ASEAN năm 1967","Hòa bình cần sự chung tay của mọi người"],answers:[0,1,3],explain:"ASEAN ra đời năm 1967; Việt Nam gia nhập năm 1995."},{id:"sd5-hoa-binh-hop-tac-30",type:"tf",q:"Chỉ người lớn mới có thể góp phần vào hòa bình.",answer:!1,explain:"Trẻ em cũng góp phần bằng cách sống thân thiện, tôn trọng mọi người."},{id:"sd5-hoa-binh-hop-tac-31",type:"mc",q:"Tình huống nào thể hiện hợp tác quốc tế?",options:["Một nước tự làm mọi việc một mình","Hai nước đóng cửa không qua lại","Bác sĩ nhiều nước cùng làm vắc-xin","Các nước tranh chấp lẫn nhau"],answer:2,explain:"Cùng nghiên cứu vắc-xin là hợp tác vì sức khỏe chung."},{id:"sd5-hoa-binh-hop-tac-32",type:"number",q:"Từ năm Việt Nam gia nhập Liên Hợp Quốc (1977) đến năm gia nhập ASEAN (1995) là bao nhiêu năm?",answer:18,explain:"1995 − 1977 = 18 năm.",unit:"năm"}]},summary:["Liên Hợp Quốc ra đời năm 1945; Việt Nam là thành viên từ năm 1977.","Các nước cần hợp tác để giải quyết những vấn đề chung của thế giới.","Mỗi người góp phần giữ hòa bình bằng cách sống thân thiện, tôn trọng nhau."]},{id:"sd5-bao-ve-moi-truong",title:"Chung tay bảo vệ môi trường Trái Đất",weeks:[34,35],learn:[{title:"Môi trường đang bị đe dọa",text:"Rác thải, khói bụi, chặt phá rừng làm môi trường ô nhiễm. Trái Đất đang nóng lên, gây nhiều thiên tai hơn – đó là biến đổi khí hậu.",example:"🏭 💨 🌡️"},{title:"Hành động chung",text:"Nhiều nước cùng tham gia các hoạt động như Giờ Trái Đất (tắt đèn một giờ). Ngày 5 tháng 6 hằng năm là Ngày Môi trường thế giới.",example:"🌍 5/6 · 💡 Giờ Trái Đất"},{title:"Em làm gì?",text:"Tiết kiệm điện, nước; hạn chế đồ nhựa dùng một lần; phân loại rác; trồng và chăm sóc cây xanh.",example:"♻️ 🌱 💧"}],practice:[{questions:[{id:"sd5-bao-ve-moi-truong-01",type:"mc",q:"Ngày Môi trường thế giới là ngày nào?",options:["5 tháng 6","1 tháng 6","2 tháng 9","30 tháng 4"],answer:0,explain:"Ngày 5 tháng 6 hằng năm là Ngày Môi trường thế giới.",emoji:"🌍"},{id:"sd5-bao-ve-moi-truong-02",type:"tf",q:"Chặt phá rừng làm môi trường bị ảnh hưởng xấu.",answer:!0,explain:"Mất rừng gây xói mòn, lũ lụt và làm Trái Đất nóng lên.",emoji:"🌳"},{id:"sd5-bao-ve-moi-truong-03",type:"mc",q:"Trong chiến dịch Giờ Trái Đất, mọi người thường làm gì?",options:["Tắt đèn không cần thiết","Bật thêm đèn cho sáng","Đốt rác ngoài sân","Đi xe máy nhiều hơn"],answer:0,explain:"Tắt đèn một giờ để tiết kiệm năng lượng, bảo vệ môi trường.",emoji:"💡"},{id:"sd5-bao-ve-moi-truong-04",type:"multi",q:"Việc nào giúp bảo vệ môi trường?",options:["Trồng cây xanh","Phân loại rác","Tiết kiệm nước","Vứt rác xuống sông"],answers:[0,1,2],explain:"Trồng cây, phân loại rác, tiết kiệm nước bảo vệ môi trường.",emoji:"♻️"},{id:"sd5-bao-ve-moi-truong-05",type:"tf",q:"Trái Đất đang nóng lên là một biểu hiện của biến đổi khí hậu.",answer:!0,explain:"Nhiệt độ Trái Đất tăng gây nhiều thiên tai hơn.",emoji:"🌡️"},{id:"sd5-bao-ve-moi-truong-06",type:"fill",q:"Phân loại … giúp tái chế và giảm ô nhiễm.",answer:["rác"],explain:"Phân loại rác giúp tái chế, giảm lượng rác chôn lấp."},{id:"sd5-bao-ve-moi-truong-07",type:"tf",q:"Túi ni-lông phân hủy rất nhanh, không gây hại môi trường.",answer:!1,explain:"Túi ni-lông phải rất nhiều năm mới phân hủy, gây ô nhiễm."},{id:"sd5-bao-ve-moi-truong-08",type:"mc",q:"Nguồn nào gây ô nhiễm không khí?",options:["Khói nhà máy, xe cộ","Cây xanh","Nước mưa","Gió thổi từ biển"],answer:0,explain:"Khói nhà máy, xe cộ thải ra nhiều khí độc.",emoji:"🏭"},{id:"sd5-bao-ve-moi-truong-09",type:"mc",q:"Nên dùng gì thay túi ni-lông khi đi chợ?",options:["Thêm nhiều túi ni-lông","Hộp xốp","Làn, giỏ hoặc túi vải","Không mang gì"],answer:2,explain:"Làn, giỏ, túi vải dùng được nhiều lần.",emoji:"🧺"}]},{questions:[{id:"sd5-bao-ve-moi-truong-10",type:"match",q:"Nối hành động với lợi ích.",pairs:[["Trồng cây","Cho bóng mát, không khí trong lành"],["Tắt đèn khi ra khỏi phòng","Tiết kiệm điện"],["Phân loại rác","Dễ tái chế"],["Khóa vòi nước","Tiết kiệm nước"]],explain:"Mỗi việc làm nhỏ đều có ích cho môi trường."},{id:"sd5-bao-ve-moi-truong-11",type:"mc",q:"Vì sao biến đổi khí hậu là vấn đề của cả thế giới?",options:["Vì chỉ ảnh hưởng đến một nước","Vì Trái Đất là ngôi nhà chung","Vì biến đổi khí hậu không có thật","Vì chỉ xảy ra ở châu Nam Cực"],answer:1,explain:"Không khí, đại dương là của chung nên ô nhiễm ở đâu cũng ảnh hưởng mọi nơi."},{id:"sd5-bao-ve-moi-truong-12",type:"tf",q:"Biến đổi khí hậu làm mực nước biển hạ thấp, vùng ven biển an toàn hơn.",answer:!1,explain:"Biến đổi khí hậu làm băng tan, nước biển dâng, đe dọa vùng ven biển."},{id:"sd5-bao-ve-moi-truong-13",type:"multi",q:"Rác nào có thể tái chế?",options:["Chai nhựa","Giấy báo cũ","Lon nhôm","Vỏ rau thối"],answers:[0,1,2],explain:"Vỏ rau là rác hữu cơ, có thể ủ phân; nhựa, giấy, nhôm có thể tái chế."},{id:"sd5-bao-ve-moi-truong-14",type:"mc",q:"Vì sao rừng được gọi là “lá phổi xanh” của Trái Đất?",options:["Vì trong rừng có nhiều nước","Vì rừng có hình giống lá phổi","Vì cây hút khí các-bô-níc, nhả ô-xi","Vì rừng không có cây cối"],answer:2,explain:"Cây xanh làm sạch không khí như lá phổi."},{id:"sd5-bao-ve-moi-truong-15",type:"tf",q:"Tắt đèn khi không dùng chỉ giúp tiết kiệm tiền, không giúp môi trường.",answer:!1,explain:"Tiết kiệm điện giảm khói thải từ nhà máy điện, giúp bảo vệ môi trường."},{id:"sd5-bao-ve-moi-truong-16",type:"mc",q:"Rác thải nhựa trôi ra đại dương gây hại gì?",options:["Làm nước biển sạch hơn","Không gây hại gì cả","Làm chết rùa, cá, chim","Tạo thêm thức ăn cho cá"],answer:2,explain:"Sinh vật biển nuốt phải nhựa hoặc bị mắc kẹt.",emoji:"🐢"},{id:"sd5-bao-ve-moi-truong-17",type:"mc",q:"Vỏ rau, vỏ trái cây nên được xử lí thế nào là tốt nhất?",options:["Ủ làm phân bón","Vứt ra đường cho gọn","Đốt ngay trong nhà","Bỏ xuống ao, hồ"],answer:0,explain:"Rác hữu cơ có thể ủ thành phân bón."},{id:"sd5-bao-ve-moi-truong-18",type:"multi",q:"Đâu là biểu hiện của ô nhiễm môi trường?",options:["Nước sông đen, có mùi hôi","Không khí nhiều khói bụi","Bầu trời trong xanh","Rác thải chất đống"],answers:[0,1,3],explain:"Bầu trời trong xanh là dấu hiệu môi trường tốt."}]},{questions:[{id:"sd5-bao-ve-moi-truong-19",type:"mc",q:"Lớp Minh muốn tham gia Ngày Môi trường thế giới. Hoạt động nào phù hợp nhất?",options:["Phát cốc nhựa cho bạn","Tổ chức đốt pháo hoa","Thả thật nhiều bóng bay","Nhặt rác, trồng cây"],answer:3,explain:"Nhặt rác, trồng cây trực tiếp làm sạch, đẹp môi trường."},{id:"sd5-bao-ve-moi-truong-20",type:"tf",q:"Dùng bình nước cá nhân thay chai nhựa dùng một lần giúp giảm rác thải nhựa.",answer:!0,explain:"Bình nước dùng được lâu, giảm số chai nhựa bị bỏ đi."},{id:"sd5-bao-ve-moi-truong-21",type:"multi",q:"Gia đình có thể tiết kiệm năng lượng bằng cách nào?",options:["Dùng bóng đèn tiết kiệm điện","Tắt thiết bị khi không dùng","Mở tủ lạnh liên tục","Đi xe đạp khi đi gần"],answers:[0,1,3],explain:"Mở tủ lạnh liên tục gây tốn điện."},{id:"sd5-bao-ve-moi-truong-22",type:"mc",q:"Khi thấy bạn vứt rác bừa bãi ở sân trường, Hà nên làm gì?",options:["Nhắc bạn nhặt rác","Vứt rác theo bạn","Làm ngơ, đi tiếp","Mắng bạn thật to"],answer:0,explain:"Nhắc nhở nhẹ nhàng giúp bạn có thói quen tốt."},{id:"sd5-bao-ve-moi-truong-23",type:"tf",q:"Bảo vệ môi trường chỉ là việc của nhà nước, học sinh không cần làm gì.",answer:!1,explain:"Mỗi người, kể cả học sinh, đều có trách nhiệm bảo vệ môi trường."},{id:"sd5-bao-ve-moi-truong-24",type:"mc",q:"Nếu mỗi người dùng ít túi ni-lông hơn, điều gì sẽ xảy ra?",options:["Lượng rác thải tăng nhiều hơn","Rác nhựa giảm, môi trường sạch hơn","Không có gì thay đổi","Biển và sông bẩn hơn"],answer:1,explain:"Việc nhỏ của nhiều người tạo thay đổi lớn."},{id:"sd5-bao-ve-moi-truong-25",type:"mc",q:"Đồng bằng Nam Bộ thấp, ven biển. Biến đổi khí hậu gây nguy cơ gì cho vùng này?",options:["Tuyết rơi dày trên đồng ruộng","Cả vùng biến thành sa mạc","Núi lửa phun trào khắp nơi","Nước biển dâng, nước mặn vào ruộng"],answer:3,explain:"Nước biển dâng làm ngập và nhiễm mặn ruộng đồng."},{id:"sd5-bao-ve-moi-truong-26",type:"multi",q:"Vì sao cần hợp tác quốc tế trong bảo vệ môi trường?",options:["Ô nhiễm không dừng lại ở biên giới","Các nước chia sẻ kinh nghiệm, công nghệ","Một nước tự làm là đủ","Trái Đất là ngôi nhà chung"],answers:[0,1,3],explain:"Môi trường là vấn đề chung nên cần nhiều nước chung tay."}]}],challenge:{questions:[{id:"sd5-bao-ve-moi-truong-27",type:"order",q:"Sắp xếp các bước xử lí chai nhựa đã dùng.",items:["Uống hết nước trong chai","Rửa sạch, làm dẹt chai","Bỏ vào thùng rác tái chế","Chai được đưa đi tái chế thành đồ dùng mới"],explain:"Làm sạch và phân loại đúng giúp tái chế hiệu quả."},{id:"sd5-bao-ve-moi-truong-28",type:"match",q:"Nối loại rác với cách xử lí.",pairs:[["Vỏ trái cây","Ủ làm phân bón"],["Giấy báo cũ","Tái chế"],["Pin hỏng","Thu gom riêng vì độc hại"]],explain:"Phân loại đúng giúp xử lí rác an toàn."},{id:"sd5-bao-ve-moi-truong-29",type:"tf",q:"Pin hỏng nên bỏ chung với rác thường.",answer:!1,explain:"Pin chứa chất độc, cần thu gom riêng."},{id:"sd5-bao-ve-moi-truong-30",type:"multi",q:"Đâu là hậu quả của biến đổi khí hậu?",options:["Thiên tai nhiều hơn","Nước biển dâng","Nắng nóng gay gắt hơn","Không khí trong lành hơn"],answers:[0,1,2],explain:"Biến đổi khí hậu gây nhiều tác hại cho con người."},{id:"sd5-bao-ve-moi-truong-31",type:"mc",q:"Thông điệp nào phù hợp với Ngày Môi trường thế giới?",options:["Hãy xả rác nơi công cộng","Hãy dùng thật nhiều túi ni-lông","Hãy chặt thêm cây","Hãy chung tay vì một Trái Đất xanh"],answer:3,explain:"Thông điệp khuyến khích mọi người bảo vệ môi trường."},{id:"sd5-bao-ve-moi-truong-32",type:"mc",q:"Bạn Khoa nói: “Một mình em tiết kiệm nước thì không thay đổi được gì.” Em đáp thế nào?",options:["Bạn nói đúng, không cần làm gì","Nhiều người cùng làm sẽ thay đổi lớn","Hãy cứ dùng nước thoải mái","Chỉ người lớn mới cần tiết kiệm"],answer:1,explain:"Hành động nhỏ của mỗi người cộng lại tạo nên thay đổi lớn."}]},summary:["Ô nhiễm môi trường và biến đổi khí hậu là vấn đề chung của thế giới.","Ngày 5 tháng 6 là Ngày Môi trường thế giới.","Tiết kiệm, phân loại rác, trồng cây là cách em bảo vệ Trái Đất."]}]}],a={grade:5,subject:n,title:i,review:h,topics:t};export{a as default,g as grade,h as review,n as subject,i as title,t as topics};
